function checkTradesAccess(){
try{
const el=document.getElementById('email');
if(!el)return;
const email=(el.dataset.real||el.value).trim().toLowerCase();
if(!email||!email.includes('@')){window._isPremiumUser=false;return}
// Client-side instant check (for responsiveness)
const showTradesLocal=window.hasTier(email,'trades');
const showPicksLocal=window.hasTier(email,'picks');
const showDreamLocal=window.hasTier(email,'dream');
window._isPremiumUser=showTradesLocal||showDreamLocal||TRADING_ONLY_EMAILS.includes(email);
window._showPicks=showPicksLocal;
window._isDreamUser=showDreamLocal;
window._verifiedEmail=email;  // Store for API calls
_applyPremiumGating(showTradesLocal||showDreamLocal,showPicksLocal,email);
_applyDreamGating(showDreamLocal);
// Server-side verification (authoritative — overrides client)
fetch('/api/auth/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:email})})
.then(function(r){return r.json()})
.then(function(d){
if(d.success){
window._isPremiumUser=d.premium;
window._showPicks=d.premium;
window._isDreamUser=d.dreamAccess||false;
window._verifiedEmail=email;  // Store confirmed email
window._isPdfUser=(email==='vj@vnky.com');
window._isTradingOnly=TRADING_ONLY_EMAILS.includes(email);
if(window._isTradingOnly)window._isPremiumUser=true; // Trading-only gets premium for trading tab
var _pb=document.getElementById('pdfExportBtn');if(_pb)_pb.style.display=window._isPdfUser?'':'none';

// Trading-only restriction
window._isTradingOnly=TRADING_ONLY_EMAILS.includes(email);
if(window._isTradingOnly){
  // Hide all tabs except Overview + Trading
  var _restrictTabs=['proScan','reports','pms','investor','options'];
  _restrictTabs.forEach(function(tid){
    var el2=document.querySelectorAll('[onclick*="'+tid+'"]');
    el2.forEach(function(e){e.style.display='none'});
  });
  // Show trading tab button if not visible
  var _tradingTabBtn=document.getElementById('traderTab');
  if(_tradingTabBtn)_tradingTabBtn.style.display='';
}
_applyPremiumGating(d.premium,d.premium,email);
_applyDreamGating(d.dreamAccess||false);
if(d.premium)console.log('✅ Server verified premium:',email);
if(d.dreamAccess)console.log('🌟 Server verified dream access:',email);
}
}).catch(function(){});
}catch(e){console.warn('checkTradesAccess error:',e)}
}
function _applyPremiumGating(showTrades,showPicks,email){
// CRITICAL: Don't show ANY tab buttons until a report is generated
var _reportShowing=document.getElementById('report')&&document.getElementById('report').classList.contains('show');
if(!_reportShowing)return;

// DECIDE tab — only for premium/trades users
var decideBtn=document.getElementById('tabBtnDecide');
if(decideBtn)decideBtn.style.display=(showTrades&&!TRADING_ONLY_EMAILS.includes(email))?'':'none';

var tradingBtn=document.getElementById('tabBtnTrading');
if(tradingBtn)tradingBtn.style.display=(showTrades||TRADING_ONLY_EMAILS.includes(email))?'':'none';

document.querySelectorAll('.sc[data-tab="smarttrades"]').forEach(function(s){s.style.display=showTrades?'':'none'});
document.querySelectorAll('.sc[data-tab="gems"]').forEach(function(s){s.style.display=showTrades?'':'none'});
document.querySelectorAll('.sc[data-tab="picks"]').forEach(function(s){s.style.display=showPicks?'':'none'});
document.querySelectorAll('.sc[data-tab="funds"]').forEach(function(s){s.style.display=showPicks?'':'none'});
document.querySelectorAll('.sub-nav[data-tab="picks"]').forEach(function(s){s.style.display=showPicks?'':'none'});
if(showTrades){initTradesProtection(email)}
if(showPicks){try{renderPicks('lc')}catch(e){}try{renderFunds('etf_in')}catch(e){}}
// Only re-render tab group sub-nav if report is already visible (not during email typing)
var _rptVis=document.getElementById('report');
if(_rptVis&&_rptVis.classList.contains('show')){
// r63.110.40: never re-route non-premium (public) users to a gated group after analyze —
// that caused the "bounces back to home" symptom. Public users are clamped to Overview/Tools.
var _hasAccess=showTrades||TRADING_ONLY_EMAILS.includes(email);
var _ag=window._activeGroup||'overview';
if(!_hasAccess&&['overview','tools'].indexOf(_ag)<0){_ag='overview';}
window._activeGroup=_ag;
try{if(typeof switchTabGroup==='function'){switchTabGroup(_ag)}}catch(e){}
}
}
