// r62.0: MICRO-CAP HUNTER — Decide tab discovery scanner
// ═══════════════════════════════════════════════════════════════════
window._activeMicroCapHunterTab = false;

// r63.72: Institutional Positioning Scanner — loader
window._positioningCache = null;
window.loadPositioningScanner = function() {
  var deResult = document.getElementById('deResult');
  if (!deResult) return;

  // r63.72.6: If we have cache, just re-render (view mode toggle is a re-render)
  if (window._positioningCache) {
    _renderPositioningPage(window._positioningCache);
    return;
  }

  // Loading state
  deResult.innerHTML = '<div style="padding:60px 20px;text-align:center;font-family:Inter,sans-serif">' +
    '<div style="font-size:32px;margin-bottom:14px">⏳</div>' +
    '<div style="font-size:14px;font-weight:700;color:#0f172a">Computing institutional positioning + Promise scores...</div>' +
    '<div style="font-size:11px;color:#94a3b8;margin-top:8px">Querying ' +
    'all institutional holdings, computing buy/sell splits, fetching live prices — typically 5–15 seconds.</div>' +
    '</div>';

  // r63.72.6: Always fetch full universe; client-side toggles between BEST BETS and ALL
  fetch('/api/positioning-scan?limit=200&min_filer_count=30')
    .then(function(r) { return r.json(); })
    .then(function(d) {
      if (!d.success) {
        deResult.innerHTML = '<div style="padding:60px 20px;text-align:center;color:#dc2626;font-family:Inter,sans-serif">' +
          '<div style="font-size:32px;margin-bottom:14px">⚠️</div>' +
          '<div style="font-size:14px;font-weight:700">Scoring failed</div>' +
          '<div style="font-size:11px;margin-top:8px;color:#94a3b8">' + (d.error || 'unknown') + '</div>' +
          '</div>';
        return;
      }
      window._positioningCache = d;
      _renderPositioningPage(d);
    })
    .catch(function(e) {
      deResult.innerHTML = '<div style="padding:60px 20px;text-align:center;color:#dc2626;font-family:Inter,sans-serif">' +
        '<div style="font-size:32px;margin-bottom:14px">⚠️</div>' +
        '<div style="font-size:14px;font-weight:700">Network error</div>' +
        '<div style="font-size:11px;margin-top:8px">' + e.message + '</div>' +
        '</div>';
    });
};

window._renderPositioningPage = function(d, activeLens) {
  var deResult = document.getElementById('deResult');
  if (!deResult) return;

  // r63.72.10: Active lens determines scoring + columns + sort
  // 'compounder' / 'accumulation' / 'optionality' — pick ONE lens at a time
  var lens = activeLens || window._positioningLens || 'accumulation';
  window._positioningLens = lens;

  var h = '';

  // Header card
  h += '<div style="background:linear-gradient(135deg,#1A3A78,#2563eb);color:#fff;padding:18px 22px;border-radius:12px;margin-bottom:14px;font-family:Inter,sans-serif">';
  h += '<div style="display:flex;align-items:center;gap:10px;margin-bottom:4px">';
  h += '<span style="font-size:22px">🔬</span>';
  h += '<h2 style="margin:0;font-size:17px;font-weight:800;font-family:Sora,sans-serif;letter-spacing:-0.3px">Multibagger Lens Scanner</h2>';
  h += '</div>';
  h += '<div style="font-size:11px;opacity:0.9">Three independent ranking engines · Each lens optimizes for a different thesis · Choose your view, then ranking + columns adapt</div>';
  h += '</div>';

  // r63.72.10: Three-lens toggle (replaces best/all/micro)
  // r63.84.0: Added title attribute tooltips with layman explanations + ensured label
  // and subtitle are visible in BOTH active and inactive states (previous render had
  // visible bug where the active middle card lost its text — see Image 3).
  h += '<div style="display:flex;gap:8px;margin-bottom:12px;flex-wrap:wrap;align-items:center">';
  var lenses = [
    {id:'compounder',  label:'🏛️ COMPOUNDERS',           sub:'Quality + ROIC durability',   color:'#10b981',
      tip:'Compounders — companies with durable Return on Invested Capital and stable margins. The "buy and hold for decades" lens — Buffett, Munger, Asian Paints, HDFC Bank, Nestle India.'},
    {id:'accumulation',label:'💰 INST. ACCUMULATION',    sub:'Smart-money flow + velocity', color:'#1A3A78',
      tip:'Institutional Accumulation — ranks stocks where mutual funds, FIIs, and big institutions are QUIETLY BUYING. Follows the smart money before retail catches on.'},
    {id:'optionality', label:'🚀 ASYMMETRIC OPTIONALITY',sub:'Tech inflection + survival',  color:'#7c3aed',
      tip:'Asymmetric Optionality — small/mid stocks with massive upside if their tech bet works, but enough cash to survive failure. Win 10x, lose 1x. The venture-capital-style lens.'}
  ];
  lenses.forEach(function(L) {
    var isActive = (lens === L.id);
    var bg = isActive ? L.color : '#fff';
    var fg = isActive ? '#fff' : '#374151';
    var bd = isActive ? L.color : '#cbd5e1';
    var subColor = isActive ? 'rgba(255,255,255,0.92)' : '#94a3b8';
    h += '<button onclick="window._positioningLens=\'' + L.id + '\';window._renderPositioningPage(window._positioningCache);" ' +
         'title="' + L.tip.replace(/"/g, '&quot;') + '" ' +
         'style="padding:10px 16px;border-radius:10px;border:1.5px solid ' + bd +
         ';background:' + bg + ';color:' + fg + ';cursor:pointer;font-family:Inter,sans-serif;' +
         'white-space:nowrap;text-align:left;display:inline-flex;flex-direction:column;align-items:flex-start;gap:2px;min-width:200px;' +
         (isActive ? 'box-shadow:0 2px 8px ' + L.color + '40;' : '') +
         '">' +
         '<span style="font-size:12px;font-weight:800;font-family:Sora,sans-serif;color:' + fg + '">' + L.label + '</span>' +
         '<span style="font-size:9px;color:' + subColor + ';font-weight:600">' + L.sub + '</span>' +
         '</button>';
  });
  h += '<div style="margin-left:auto"><button onclick="window._positioningCache=null;loadPositioningScanner();" ' +
       'style="padding:8px 14px;border-radius:6px;background:#fff;border:1px solid #cbd5e1;font-size:10px;font-weight:700;color:#374151;cursor:pointer;font-family:Inter,sans-serif;white-space:nowrap">↻ Refresh</button></div>';
  h += '</div>';

  // r63.72.10: Search bar — using window-scoped function (fixes JS error)
  var searchVal = window._positioningSearch || '';
  h += '<div style="margin-bottom:12px;display:flex;gap:10px;align-items:center">';
  h += '<div style="position:relative;flex:1;max-width:480px">';
  h += '<span style="position:absolute;left:12px;top:50%;transform:translateY(-50%);font-size:14px;color:#94a3b8">🔍</span>';
  h += '<input id="positioningSearchInput" type="text" placeholder="Search ticker or issuer (e.g. POET, MU, SNDK)..." ' +
       'value="' + searchVal.replace(/"/g, '&quot;') + '" ' +
       'oninput="window._positioningSearch=this.value;clearTimeout(window._posSearchT);window._posSearchT=setTimeout(function(){window._renderPositioningPage(window._positioningCache);var i=document.getElementById(\'positioningSearchInput\');if(i){i.focus();i.setSelectionRange(i.value.length,i.value.length);}}, 150);" ' +
       'style="width:100%;padding:10px 12px 10px 36px;border:1px solid #cbd5e1;border-radius:8px;font-size:13px;font-family:Inter,sans-serif;color:#0f172a;outline:none" ' +
       'onfocus="this.style.borderColor=\'#1A3A78\'" onblur="this.style.borderColor=\'#cbd5e1\'">';
  if (searchVal) {
    h += '<button onclick="window._positioningSearch=\'\';window._renderPositioningPage(window._positioningCache);" ' +
         'style="position:absolute;right:8px;top:50%;transform:translateY(-50%);background:none;border:none;font-size:14px;color:#94a3b8;cursor:pointer;padding:4px 8px">✕</button>';
  }
  h += '</div>';
  h += '<div id="positioningMatchCount" style="font-size:11px;color:#64748b;font-family:Inter,sans-serif"></div>';
  h += '</div>';

  // ── Filter & sort by active lens ───────────────────────────────────────
  // Each lens has a different ranking score and minimum-data threshold
  var displayRows = (d.results || []).slice();

  // For each lens, define: which score to sort by, which conviction to use,
  // and what minimum data must be present to include the row
  var lensConfig = {
    compounder: {
      scoreField: 'compounder_score',
      convictionField: 'compounder_conviction',
      requiredField: 'compounder_score',  // must have real fundamentals
      label: 'Quality'
    },
    accumulation: {
      scoreField: 'accumulation_score',
      convictionField: 'accumulation_conviction',
      requiredField: 'accumulation_score',  // 13F-derived, almost always present
      label: 'Flow'
    },
    optionality: {
      scoreField: 'optionality_score_lens',
      convictionField: 'optionality_conviction',
      requiredField: 'optionality_score_lens',
      label: 'Optionality'
    }
  };
  var cfg = lensConfig[lens];

  // Filter: only rows that have a score for the active lens
  displayRows = displayRows.filter(function(r) {
    return r[cfg.requiredField] !== null && r[cfg.requiredField] !== undefined;
  });

  // Apply search filter
  if (searchVal && searchVal.trim()) {
    var q = searchVal.trim().toUpperCase();
    displayRows = displayRows.filter(function(r) {
      return ((r.ticker || '').toUpperCase().indexOf(q) >= 0)
          || ((r.issuer_name || '').toUpperCase().indexOf(q) >= 0);
    });
  }

  // Sort by active lens's primary score (descending)
  displayRows.sort(function(a, b) {
    var av = a[cfg.scoreField] || 0;
    var bv = b[cfg.scoreField] || 0;
    return bv - av;
  });

  // ── Render table ────────────────────────────────────────────────────────
  if (!displayRows || displayRows.length === 0) {
    h += '<div style="padding:60px 20px;text-align:center;color:#94a3b8;font-family:Inter,sans-serif">' +
         '<div style="font-size:32px;margin-bottom:14px">📊</div>' +
         '<div style="font-size:13px">No tickers have data for this lens.</div>' +
         '<div style="font-size:11px;margin-top:8px">' +
         (lens === 'compounder' ? 'Compounders requires fundamentals (ROIC, margins, FCF) — Yahoo Finance may be blocked.' :
          lens === 'optionality' ? 'Optionality requires fundamentals — Yahoo Finance may be blocked.' :
          'Try Refresh — server may be enriching the universe.') +
         '</div></div>';
  } else {
    // r63.84.0: Wyckoff-regime legend so users don\'t have to guess what DISTRIBUTION means.
    // Hover any pill in the REGIME column for a one-line layman explanation; the legend
    // below the table gives the full glossary.
    h += '<details style="margin-bottom:10px;background:#fafbfc;border:1px solid #e2e8f0;border-radius:10px;padding:0;font-family:Inter,sans-serif">';
    h += '<summary style="padding:9px 14px;cursor:pointer;font-size:11px;font-weight:700;color:#1A3A78;list-style:none;display:flex;align-items:center;justify-content:space-between">';
    h += '<span>📖 <strong>What do these labels mean?</strong> <span style="color:#64748b;font-weight:500">— Wyckoff smart-money phases · click to read</span></span>';
    h += '<span style="font-size:12px;color:#94a3b8">▾</span>';
    h += '</summary>';
    h += '<div style="padding:10px 14px 14px;border-top:1px solid #f1f5f9;display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px;font-size:11px">';
    var _legend = [
      {tag:'ACCUMULATION', bg:'#10b981', txt:'Smart money is QUIETLY BUYING. Price looks weak/boring but institutions are loading up. <strong>Bullish setup — best buying zone.</strong>'},
      {tag:'MARKUP',       bg:'#3b82f6', txt:'Uptrend confirmed — price making higher highs. <strong>Ride the trend, buy dips.</strong>'},
      {tag:'DISTRIBUTION', bg:'#dc2626', txt:'Smart money is QUIETLY SELLING to retail. Price looks strong but institutions are exiting. <strong>Bearish — do NOT chase, take profits if holding.</strong>'},
      {tag:'MARKDOWN',     bg:'#7f1d1d', txt:'Downtrend confirmed — sellers in control. <strong>Cash is the safest position. Wait for accumulation to return.</strong>'},
      {tag:'RANGING',      bg:'#e2e8f0', fg:'#475569', txt:'No clear phase — price drifting sideways with no conviction either way. <strong>Wait for a break before committing capital.</strong>'},
    ];
    _legend.forEach(function(L) {
      h += '<div style="display:flex;gap:10px;align-items:flex-start">';
      h += '<span style="flex-shrink:0;padding:3px 8px;border-radius:6px;background:' + L.bg + ';color:' + (L.fg || '#fff') + ';font-size:9px;font-weight:700;font-family:Sora,sans-serif;white-space:nowrap;line-height:1.4">' + L.tag + '</span>';
      h += '<div style="font-size:11px;color:#475569;line-height:1.6">' + L.txt + '</div>';
      h += '</div>';
    });
    h += '<div style="grid-column:1/-1;margin-top:6px;padding:8px 12px;background:#fef3c780;border-radius:6px;font-size:10px;color:#78350f;line-height:1.6"><strong>How to use:</strong> ACCUMULATION + high QUALITY + high OPTIONALITY = strongest BUY signal. DISTRIBUTION + low QUALITY = strongest SELL signal. Verdict column (HIGH / MEDIUM / LOW / AVOID) is the combined conviction.</div>';
    h += '</div></details>';

    h += '<div style="background:#fff;border-radius:10px;overflow:hidden;border:1px solid #e2e8f0;font-family:Inter,sans-serif">';
    h += '<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:11px;min-width:1200px">';

    // 7-column institutional layout per the document
    h += '<thead><tr style="background:#f8fafc;text-align:left;font-family:Sora,sans-serif">';
    var heads = [
      {label:'#',          align:'left',  width:'36px'},
      {label:'STOCK',      align:'left',  width:'auto'},
      {label:'REGIME',     align:'left',  width:'120px', tip:'Wyckoff phase — ACCUMULATION (smart money buying), MARKUP (uptrend), DISTRIBUTION (smart money selling), MARKDOWN (downtrend), RANGING (sideways). Hover any pill for the plain-English meaning.'},
      {label:'FLOW',       align:'right', width:'70px',  tip:'Institutional flow score — buy/sell dominance + ownership velocity'},
      {label:'QUALITY',    align:'right', width:'70px',  tip:'Business durability — ROIC stability, margin floor, FCF consistency'},
      {label:'OPTIONALITY',align:'right', width:'80px',  tip:'Asymmetric upside — R&D intensity, cash, revenue acceleration'},
      {label:'SATURATION', align:'right', width:'80px',  tip:'Institutional crowding — actual filers vs. expected for market cap'},
      {label:'VERDICT',    align:'left',  width:'120px', tip:'Conviction band based on the active lens'},
      {label:'🎯 ACTION',  align:'center',width:'100px', tip:'Plain-English call combining regime + verdict + saturation. BUY = strong setup. WATCH = wait for confirmation. HOLD/TRIM = take some profits. SELL = exit. AVOID = stay away.'},
      {label:'PRICE',      align:'right', width:'82px'},
      {label:'MKT CAP',    align:'right', width:'76px'},
      {label:'52W',        align:'right', width:'70px'},
      {label:'INST B/S',   align:'right', width:'80px',  tip:'Buyers : Sellers in latest quarter'}
    ];
    heads.forEach(function(hh) {
      var tipAttr = hh.tip ? ' title="' + hh.tip + '"' : '';
      h += '<th' + tipAttr + ' style="padding:10px 8px;font-size:9px;letter-spacing:0.6px;color:#64748b;font-weight:800;text-align:' + hh.align + ';width:' + hh.width + '">' + hh.label + '</th>';
    });
    h += '</tr></thead><tbody>';

    // Helper: format a 0-100 score with color, or N/A
    function _scoreCell(v) {
      if (v === null || v === undefined) {
        return '<span style="color:#cbd5e1;font-size:9px">N/A</span>';
      }
      var col = v >= 70 ? '#10b981' : (v >= 50 ? '#3b82f6' : (v >= 30 ? '#f59e0b' : '#dc2626'));
      return '<span style="color:' + col + ';font-weight:700;font-family:IBM Plex Mono,monospace;font-size:12px">' + Math.round(v) + '</span>';
    }

    // Helper: regime badge with layman-friendly tooltip explaining the Wyckoff phase
    // r63.84.0: previously only ACCUMULATION/DISTRIBUTION were styled and bare label rendered.
    // Now every phase has a clear color + hover tooltip in plain English.
    function _regimeBadge(reg) {
      var meta = {
        'ACCUMULATION':  {bg:'#10b981', fg:'#fff',     tip:'Smart money is QUIETLY BUYING — price looks weak but institutions are loading up. Bullish setup.'},
        'MARKUP':        {bg:'#3b82f6', fg:'#fff',     tip:'Uptrend confirmed — price is making higher highs. Ride the trend, buy dips.'},
        'DISTRIBUTION':  {bg:'#dc2626', fg:'#fff',     tip:'Smart money is QUIETLY SELLING to retail — price looks strong but institutions are exiting. Bearish setup — avoid new buys.'},
        'MARKDOWN':      {bg:'#7f1d1d', fg:'#fff',     tip:'Downtrend confirmed — sellers in control. Cash is the safest position.'},
        'RANGING':       {bg:'#e2e8f0', fg:'#475569',  tip:'No clear phase — price drifting sideways. Wait for a break before committing capital.'},
        'NEUTRAL':       {bg:'#e2e8f0', fg:'#475569',  tip:'Indeterminate — insufficient signal strength to call a phase.'},
      };
      var m = meta[reg] || {bg:'#94a3b8', fg:'#fff', tip:reg};
      return '<span title="' + m.tip + '" style="display:inline-block;padding:3px 8px;border-radius:6px;background:' + m.bg + ';color:' + m.fg + ';font-size:9px;font-weight:700;font-family:Sora,sans-serif;white-space:nowrap;cursor:help">' + reg + '</span>';
    }

    // Helper: verdict band
    function _verdictBadge(conv) {
      var bg = '#f1f5f9', fg = '#94a3b8';
      if (conv === 'HIGH') { bg = '#dcfce7'; fg = '#166534'; }
      else if (conv === 'MEDIUM') { bg = '#dbeafe'; fg = '#1e40af'; }
      else if (conv === 'LOW') { bg = '#fef3c7'; fg = '#92400e'; }
      else if (conv === 'AVOID') { bg = '#fee2e2'; fg = '#991b1b'; }
      return '<span style="display:inline-block;padding:3px 8px;border-radius:6px;background:' + bg + ';color:' + fg + ';font-size:9px;font-weight:800;font-family:Sora,sans-serif;white-space:nowrap">' + conv + '</span>';
    }

    // r63.84.0: Plain-English ACTION badge derived from regime + verdict + saturation
    // User asked for "clearly... market trends and check insider activity clearly,
    // institutional ownership during various time frames, volume, and final verdict.
    // like can buy or sell stuff like that". This translates the combined signal
    // into a single buy/wait/sell call the user can act on without learning Wyckoff.
    function _actionBadge(reg, verdict, sat) {
      var action = 'WATCH', color = '#6b7280', tip = 'Mixed signals — wait for clearer setup before acting.';
      var crowded = (sat != null && sat >= 75);   // saturated / over-owned
      var early   = (sat != null && sat <= 30);   // still under-owned

      if (verdict === 'AVOID' || reg === 'MARKDOWN') {
        action = 'AVOID'; color = '#991b1b';
        tip = (reg === 'MARKDOWN')
          ? 'MARKDOWN phase: sellers in control. Bottom not in yet — capital preservation > opportunity.'
          : 'Verdict AVOID — fundamentals fail the active lens. Do not commit capital.';
      } else if (reg === 'DISTRIBUTION') {
        action = (verdict === 'HIGH' || verdict === 'MEDIUM') ? 'SELL' : 'AVOID';
        color = '#dc2626';
        tip = 'DISTRIBUTION: smart money is selling to retail. Price may look strong but institutions are exiting. Exit existing positions; do not chase.';
      } else if (reg === 'ACCUMULATION' && (verdict === 'HIGH' || verdict === 'MEDIUM') && !crowded) {
        action = 'BUY'; color = '#059669';
        tip = 'ACCUMULATION + ' + verdict + ' verdict' + (early ? ' + under-owned' : '') + '. Institutions are quietly loading. Best buying setup.';
      } else if (reg === 'MARKUP' && (verdict === 'HIGH' || verdict === 'MEDIUM')) {
        action = crowded ? 'TRIM' : 'BUY';
        color = crowded ? '#d97706' : '#10b981';
        tip = crowded
          ? 'MARKUP + saturated ownership. Trend intact but late — trim to lock gains; new buys only on dips.'
          : 'MARKUP + ' + verdict + ' verdict. Trend confirmed. Buy dips, ride momentum.';
      } else if (reg === 'RANGING') {
        action = 'WATCH'; color = '#6b7280';
        tip = 'RANGING: no directional conviction. Wait for breakout (ideally into ACCUMULATION) before deploying capital.';
      } else if (verdict === 'LOW') {
        action = 'WATCH'; color = '#92400e';
        tip = 'Low conviction across the active lens. Re-check after next earnings or 13F refresh.';
      } else if (verdict === 'INSUFFICIENT DATA') {
        action = '—'; color = '#cbd5e1';
        tip = 'Insufficient data to make a call — fewer than 2 of the required input metrics returned.';
      }

      return '<span title="' + tip.replace(/"/g, '&quot;') + '" style="display:inline-block;padding:4px 10px;border-radius:6px;background:' + color + ';color:#fff;font-size:10px;font-weight:800;font-family:Sora,sans-serif;white-space:nowrap;letter-spacing:0.4px;cursor:help">' + action + '</span>';
    }

    displayRows.forEach(function(r, i) {
      // Price + change
      var priceStr = (r.price && r.price > 0) ? '$' + r.price.toFixed(2) : '<span style="color:#cbd5e1">—</span>';
      var changeStr = '';
      if (r.price && r.price > 0 && r.change_pct !== undefined && r.change_pct !== null) {
        var chCol = r.change_pct >= 0 ? '#10b981' : '#dc2626';
        changeStr = '<div style="font-size:9px;color:' + chCol + ';margin-top:2px">' +
                    (r.change_pct >= 0 ? '+' : '') + r.change_pct.toFixed(2) + '%</div>';
      }

      // Market cap
      var mcapStr = '<span style="color:#cbd5e1">—</span>';
      if (r.market_cap && r.market_cap > 0) {
        var mb = r.market_cap / 1e9;
        if (mb >= 100) mcapStr = '$' + mb.toFixed(0) + 'B';
        else if (mb >= 1) mcapStr = '$' + mb.toFixed(1) + 'B';
        else mcapStr = '$' + (r.market_cap / 1e6).toFixed(0) + 'M';
      }

      // 52W mini bar
      var rangeStr = '<span style="color:#cbd5e1">—</span>';
      if (r.pct_in_range !== undefined && r.pct_in_range >= 0) {
        var pos = Math.max(0, Math.min(100, r.pct_in_range));
        var barColor = pos <= 25 ? '#10b981' : (pos >= 75 ? '#dc2626' : '#3b82f6');
        rangeStr = '<div style="position:relative;width:50px;height:10px;background:#f1f5f9;border-radius:3px;margin-left:auto">' +
                   '<div style="position:absolute;left:' + pos + '%;top:0;width:3px;height:10px;background:' + barColor + ';transform:translateX(-50%)"></div>' +
                   '</div>' +
                   '<div style="font-size:8px;color:#94a3b8;text-align:right;margin-top:2px">' + pos.toFixed(0) + '%</div>';
      }

      // Buy/sell
      var bsStr = '<span style="color:#cbd5e1">—</span>';
      if ((r.inst_buyers || 0) + (r.inst_sellers || 0) > 0) {
        var bRatio = (r.inst_buyers || 0) / Math.max(1, (r.inst_buyers || 0) + (r.inst_sellers || 0));
        var bsCol = bRatio >= 0.7 ? '#10b981' : (bRatio <= 0.3 ? '#dc2626' : '#64748b');
        bsStr = '<span style="color:' + bsCol + ';font-family:IBM Plex Mono,monospace;font-weight:700">' +
                (r.inst_buyers || 0) + ':' + (r.inst_sellers || 0) + '</span>';
      }

      var verdict = r[cfg.convictionField] || 'INSUFFICIENT DATA';
      var clickAttr = 'onclick="window._positioningDeepDive(\'' + r.ticker.replace(/'/g, "\\'") + '\')"';

      h += '<tr style="border-top:1px solid #f1f5f9;cursor:pointer" onmouseover="this.style.background=\'#fafbfc\'" onmouseout="this.style.background=\'\'" ' + clickAttr + '>';
      h += '<td style="padding:10px 8px;color:#94a3b8;font-family:IBM Plex Mono,monospace">' + (i + 1) + '</td>';
      h += '<td style="padding:10px 8px"><div style="font-weight:800;color:#0f172a;font-family:IBM Plex Mono,monospace;font-size:12px">' + r.ticker + '</div>' +
           '<div style="color:#94a3b8;font-size:10px;max-width:160px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + (r.issuer_name || '') + '</div></td>';
      h += '<td style="padding:10px 8px">' + _regimeBadge(r.regime || 'NEUTRAL') + '</td>';
      h += '<td style="padding:10px 8px;text-align:right">' + _scoreCell(r.accumulation_score) + '</td>';
      h += '<td style="padding:10px 8px;text-align:right">' + _scoreCell(r.compounder_score) + '</td>';
      h += '<td style="padding:10px 8px;text-align:right">' + _scoreCell(r.optionality_score_lens) + '</td>';
      h += '<td style="padding:10px 8px;text-align:right">' + _scoreCell(r.saturation_pct) + '</td>';
      h += '<td style="padding:10px 8px">' + _verdictBadge(verdict) + '</td>';
      h += '<td style="padding:10px 8px;text-align:center">' + _actionBadge(r.regime || 'NEUTRAL', verdict, r.saturation_pct) + '</td>';
      h += '<td style="padding:10px 8px;text-align:right;color:#0f172a;font-family:IBM Plex Mono,monospace;font-weight:700">' + priceStr + changeStr + '</td>';
      h += '<td style="padding:10px 8px;text-align:right;color:#475569;font-family:IBM Plex Mono,monospace">' + mcapStr + '</td>';
      h += '<td style="padding:10px 8px;text-align:right">' + rangeStr + '</td>';
      h += '<td style="padding:10px 8px;text-align:right">' + bsStr + '</td>';
      h += '</tr>';
    });
    h += '</tbody></table></div></div>';
  }

  // ── Footer: lens-specific methodology explanation ──────────────────────
  h += '<div style="padding:14px 4px;font-size:10px;color:#94a3b8;font-family:Inter,sans-serif;line-height:1.5">';
  if (lens === 'compounder') {
    h += '<strong>Compounders Lens</strong> ranks businesses by durability of returns: ROIC 5-yr median (40%) + ROIC stability (20%) + gross margin floor under stress (20%) + FCF positive years (20%). Surfaces names like Roper, Ecolab, Costco. <strong>Requires fundamentals data</strong> — names where Yahoo is blocked are excluded.';
  } else if (lens === 'accumulation') {
    h += '<strong>Institutional Accumulation Lens</strong> ranks by smart-money flow IN PROGRESS: ownership velocity Q/Q (30%) + buy/sell dominance (30%) + saturation sweet-spot (20%, rewards 30-50%, penalizes 90%+) + relative strength (10%) + persistence (10%). Surfaces names like MU pre-HBM cycle, PLTR during rerating. <strong>Hard veto</strong> when sellers ≥ 3× buyers.';
  } else {
    h += '<strong>Asymmetric Optionality Lens</strong> ranks by non-linear upside: R&D intensity sector-weighted (30%) + revenue Q/Q acceleration (25%) + cash-to-mcap optionality (15%) + survivability runway (15%) + asymmetric 52W entry (15%). Surfaces names like NuScale, early photonics, biotech-platform. <strong>Requires fundamentals data.</strong>';
  }
  h += '<br><br><strong>SATURATION</strong> = filer count vs. expected for market cap. A $200B name with 200 filers shows saturation ≈ 5 (deeply under-covered, NOT early discovery). A $200B name with 2500 filers shows saturation ≈ 70 (typical large-cap crowding). Saturation is meaningful only relative to market cap.';
  h += '<br><br><strong>VERDICT</strong> bands: HIGH = top decile of active lens (≥75 score, ≥4 input metrics). MEDIUM = ≥50 score with ≥3 inputs. LOW = ≥30 score. AVOID = <30. INSUFFICIENT DATA = fewer than 2 inputs available.';
  h += '<br><br><strong>🎯 ACTION</strong> is the plain-English call combining regime + verdict + saturation: <strong style="color:#059669">BUY</strong> (accumulation phase + strong verdict + not over-owned), <strong style="color:#10b981">BUY</strong> (markup confirmed + strong verdict), <strong style="color:#d97706">TRIM</strong> (markup but ownership saturated — late entry risk), <strong style="color:#6b7280">WATCH</strong> (ranging / wait for breakout), <strong style="color:#dc2626">SELL / AVOID</strong> (distribution or markdown — institutions exiting). <strong>Click any row to open the full deep-dive analysis</strong> with insider trades, institutional ownership over time, volume, and the institutional verdict.';
  h += '</div>';

  deResult.innerHTML = h;

  // Update match counter
  var counterEl = document.getElementById('positioningMatchCount');
  if (counterEl) {
    var total = (d.results || []).length;
    var shown = displayRows.length;
    if (searchVal && searchVal.trim()) {
      counterEl.innerHTML = '<strong>' + shown + '</strong> match' + (shown === 1 ? '' : 'es') + ' · <span style="color:#94a3b8">of ' + total + ' total</span>';
    } else {
      counterEl.innerHTML = '<strong>' + shown + '</strong> rows · <span style="color:#94a3b8">' + cfg.label + ' lens active</span>';
    }
  }
};

// Backward-compat: make _renderPositioningPage callable as legacy global too
function _renderPositioningPage(d, activeLens) {
  return window._renderPositioningPage(d, activeLens);
}

// r63.72.5: Safe deep-dive handler — null-checks before populating.
// Replaces inline onclick that crashed with "Cannot set properties of null".
window._positioningDeepDive = function(ticker) {
  if (!ticker) return;
  try {
    // Switch to Stock tab first so symbolInput exists.
    if (typeof switchTabGroup === 'function') switchTabGroup('research');
    if (typeof switchTab === 'function') switchTab('quick');

    // Defer setting the symbol + submitting until DOM has rendered.
    setTimeout(function() {
      var input = document.getElementById('symbolInput');
      if (input) {
        input.value = ticker;
        if (typeof onSubmit === 'function') {
          try { onSubmit(new Event('submit')); }
          catch (e) { /* form submit handler may throw — ignore, value is set */ }
        }
        // Fallback: try the form's submit button if onSubmit isn\'t defined.
        var btn = document.getElementById('symbolBtn') || document.querySelector('form#searchForm button[type="submit"]');
        if (btn && typeof onSubmit !== 'function') btn.click();
      } else {
        console.warn('[positioning] symbolInput not found; deep-dive skipped for', ticker);
      }
    }, 200);
  } catch (e) {
    console.error('[positioning] deep-dive failed:', e);
  }
};

// ═══════════════════════════════════════════════════════════════════════════
// r63.87.0: SMART MONEY SCANNER — batch SMI signals across a universe
// Calls /api/smart-money-scanner?region=US&mcap=large&limit=50 and renders a
// ranked table of smart-money signals. Uses the SAME defensive button pattern
// from the intraday scanner (always dark-on-light, active = thick border).
// Until backend is wired, renders a clear empty state with the field spec.
// ═══════════════════════════════════════════════════════════════════════════
window.loadSmartMoneyScanner = function(forceReg, forceMcap) {
  if (!window._activeSmartMoneyTab) return;
  var el = document.getElementById('deResult');
  if (!el) return;
  var reg = forceReg || window._deRegion || 'US';
  window._deRegion = reg;
  var mcap = forceMcap || window._smartMoneyMcap || 'large';
  window._smartMoneyMcap = mcap;

  var _eml = document.getElementById('email');
  var email = window._verifiedEmail || (_eml ? (_eml.dataset.real || _eml.value) : '').trim().toLowerCase();

  var _regBar = (typeof _renderRegionToggle === 'function')
    ? _renderRegionToggle('loadSmartMoneyScanner', reg)
    : '';

  var _univLabel = (function(){
    if (reg === 'US') {
      return ({large:'S&P 100', mid:'S&P 400 (mid)', small:'S&P 600 (small)', micro:'Russell Micro-Cap'})[mcap] || 'S&P 100';
    }
    return ({large:'NIFTY 50', mid:'NIFTY MIDCAP 100', small:'NIFTY SMALLCAP 100', micro:'NIFTY MICROCAP 250'})[mcap] || 'NIFTY 50';
  })();

  // Loading state
  var _smiLoader = (typeof _csLoader === 'function') ? _csLoader({
    title: "Smart Money Scanner",
    subtitle: "SCANNING " + _univLabel + " · " + mcap.toUpperCase() + " CAP · 13F + INSIDER + Q-OVER-Q",
    statusInitial: "Pulling 8-quarter ownership history + insider Form 4 cluster...",
    estimatedSec: 60,
    onAbort: function(){ window._activeSmartMoneyTab = false; },
  }) : null;

  el.innerHTML = _regBar +
    '<div style="max-width:1280px;margin:0 auto;padding:0 8px">' +
      '<div style="background:#fff;border:1px solid #e2e8f0;border-radius:8px;padding:14px 18px;margin-bottom:14px;display:flex;align-items:center;gap:14px">' +
        '<div style="width:40px;height:40px;background:#1A3A78;border-radius:8px;display:flex;align-items:center;justify-content:center;color:#fff;font-size:14px;font-weight:900;font-family:Sora,sans-serif">🧠</div>' +
        '<div style="flex:1"><div style="font-size:16px;font-weight:900;color:#0f172a;font-family:Sora,sans-serif">Smart Money Scanner</div>' +
        '<div style="font-size:10px;color:#64748b;font-family:\'IBM Plex Mono\',monospace;letter-spacing:0.5px;margin-top:2px">SCANNING ' + _univLabel + ' · ' + mcap.toUpperCase() + ' CAP</div></div>' +
      '</div>' +
      (_smiLoader ? _smiLoader.html : '<div style="padding:40px;text-align:center;color:#64748b">Loading...</div>') +
    '</div>';
  if (_smiLoader) _smiLoader.start(el);

  fetch('/api/smart-money-scanner?region=' + reg + '&mcap=' + mcap + '&email=' + encodeURIComponent(email) + '&limit=50', {cache:'no-store'})
    .then(function(r){return r.json();})
    .then(function(d){
      if (_smiLoader) _smiLoader.stop();
      if (_smiLoader && _smiLoader.isAborted()) return;
      _renderSmartMoneyScanner(el, d, _regBar, reg, mcap, _univLabel);
    })
    .catch(function(e){
      if (_smiLoader) _smiLoader.stop();
      // Backend not yet wired — graceful empty state with the spec
      _renderSmartMoneyScanner(el, {success:false, error:e.message, _notWired:true}, _regBar, reg, mcap, _univLabel);
    });
};

// ═══════════════════════════════════════════════════════════════════════════════
// r63.95.0: SCS integration into Smart Money Scanner
//   _smiScsCellHtml(r)            → renders the per-row SCS cell (verdict pill + score)
//   window._smiBatchComputeScs()  → fires /api/scs-batch for all visible tickers,
//                                   shows progress, refreshes scanner on completion
// ═══════════════════════════════════════════════════════════════════════════════

function _smiScsCellHtml(r) {
  // Three states: not_computed (button), cached (verdict pill + score), error.
  if (!r || r.scs_status === 'not_computed' || !r.scs_status) {
    return '<span title="SCS not yet computed for this ticker. Click ⚡ COMPUTE SCS above to populate, or open the 🏗 Structural tab and analyze this symbol directly." style="display:inline-block;padding:3px 8px;border-radius:4px;background:#f5f3ff;color:#7c3aed;font-size:9px;font-weight:700;font-family:\'IBM Plex Mono\',monospace;cursor:help">not yet</span>';
  }
  if (r.scs_status === 'cached') {
    var v = (r.scs_verdict || '').toString();
    var score = r.scs_score;
    var tags = r.scs_top_tags || [];
    var quiet = r.scs_quiet_accumulation;
    var bg, fg, label;
    if (v.indexOf('STRUCTURAL_BREAKOUT') >= 0) { bg = '#dcfce7'; fg = '#166534'; label = '🟢 BREAKOUT'; }
    else if (v.indexOf('TRANSITION') >= 0)     { bg = '#fef3c7'; fg = '#92400e'; label = '🟡 TRANSITION'; }
    else if (v.indexOf('NO_STRUCTURAL') >= 0)  { bg = '#fee2e2'; fg = '#991b1b'; label = '🔴 NO CHANGE'; }
    else                                        { bg = '#f1f5f9'; fg = '#64748b'; label = '🟡 INSUFFICIENT'; }
    // Build hover tip with top tags
    var tipText = 'SCS Verdict: ' + (r.scs_verdict_label || v).replace(/[🟢🟡🔴]/g, '').trim();
    if (score !== null && score !== undefined) tipText += ' · Score ' + score + '/100';
    if (r.scs_lead_strength) tipText += ' · Lead strength: ' + r.scs_lead_strength;
    if (tags.length) tipText += '\nTags: ' + tags.join(', ');
    if (r.scs_cache_age_sec !== undefined) tipText += '\nCached ' + Math.floor((r.scs_cache_age_sec||0)/60) + ' min ago';
    tipText += '\n\nClick to open full Structural Change analysis →';
    var clickHandler = 'event.stopPropagation();' +
      'try{var inp=document.getElementById(\'scsSym\');if(inp){inp.value=\'' + (r.ticker||'').replace(/'/g,'\\\'') + '\';}' +
      'if(window._scsState){window._scsState.region=\'' + (r.region || 'US').replace(/'/g,'\\\'') + '\';}' +
      'if(typeof window._openStructural===\'function\')window._openStructural();' +
      'if(typeof window.loadStructural===\'function\')setTimeout(window.loadStructural,200);}catch(e){}';
    var html = '<div onclick="' + clickHandler + '" title="' + tipText.replace(/"/g,'&quot;') + '" style="display:inline-flex;flex-direction:column;align-items:center;gap:2px;cursor:pointer;padding:2px">';
    html += '<span style="padding:2px 7px;border-radius:4px;background:' + bg + ';color:' + fg + ';font-size:9px;font-weight:800;font-family:Sora,sans-serif;letter-spacing:0.3px;white-space:nowrap">' + label + '</span>';
    if (score !== null && score !== undefined) {
      html += '<span style="font-size:9px;color:' + fg + ';font-family:\'IBM Plex Mono\',monospace;font-weight:700">' + score + '/100</span>';
    }
    if (quiet) {
      html += '<span title="QUIET ACCUMULATION — early structural breakout setup" style="font-size:8px;color:#f59e0b;font-weight:800;font-family:Sora,sans-serif;letter-spacing:0.3px">👁 QUIET</span>';
    } else if (tags.length > 0) {
      html += '<span style="font-size:8px;color:#9ca3af;font-family:\'IBM Plex Mono\',monospace">+' + tags.length + ' tags</span>';
    }
    html += '</div>';
    return html;
  }
  return '<span style="color:#cbd5e1;font-size:9px">—</span>';
}

window._smiBatchComputeScs = function(reg, mcap) {
  // Pull tickers from the currently rendered scanner table — the simplest, most reliable
  // source. Scrape ticker cells. We bound to first 25 to match the backend's per-call cap.
  reg = (reg || 'US').toUpperCase();
  var tickerCells = document.querySelectorAll('table td div[style*="font-family:IBM Plex Mono"]');
  var seen = {};
  var tickers = [];
  for (var i = 0; i < tickerCells.length && tickers.length < 25; i++) {
    var t = (tickerCells[i].textContent || '').trim();
    // Filter to plausible ticker symbols (uppercase, alphanumeric, dash/dot OK)
    if (t && /^[A-Z][A-Z0-9.\-]{0,9}$/.test(t) && !seen[t]) {
      seen[t] = 1;
      tickers.push(t);
    }
  }
  if (tickers.length === 0) {
    alert('No tickers found in the table to compute. Make sure the scanner has loaded first.');
    return;
  }
  // Confirm with user since this triggers up to 25 fresh yfinance fan-out scans
  if (!confirm('Compute Structural Change Signal for ' + tickers.length + ' visible tickers?\n\n' +
               'This fans out up to ' + tickers.length + ' yfinance calls in parallel (4 workers).\n' +
               'Expected time: ' + Math.ceil(tickers.length / 4 * 3) + '–' + Math.ceil(tickers.length / 4 * 6) + ' seconds.\n\n' +
               'Results will be cached for 30 minutes. After completion, the scanner will auto-refresh to surface SCS verdicts inline.')) {
    return;
  }

  // Find the COMPUTE SCS button and update its label to a progress indicator
  var btn = document.querySelector('button[onclick*="_smiBatchComputeScs"]');
  var originalHtml = btn ? btn.innerHTML : null;
  if (btn) {
    btn.disabled = true;
    btn.style.opacity = '0.6';
    btn.style.cursor = 'wait';
    btn.innerHTML = '⏳ COMPUTING (' + tickers.length + ' tickers)…';
  }

  var t0 = Date.now();
  fetch('/api/scs-batch?symbols=' + encodeURIComponent(tickers.join(',')) + '&region=' + encodeURIComponent(reg) + '&max_workers=4', {cache:'no-store'})
    .then(function(r){ if (!r.ok) throw new Error('API ' + r.status); return r.json(); })
    .then(function(d){
      var elapsed = Math.round((Date.now() - t0) / 1000);
      if (!d || d.success === false) {
        if (btn) {
          btn.disabled = false;
          btn.style.opacity = '1';
          btn.style.cursor = 'pointer';
          btn.innerHTML = originalHtml || '⚡ COMPUTE SCS';
        }
        alert('SCS batch failed: ' + ((d && d.error) || 'unknown error'));
        return;
      }
      // Show summary toast/alert
      var msg = '🏗 SCS batch complete (' + elapsed + 's)\n\n';
      msg += d.scored + ' / ' + d.requested + ' scored successfully\n';
      if (d.breakouts > 0) msg += '🟢 ' + d.breakouts + ' Structural Breakout Candidate' + (d.breakouts === 1 ? '' : 's') + '\n';
      if (d.transitions > 0) msg += '🟡 ' + d.transitions + ' in Transition Phase\n';
      if (d.quiet_accumulation_count > 0) msg += '👁 ' + d.quiet_accumulation_count + ' QUIET ACCUMULATION setup' + (d.quiet_accumulation_count === 1 ? '' : 's') + ' detected\n';
      msg += '\nRefreshing scanner to show SCS column…';
      // Use a non-blocking notification if possible, fallback to alert
      try {
        if (window._showToast) window._showToast(msg);
        else console.log(msg);
      } catch(_e) {}
      // Auto-refresh the scanner so SCS column populates
      setTimeout(function(){ if (typeof loadSmartMoneyScanner === 'function') loadSmartMoneyScanner(reg, mcap); }, 300);
    })
    .catch(function(e){
      if (btn) {
        btn.disabled = false;
        btn.style.opacity = '1';
        btn.style.cursor = 'pointer';
        btn.innerHTML = originalHtml || '⚡ COMPUTE SCS';
      }
      alert('SCS batch error: ' + e.message);
    });
};

function _renderSmartMoneyScanner(el, d, regBar, reg, mcap, univLabel) {
  var csym = reg === 'US' ? '$' : '₹';
  var h = regBar;
  h += '<div style="max-width:1280px;margin:0 auto;padding:0 8px">';

  // Header card
  h += '<div style="background:#fff;border:1px solid #e2e8f0;border-radius:8px;padding:14px 18px;margin-bottom:14px;display:flex;align-items:center;gap:14px">';
  h += '<div style="width:40px;height:40px;background:#1A3A78;border-radius:8px;display:flex;align-items:center;justify-content:center;color:#fff;font-size:14px;font-weight:900;font-family:Sora,sans-serif">🧠</div>';
  h += '<div style="flex:1"><div style="font-size:16px;font-weight:900;color:#0f172a;font-family:Sora,sans-serif">Smart Money Scanner</div>';
  h += '<div style="font-size:10px;color:#64748b;font-family:\'IBM Plex Mono\',monospace;letter-spacing:0.5px;margin-top:2px">' + univLabel + ' · ' + ((d && d.universe_size) || 0) + ' SCANNED · ' + ((d && d.results && d.results.length) || 0) + ' RANKED · ' + ((d && d.scan_time_sec) || 0) + 's</div></div>';
  if (d && d._cached) h += '<div style="font-size:9px;color:#1A3A78;font-weight:700;background:#eef2f9;padding:5px 10px;border-radius:4px;font-family:\'IBM Plex Mono\',monospace">CACHED ' + Math.floor((d._cache_age_sec||0)/60) + ' MIN</div>';
  // r63.95.0: SCS cache-hit indicator + batch compute button
  if (d && d.scs_enrichment) {
    var _scsHits = d.scs_enrichment.cached_hits || 0;
    var _scsTotal = d.scs_enrichment.total_rows || 0;
    var _scsBg = _scsHits > 0 ? '#f5f3ff' : '#fef3c7';
    var _scsFg = _scsHits > 0 ? '#4f46e5' : '#92400e';
    h += '<div style="font-size:9px;color:' + _scsFg + ';font-weight:700;background:' + _scsBg + ';padding:5px 10px;border-radius:4px;font-family:\'IBM Plex Mono\',monospace">🏗 SCS ' + _scsHits + '/' + _scsTotal + '</div>';
  }
  h += '<button onclick="window._smiBatchComputeScs(\'' + reg + '\',\'' + mcap + '\')" title="Compute Structural Change Signal for all visible rows in parallel (25 at a time, ~30s per batch). Warmed results then appear in the SCS column on next refresh." style="margin-left:6px;padding:6px 10px;border:1px solid #c7d2fe;background:linear-gradient(135deg,#f5f3ff,#ede9fe);color:#4f46e5;border-radius:6px;font-size:10px;font-weight:800;cursor:pointer;font-family:Sora,sans-serif;letter-spacing:0.3px">⚡ COMPUTE SCS</button>';
  h += '<button onclick="loadSmartMoneyScanner()" style="margin-left:8px;padding:6px 12px;border:1px solid #cbd5e1;background:#fff;border-radius:6px;font-size:10px;font-weight:700;cursor:pointer">↻ REFRESH</button>';
  h += '</div>';

  // Market-cap filter row — same defensive pattern as Intraday Scanner
  h += '<div style="display:flex;gap:12px;margin-bottom:10px;flex-wrap:wrap;align-items:center">';
  h += '<div style="font-size:9px;font-weight:800;color:#64748b;letter-spacing:1px;font-family:\'IBM Plex Mono\',monospace;margin-right:4px">MARKET CAP</div>';
  var _mcapBtns = [
    {id:'large', label:'Large Cap', sub: (reg==='US'?'S&P 100':'NIFTY 50')},
    {id:'mid',   label:'Mid Cap',   sub: (reg==='US'?'S&P 400':'MIDCAP 100')},
    {id:'small', label:'Small Cap', sub: (reg==='US'?'S&P 600':'SMALLCAP 100')},
    {id:'micro', label:'Micro Cap', sub: (reg==='US'?'Russell Micro':'MICROCAP 250')},
  ];
  _mcapBtns.forEach(function(b){
    var active = (mcap === b.id);
    var borderColor = active ? '#1A3A78' : '#cbd5e1';
    var borderWidth = active ? '2px' : '1px';
    var labelColor = active ? '#1A3A78' : '#374151';
    var bottomAccent = active ? 'border-bottom:3px solid #1A3A78;padding-bottom:5px;' : 'border-bottom:3px solid transparent;padding-bottom:5px;';
    h += '<button onclick="loadSmartMoneyScanner(\'' + reg + '\',\'' + b.id + '\')" ' +
         'style="padding:7px 14px;border:' + borderWidth + ' solid ' + borderColor + ';' +
         'background:#fff;border-radius:7px;cursor:pointer;font-family:Inter,sans-serif;' +
         'display:inline-flex;flex-direction:column;align-items:flex-start;line-height:1.2;' + bottomAccent +
         (active ? 'box-shadow:0 2px 8px rgba(26,58,120,0.18);' : '') + '">' +
         '<span style="font-size:11px;font-weight:' + (active?'900':'700') + ';font-family:Sora,sans-serif;color:' + labelColor + '">' + b.label + '</span>' +
         '<span style="font-size:8px;font-weight:600;color:#94a3b8;margin-top:1px;font-family:\'IBM Plex Mono\',monospace">' + b.sub + '</span>' +
         '</button>';
  });
  h += '</div>';

  // ─── Empty state: backend not yet wired ─────────────────────────────
  if (!d || !d.success || !d.results || !d.results.length) {
    h += '<div style="background:#fff;border:1px solid #e2e8f0;border-radius:8px;padding:36px 24px;text-align:center;color:#475569;font-family:Inter,sans-serif">';
    h += '<div style="font-size:48px;opacity:0.4;margin-bottom:12px">🧠</div>';
    h += '<div style="font-size:14px;font-weight:800;color:#0f172a;margin-bottom:6px">Smart Money Scanner — Backend Not Yet Wired</div>';
    h += '<div style="font-size:11px;color:#64748b;line-height:1.7;max-width:680px;margin:0 auto">';
    h += 'The endpoint <code style="background:#f1f5f9;padding:2px 6px;border-radius:4px;font-family:IBM Plex Mono,monospace;color:#1A3A78">/api/smart-money-scanner</code> is not yet returning results. ';
    h += 'This batch scanner needs four time-series fields per stock: ';
    h += '<code style="background:#f1f5f9;padding:1px 4px;border-radius:3px;font-family:IBM Plex Mono,monospace;color:#1A3A78">ownership_history</code> (8 quarters · drives OWN LAST 4Q + sparkline), ';
    h += '<code style="background:#f1f5f9;padding:1px 4px;border-radius:3px;font-family:IBM Plex Mono,monospace;color:#1A3A78">volume_quarterly_history</code> (5 quarters · drives VOL LAST 4Q), ';
    h += '<code style="background:#f1f5f9;padding:1px 4px;border-radius:3px;font-family:IBM Plex Mono,monospace;color:#1A3A78">top_holders_delta</code> (drives TOP HOLDERS), ';
    h += 'and <code style="background:#f1f5f9;padding:1px 4px;border-radius:3px;font-family:IBM Plex Mono,monospace;color:#1A3A78">insider_quarterly_history</code> (drives INSIDER). ';
    h += 'See <code style="background:#f1f5f9;padding:1px 4px;border-radius:3px;font-family:IBM Plex Mono,monospace;color:#1A3A78">SMART_MONEY_SCANNER_BACKEND_REFERENCE.py</code> in the deploy zip for the exact payload spec.';
    h += '</div>';
    h += '<div style="margin-top:18px;padding:10px 14px;background:#fffbeb;border-radius:6px;border:1px solid #fde68a;font-size:10px;color:#78350f;display:inline-block;max-width:560px;line-height:1.6">';
    h += '<strong>Build order recommendation:</strong> wire <code style="font-family:IBM Plex Mono,monospace">top_holders_delta</code> first (biggest signal per byte), then <code style="font-family:IBM Plex Mono,monospace">ownership_history</code> + <code style="font-family:IBM Plex Mono,monospace">volume_quarterly_history</code> (these light up the 4Q cells), then <code style="font-family:IBM Plex Mono,monospace">insider_quarterly_history</code>. Each field renders independently in this table — partial deployment is safe.';
    h += '</div>';
    h += '</div></div>';
    el.innerHTML = h;
    return;
  }

  // ─── Live ranked table ───────────────────────────────────────────
  // Sort by smart-money composite score (descending)
  var rows = d.results.slice().sort(function(a,b){return (b.smi_score||0)-(a.smi_score||0);});

  // Verdict pill colors
  var _verdictMeta = {
    'ACCUMULATING':  {bg:'#059669', tip:'Multi-quarter institutional accumulation. Smart money is quietly building position.'},
    'DISTRIBUTING':  {bg:'#dc2626', tip:'Multi-quarter institutional distribution. Smart money is exiting — bearish.'},
    'HOLDING':       {bg:'#d97706', tip:'Range-bound institutional ownership. No clear directional bias.'},
    'INSUFFICIENT':  {bg:'#94a3b8', tip:'Fewer than 4 quarters of data — verdict not yet derivable.'},
  };

  h += '<div style="background:#fff;border-radius:10px;overflow:hidden;border:1px solid #e2e8f0;font-family:Inter,sans-serif;margin-bottom:14px">';
  h += '<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:11px;min-width:1080px">';
  h += '<thead><tr style="background:#f8fafc;text-align:left;font-family:Sora,sans-serif">';
  var heads = [
    {l:'#',           a:'left',   w:'30px'},
    {l:'STOCK',       a:'left',   w:'140px'},
    {l:'VERDICT',     a:'left',   w:'100px', tip:'Smart-money verdict from 8-quarter ownership delta'},
    {l:'OWN LAST 4Q', a:'center', w:'130px', tip:'Institutional ownership % change for each of the last 4 quarters. Green = institutions added · Red = institutions reduced. Requires SEC EDGAR 13F integration.'},
    {l:'VOL LAST 4Q', a:'center', w:'130px', tip:'Average daily trading volume change for each of the last 4 quarters vs prior quarter. Green = volume rising · Red = volume falling.'},
    {l:'INSIDER 4Q',  a:'center', w:'130px', tip:'Insider net flow per quarter — buys minus sells in dollar terms. Green = net buying · Red = net selling.'},
    {l:'TOP HOLDERS', a:'left',   w:'110px', tip:'Net action across top 10 institutional holders this quarter. Requires SEC EDGAR 13F.'},
    {l:'🏗 SCS',       a:'center', w:'110px', tip:'Structural Change Signal — corporate transformation verdict (cached from prior Structural tab analysis or batch warmup). Click "⚡ COMPUTE SCS" above the table to populate all rows.'},
    {l:'SCORE',       a:'right',  w:'55px',  tip:'Composite 0-100. Combines ownership trend + holder action + insider acceleration.'},
    {l:'🎯 ACTION',   a:'center', w:'80px',  tip:'Plain-English buy/sell call combining all signals.'},
    {l:'PRICE',       a:'right',  w:'75px'},
  ];
  heads.forEach(function(hh){
    var tipAttr = hh.tip ? ' title="' + hh.tip.replace(/"/g,'&quot;') + '"' : '';
    h += '<th' + tipAttr + ' style="padding:10px 8px;font-size:9px;letter-spacing:0.6px;color:#64748b;font-weight:800;text-align:' + hh.a + ';width:' + hh.w + '">' + hh.l + '</th>';
  });
  h += '</tr></thead><tbody>';

  // Helper: derive ACTION from verdict + score
  function _smiAction(verdict, score) {
    if (verdict === 'ACCUMULATING' && score >= 70) return {label:'BUY',   color:'#059669', tip:'Strong multi-quarter accumulation + high composite score. Best smart-money setup.'};
    if (verdict === 'ACCUMULATING')                 return {label:'BUY',   color:'#10b981', tip:'Multi-quarter institutional accumulation. Follow the smart money.'};
    if (verdict === 'DISTRIBUTING' && score <= 30)  return {label:'AVOID', color:'#991b1b', tip:'Strong distribution + low score. Institutions are unwinding — stay out.'};
    if (verdict === 'DISTRIBUTING')                 return {label:'SELL',  color:'#dc2626', tip:'Institutions reducing position. Exit if long; do not chase.'};
    if (verdict === 'HOLDING')                      return {label:'WATCH', color:'#d97706', tip:'No clear conviction. Wait for inflection before committing.'};
    // r63.91.0: When verdict is INSUFFICIENT (ownership_history not wired yet) but we
    // have insider data driving the score, give a meaningful partial signal:
    if (verdict === 'INSUFFICIENT' && score >= 65)  return {label:'WATCH+', color:'#10b981', tip:'Insider data leans bullish (' + score + ' score) — full verdict pending ownership_history wiring.'};
    if (verdict === 'INSUFFICIENT' && score <= 35)  return {label:'WATCH−', color:'#dc2626', tip:'Insider data leans bearish (' + score + ' score) — full verdict pending ownership_history wiring.'};
    return {label:'—', color:'#cbd5e1', tip:'Insufficient quarterly data to make a call yet. Backend needs ownership_history + top_holders_delta wired.'};
  }

  // Helper: render 4 colored cells showing Q-over-Q deltas with quarter labels.
  // r63.88.0: User asked for "last 4 quarters... green if added, red if reduced".
  // r63.90.0: Added kind='usd' for insider net-flow dollar amounts (signed, K/M/B
  // formatted, ±$50K threshold). Each cell shows the net flow for that quarter,
  // not the delta vs prior — because insider activity is intrinsically per-quarter.
  // Each cell shows the per-quarter delta vs the prior quarter, color-coded.
  //   - kind='pp'  → delta in percentage points (institutional ownership %)
  //   - kind='pct' → delta as % change (trading volume Q-over-Q)
  //   - kind='usd' → absolute signed dollar net flow (insider buys − sells, no Q/Q diff)
  // Pulls from `hist` array — for pp/pct uses LAST 5 entries to compute 4 deltas,
  // for usd uses LAST 4 entries directly (already per-quarter values).
  function _q4Cells(hist, valueKey, kind, fallbackHint) {
    if (!hist || hist.length < 2) {
      return '<span title="' + fallbackHint + '" style="color:#cbd5e1;font-size:9px;font-family:IBM Plex Mono,monospace;cursor:help">— pending —</span>';
    }
    var deltas = [];
    if (kind === 'usd') {
      // Insider net flow — already per-quarter, no Q/Q diff needed
      var sliceU = hist.slice(-4);
      sliceU.forEach(function(q){
        var v = q[valueKey] || 0;
        deltas.push({delta: v, quarter: q.quarter || '?', curr: v, prev: null,
                     n_buys: q.n_buys || 0, n_sells: q.n_sells || 0});
      });
    } else {
      // ownership pp / volume pct — compute Q-over-Q deltas
      var slice = hist.slice(-5);
      for (var i = 1; i < slice.length; i++) {
        var curr = slice[i][valueKey] || 0;
        var prev = slice[i-1][valueKey] || 0;
        var d = (kind === 'pp') ? (curr - prev) : (prev > 0 ? ((curr - prev) / prev) * 100 : 0);
        deltas.push({delta: d, quarter: slice[i].quarter || ('Q' + i), curr: curr, prev: prev});
      }
    }
    // Pad with nulls if we have fewer than 4 quarters
    while (deltas.length < 4) deltas.unshift(null);

    // Format helper: signed dollar amount with K/M/B
    function _fmtUsd(v) {
      var ab = Math.abs(v); var sign = v >= 0 ? '+' : '−';
      if (ab >= 1e9) return sign + '$' + (ab/1e9).toFixed(1) + 'B';
      if (ab >= 1e6) return sign + '$' + (ab/1e6).toFixed(1) + 'M';
      if (ab >= 1e3) return sign + '$' + (ab/1e3).toFixed(0) + 'K';
      return sign + '$' + ab.toFixed(0);
    }

    var cellsHtml = '<div style="display:inline-flex;flex-direction:column;gap:1px;align-items:center">';
    cellsHtml += '<div style="display:flex;gap:2px">';
    deltas.forEach(function(d){
      if (!d) {
        cellsHtml += '<div style="width:30px;height:18px;border-radius:3px;background:#f1f5f9;color:#cbd5e1;font-size:8px;font-weight:700;font-family:IBM Plex Mono,monospace;display:flex;align-items:center;justify-content:center">—</div>';
        return;
      }
      var col, txtCol;
      var threshold = (kind === 'pp') ? 0.1 : (kind === 'pct' ? 1.0 : 50000);  // $50K threshold for insider
      if (d.delta > threshold)       { col = '#059669'; txtCol = '#fff'; }   // ADDED — green
      else if (d.delta < -threshold) { col = '#dc2626'; txtCol = '#fff'; }   // REDUCED — red
      else                            { col = '#e2e8f0'; txtCol = '#475569'; } // FLAT — gray
      var displayVal, tip;
      if (kind === 'pp') {
        var sign = d.delta > 0 ? '+' : (d.delta < 0 ? '' : '');
        displayVal = sign + d.delta.toFixed(1);
        tip = d.quarter + ': ' + d.prev.toFixed(1) + '% → ' + d.curr.toFixed(1) + '% (' + sign + d.delta.toFixed(2) + 'pp)';
      } else if (kind === 'pct') {
        var s2 = d.delta > 0 ? '+' : (d.delta < 0 ? '' : '');
        displayVal = s2 + d.delta.toFixed(0) + '%';
        tip = d.quarter + ': prior ' + (d.prev/1e6).toFixed(1) + 'M → ' + (d.curr/1e6).toFixed(1) + 'M (' + s2 + d.delta.toFixed(1) + '%)';
      } else {  // usd
        displayVal = _fmtUsd(d.delta);
        var ab2 = Math.abs(d.delta);
        var compact = ab2 >= 1e6 ? (ab2/1e6).toFixed(1)+'M' : ab2 >= 1e3 ? (ab2/1e3).toFixed(0)+'K' : ab2.toFixed(0);
        if (ab2 < 10000) {
          // For small dollar amounts, prefer showing buy/sell counts
          displayVal = (d.n_buys || 0) + 'B/' + (d.n_sells || 0) + 'S';
        } else if (ab2 < 1e6) {
          displayVal = (d.delta >= 0 ? '+' : '−') + '$' + (ab2/1e3).toFixed(0) + 'K';
        } else {
          displayVal = (d.delta >= 0 ? '+' : '−') + '$' + (ab2/1e6).toFixed(1) + 'M';
        }
        tip = d.quarter + ': ' + (d.n_buys || 0) + ' insider buy' + ((d.n_buys||0)===1?'':'s') + ' · ' +
              (d.n_sells || 0) + ' sell' + ((d.n_sells||0)===1?'':'s') + ' · net ' + _fmtUsd(d.delta);
      }
      cellsHtml += '<div title="' + tip + '" style="width:30px;height:18px;border-radius:3px;background:' + col + ';color:' + txtCol + ';font-size:9px;font-weight:800;font-family:IBM Plex Mono,monospace;display:flex;align-items:center;justify-content:center;cursor:help">' + displayVal + '</div>';
    });
    cellsHtml += '</div>';
    cellsHtml += '<div style="display:flex;gap:2px">';
    deltas.forEach(function(d){
      var label = '—';
      if (d && d.quarter) {
        var m = /^Q(\d)\s*(\d{2,4})$/.exec(d.quarter);
        if (m) label = 'Q' + m[1] + "'" + m[2].slice(-2);
        else label = d.quarter.slice(-5);
      }
      cellsHtml += '<div style="width:30px;text-align:center;font-size:7px;color:#94a3b8;font-family:IBM Plex Mono,monospace">' + label + '</div>';
    });
    cellsHtml += '</div></div>';
    return cellsHtml;
  }

  // Helper: holder action badge
  function _holderBadge(action) {
    var meta = {
      'NET ADDING':   {bg:'#dcfce7', fg:'#166534', tip:'More than 60% of top holders are increasing positions Q/Q'},
      'NET REDUCING': {bg:'#fee2e2', fg:'#991b1b', tip:'More than 60% of top holders are reducing positions Q/Q'},
      'MIXED':        {bg:'#fef3c7', fg:'#92400e', tip:'No clear directional bias among top holders'},
      'HOLDING':      {bg:'#f1f5f9', fg:'#475569', tip:'Top holders mostly unchanged from prior quarter'},
    };
    var m = meta[action] || {bg:'#f1f5f9', fg:'#94a3b8', tip:action || 'No data'};
    return '<span title="' + m.tip + '" style="padding:3px 8px;border-radius:5px;background:' + m.bg + ';color:' + m.fg + ';font-size:9px;font-weight:800;font-family:Sora,sans-serif;white-space:nowrap;cursor:help">' + (action || '—') + '</span>';
  }

  // Helper: insider trend badge
  function _insiderBadge(trend) {
    var meta = {
      'ACCELERATING': {bg:'#dcfce7', fg:'#166534', tip:'Insider buying $-value growing materially each of the last few quarters'},
      'STEADY':       {bg:'#dbeafe', fg:'#1e40af', tip:'Consistent insider activity, no inflection'},
      'DECELERATING': {bg:'#fee2e2', fg:'#991b1b', tip:'Insider buying $-value shrinking — losing conviction'},
      'NONE':         {bg:'#f1f5f9', fg:'#94a3b8', tip:'No material insider activity in recent quarters'},
    };
    var m = meta[trend] || {bg:'#f1f5f9', fg:'#94a3b8', tip:trend || 'No data'};
    return '<span title="' + m.tip + '" style="padding:3px 8px;border-radius:5px;background:' + m.bg + ';color:' + m.fg + ';font-size:9px;font-weight:800;font-family:Sora,sans-serif;white-space:nowrap;cursor:help">' + (trend || '—') + '</span>';
  }

  rows.forEach(function(r, i){
    var verdict = r.smi_verdict || 'INSUFFICIENT';
    var vMeta = _verdictMeta[verdict] || _verdictMeta['INSUFFICIENT'];
    var act = _smiAction(verdict, r.smi_score || 0);

    var priceStr = (r.price && r.price > 0) ? csym + r.price.toFixed(2) : '<span style="color:#cbd5e1">—</span>';
    var chgStr = '';
    if (r.price && r.change_pct !== undefined && r.change_pct !== null) {
      var chCol = r.change_pct >= 0 ? '#10b981' : '#dc2626';
      chgStr = '<div style="font-size:9px;color:' + chCol + ';margin-top:1px">' + (r.change_pct >= 0 ? '+' : '') + r.change_pct.toFixed(2) + '%</div>';
    }

    var scoreStr;
    if (r.smi_score != null) {
      var sCol = r.smi_score >= 70 ? '#059669' : r.smi_score >= 50 ? '#3b82f6' : r.smi_score >= 30 ? '#d97706' : '#dc2626';
      scoreStr = '<span style="color:' + sCol + ';font-weight:800;font-family:IBM Plex Mono,monospace;font-size:13px">' + Math.round(r.smi_score) + '</span>';
    } else {
      scoreStr = '<span style="color:#cbd5e1;font-size:9px">N/A</span>';
    }

    var clickAttr = 'onclick="window._smartMoneyDeepDive(\'' + (r.ticker||'').replace(/\'/g,'\\\'') + '\')"';

    h += '<tr style="border-top:1px solid #f1f5f9;cursor:pointer" onmouseover="this.style.background=\'#fafbfc\'" onmouseout="this.style.background=\'\'" ' + clickAttr + '>';
    h += '<td style="padding:10px 8px;color:#94a3b8;font-family:IBM Plex Mono,monospace">' + (i+1) + '</td>';
    h += '<td style="padding:10px 8px"><div style="font-weight:800;color:#0f172a;font-family:IBM Plex Mono,monospace;font-size:12px">' + r.ticker + '</div>' +
         '<div style="color:#94a3b8;font-size:10px;max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + (r.issuer_name || '') + '</div></td>';
    h += '<td style="padding:10px 8px"><span title="' + vMeta.tip + '" style="padding:3px 9px;border-radius:6px;background:' + vMeta.bg + ';color:#fff;font-size:9px;font-weight:800;font-family:Sora,sans-serif;white-space:nowrap;cursor:help">' + verdict + '</span></td>';
    // r63.88.0: 4 quarter cells for institutional ownership Q-over-Q (green = added, red = reduced)
    h += '<td style="padding:10px 8px;text-align:center">' + _q4Cells(r.ownership_history, 'total_pct_outstanding', 'pp', 'ownership_history not yet returned') + '</td>';
    // r63.88.0: 4 quarter cells for trading volume Q-over-Q (green = volume rising, red = falling)
    h += '<td style="padding:10px 8px;text-align:center">' + _q4Cells(r.volume_quarterly_history, 'avg_daily_volume', 'pct', 'volume_quarterly_history not yet returned') + '</td>';
    // r63.90.0: 4 quarter cells for insider net flow per quarter (green = net buying, red = net selling)
    h += '<td style="padding:10px 8px;text-align:center">' + _q4Cells(r.insider_quarterly_history, 'net_flow_usd', 'usd', 'insider_quarterly_history not yet returned') + '</td>';
    h += '<td style="padding:10px 8px">' + _holderBadge(r.top_holders_action) + '</td>';
    // r63.95.0: SCS cell — surfaces cached Structural Change Signal verdict if available
    h += '<td style="padding:10px 8px;text-align:center">' + _smiScsCellHtml(r) + '</td>';
    h += '<td style="padding:10px 8px;text-align:right">' + scoreStr + '</td>';
    h += '<td style="padding:10px 8px;text-align:center"><span title="' + act.tip + '" style="padding:4px 10px;border-radius:6px;background:' + act.color + ';color:#fff;font-size:10px;font-weight:800;font-family:Sora,sans-serif;cursor:help">' + act.label + '</span></td>';
    h += '<td style="padding:10px 8px;text-align:right;color:#0f172a;font-family:IBM Plex Mono,monospace;font-weight:700">' + priceStr + chgStr + '</td>';
    h += '</tr>';
  });
  h += '</tbody></table></div></div>';

  // Methodology footer
  h += '<div style="padding:14px 4px;font-size:10px;color:#94a3b8;font-family:Inter,sans-serif;line-height:1.6">';
  h += '<strong style="color:#475569">Smart Money Scanner methodology:</strong> For each stock in the ' + univLabel + ' universe, the scanner aggregates four time-series signals from SEC 13F + Form 4 (US) / BSE-NSE shareholding pattern + insider disclosures (India):';
  h += '<br>• <strong>OWN LAST 4Q</strong> — institutional ownership % change quarter-over-quarter. <span style="color:#059669;font-weight:700">Green</span> = institutions added that quarter, <span style="color:#dc2626;font-weight:700">red</span> = institutions reduced, gray = flat (under 0.1pp change). 4 cells = last 4 Q-over-Q deltas. Most recent quarter rightmost.';
  h += '<br>• <strong>VOL LAST 4Q</strong> — average daily trading volume change Q-over-Q. <span style="color:#059669;font-weight:700">Green</span> = volume up (interest building), <span style="color:#dc2626;font-weight:700">red</span> = volume down (interest waning), gray = flat (under 1% change). 4 cells = last 4 Q-over-Q deltas.';
  h += '<br>• <strong>INSIDER 4Q</strong> — insider net flow (buys $ minus sells $) for each of the last 4 quarters. <span style="color:#059669;font-weight:700">Green</span> = insiders net buying that quarter (bullish), <span style="color:#dc2626;font-weight:700">red</span> = insiders net selling (bearish), gray = quiet (under $50K). Small amounts shown as buy/sell counts (e.g., "5B/1S"); larger as $ amount (e.g., "+$2.1M").';
  h += '<br>• <strong>TOP HOLDERS</strong> — direction across top 10 institutional holders this quarter (NET ADDING if &gt;60% increasing, NET REDUCING if &gt;60% reducing, MIXED otherwise).';
  h += '<br><br><strong style="color:#475569">VERDICT</strong>: ACCUMULATING (8Q delta ≥ +3pp), DISTRIBUTING (≤ −3pp), HOLDING (between), INSUFFICIENT (fewer than 4 quarters).';
  h += '<br><strong style="color:#475569">🎯 ACTION</strong>: BUY (ACCUMULATING), TRIM/SELL (DISTRIBUTING), WATCH (HOLDING), AVOID (DISTRIBUTING + score &lt; 30).';
  h += '<br><br><strong style="color:#4f46e5">🏗 SCS (Structural Change Signal)</strong> — corporate transformation verdict across 5 categories (Capital Structure 25%, Business Model 25%, Ownership 20%, Strategic Pivot 15%, Balance Sheet Reset 15%). Surfaces cached results from the Structural tab; click <strong>⚡ COMPUTE SCS</strong> above the table to fan out a 25-ticker batch warmup. Verdict pill colors: 🟢 STRUCTURAL_BREAKOUT_CANDIDATE (score ≥65) · 🟡 TRANSITION_PHASE (45–64) · 🔴 NO_STRUCTURAL_CHANGE (&lt;45). The <strong>👁 QUIET</strong> badge flags the early-detection trigger: ≥2 categories positive + institutional ownership rising + price in consolidation — the "pre-breakout setup" institutions look for.';
  h += '<br><br><strong style="color:#475569">Hover any green/red cell</strong> for the exact prior → current values. <strong>Click any row</strong> to open the full per-stock SMI panel with charts, holder delta table, and quarterly insider history. <strong>Click the SCS pill</strong> to open the full Structural Change analysis for that ticker.';
  h += '</div>';

  h += '</div>';
  el.innerHTML = h;
}

// Drill-down: open the full analyze page for a ticker (which now includes the SMI panel)
window._smartMoneyDeepDive = function(ticker) {
  if (!ticker) return;
  try {
    if (typeof switchTabGroup === 'function') switchTabGroup('research');
    if (typeof switchTab === 'function') switchTab('quick');
    setTimeout(function(){
      var input = document.getElementById('symbolInput');
      if (input) {
        input.value = ticker;
        if (typeof onSubmit === 'function') {
          try { onSubmit(new Event('submit')); } catch (e) { /* form may throw — value is set */ }
        }
        var btn = document.getElementById('symbolBtn') || document.querySelector('form#searchForm button[type="submit"]');
        if (btn && typeof onSubmit !== 'function') btn.click();
      }
    }, 200);
  } catch (e) {
    console.error('[smartmoney] deep-dive failed:', e);
  }
};

window.loadMicroCapHunter = function(forceReg) {
  if (!window._activeMicroCapHunterTab) return;
  var el = document.getElementById('deResult');
  if (!el) return;
  var reg = forceReg || window._deRegion || 'US';
  window._deRegion = reg;
  var csym = reg === 'US' ? '$' : '₹';

  var _eml = document.getElementById('email');
  var email = window._verifiedEmail || (_eml ? (_eml.dataset.real || _eml.value) : '').trim().toLowerCase();

  // Region toggle bar (consistent with other Decide screens)
  var _regBar = (typeof _renderRegionToggle === 'function')
    ? _renderRegionToggle('loadMicroCapHunter', reg)
    : '';

  // r62.3: Production loading state for Micro-Cap Hunter
  var _hunterLoader = _csLoader({
    title: "Micro-Cap Hunter",
    subtitle: "SCANNING " + (reg === 'US' ? '~90 US' : '~60 INDIA') + " MICRO-CAPS · 7-FACTOR LIGHT SCAN",
    statusInitial: "Running 7-factor screen with liquidity + distress filters...",
    estimatedSec: 75,
    onAbort: function(){ window._activeMicroCapHunterTab = false; },
  });
  el.innerHTML = _regBar + (
    '<div style="max-width:1280px;margin:0 auto;padding:0 8px">' +
    '<div style="background:#fff;border:1px solid #e2e8f0;border-radius:8px;padding:14px 18px;margin-bottom:14px;display:flex;align-items:center;gap:14px">' +
      '<div style="width:40px;height:40px;background:#1A3A78;border-radius:8px;display:flex;align-items:center;justify-content:center;color:#fff;font-size:14px;font-weight:900;font-family:Sora,sans-serif">MH</div>' +
      '<div style="flex:1">' +
        '<div style="font-size:16px;font-weight:900;color:#0f172a;font-family:Sora,sans-serif">Micro-Cap Hunter</div>' +
        '<div style="font-size:10px;color:#64748b;font-family:\'IBM Plex Mono\',monospace;letter-spacing:0.5px;margin-top:2px">SCANNING UNIVERSE · ' + (reg === 'US' ? 'US' : 'INDIA NSE') + '</div>' +
      '</div>' +
      '<div style="font-size:9px;color:#1A3A78;font-weight:700;letter-spacing:0.6px;font-family:\'IBM Plex Mono\',monospace;background:#eef2f9;padding:5px 10px;border-radius:4px">FIRST RUN ~60-90s · CACHED 30 MIN</div>' +
    '</div>' +
    _hunterLoader.html +
    '</div>'
  );
  _hunterLoader.start(el);

  _csFetchWithTimeout('/api/microcap-hunter?region=' + reg + '&email=' + encodeURIComponent(email) + '&min_score=40&limit=20', null, 120000)
    .then(function(r) { return r.json(); })
    .then(function(d) {
      if (typeof _hunterLoader !== 'undefined') _hunterLoader.stop();
      if (typeof _hunterLoader !== 'undefined' && _hunterLoader.isAborted()) return;
      if (!d.success) {
        el.innerHTML = _regBar +
          '<div style="max-width:720px;margin:24px auto;padding:24px;text-align:center;background:#fef2f2;border:1px solid #fecaca;border-radius:8px;color:#991b1b;font-family:Inter,sans-serif">' +
          '<div style="font-size:28px;margin-bottom:8px">⚠</div>' +
          '<div style="font-size:13px;font-weight:700;margin-bottom:6px">Scan failed</div>' +
          '<div style="font-size:11px;color:#7f1d1d;margin-bottom:14px">' + (d.error || 'Unknown error') + '</div>' +
          '<button onclick="loadMicroCapHunter()" style="padding:6px 14px;border:1px solid #fca5a5;background:#fff;color:#dc2626;border-radius:5px;font-size:11px;font-weight:700;cursor:pointer">RETRY</button>' +
          '</div>';
        return;
      }
      _renderMicroCapHunter(el, d, _regBar, reg, email);
    })
    .catch(function(e) {
      if (typeof _hunterLoader !== 'undefined') _hunterLoader.stop();
      if (typeof _hunterLoader !== 'undefined' && _hunterLoader.isAborted()) return;
      var msg = (e.name === 'AbortError') ? 'Scan timed out after 2 minutes. Yahoo is likely rate-limiting. Try again in a few minutes.' : ('Network error: ' + e.message);
      el.innerHTML = _regBar +
        '<div style="max-width:720px;margin:24px auto;padding:24px;text-align:center;background:#fef2f2;border:1px solid #fecaca;border-radius:8px;color:#991b1b;font-family:Inter,sans-serif">' +
        '<div style="font-size:28px;margin-bottom:8px">⚠</div>' +
        '<div style="font-size:13px;font-weight:700;margin-bottom:6px">Could not complete scan</div>' +
        '<div style="font-size:11px;color:#7f1d1d;margin-bottom:14px;line-height:1.5">' + msg + '</div>' +
        '<button onclick="loadMicroCapHunter()" style="padding:6px 14px;border:1px solid #fca5a5;background:#fff;color:#dc2626;border-radius:5px;font-size:11px;font-weight:700;cursor:pointer">RETRY</button>' +
        '</div>';
    });
};

function _renderMicroCapHunter(el, d, regBar, reg, email) {
  var csym = d.currency_symbol || '$';
  var fmtCcy = function(v) {
    if (v == null) return '—';
    if (Math.abs(v) >= 1e9) return csym + (v/1e9).toFixed(2) + 'B';
    if (Math.abs(v) >= 1e6) return csym + (v/1e6).toFixed(0) + 'M';
    if (Math.abs(v) >= 1e3) return csym + (v/1e3).toFixed(0) + 'K';
    return csym + v.toFixed(2);
  };

  var h = regBar;
  h += '<div style="max-width:1280px;margin:0 auto;padding:0 8px">';

  // ═══ Header strip ═══
  h += '<div style="background:#fff;border:1px solid #e2e8f0;border-radius:8px;padding:14px 18px;margin-bottom:14px;display:flex;align-items:center;gap:14px">';
  h += '<div style="width:40px;height:40px;background:#1A3A78;border-radius:8px;display:flex;align-items:center;justify-content:center;color:#fff;font-size:14px;font-weight:900;font-family:Sora,sans-serif">MH</div>';
  h += '<div style="flex:1;min-width:0">';
  h += '<div style="font-size:16px;font-weight:900;color:#0f172a;font-family:Sora,sans-serif;letter-spacing:0.2px">Micro-Cap Hunter</div>';
  h += '<div style="font-size:10px;color:#64748b;font-family:\'IBM Plex Mono\',monospace;letter-spacing:0.5px;margin-top:2px">' + (reg === 'US' ? 'US' : 'INDIA NSE') + ' · ' + d.universe_size + ' SCANNED · ' + d.candidates.length + ' PASS · ' + d.scan_time_sec + 's</div>';
  h += '</div>';
  if (d._cached) {
    h += '<div style="font-size:9px;color:#1A3A78;font-weight:700;letter-spacing:0.6px;font-family:\'IBM Plex Mono\',monospace;background:#eef2f9;padding:5px 10px;border-radius:4px">CACHED · ' + Math.floor((d._cache_age_sec || 0)/60) + ' MIN AGO</div>';
  } else {
    h += '<div style="font-size:9px;color:#059669;font-weight:700;letter-spacing:0.6px;font-family:\'IBM Plex Mono\',monospace;background:#ecfdf5;padding:5px 10px;border-radius:4px">FRESH SCAN</div>';
  }
  h += '<button onclick="loadMicroCapHunter()" style="margin-left:8px;padding:6px 12px;border:1px solid #cbd5e1;background:#fff;border-radius:6px;font-size:10px;font-weight:700;cursor:pointer;font-family:Inter,sans-serif">↻ REFRESH</button>';
  h += '</div>';

  // Honest disclaimer
  h += '<div style="background:#fffbeb;border:1px solid #fde68a;border-radius:8px;padding:10px 14px;margin-bottom:14px;display:flex;gap:10px;align-items:center">';
  h += '<span style="color:#d97706;font-size:14px;flex-shrink:0">⚠</span>';
  h += '<div style="flex:1;font-size:11px;color:#78350f;line-height:1.5;font-family:Inter,sans-serif">' + (d.honest_disclaimer || '') + '</div>';
  h += '</div>';

  // No candidates fallback
  if (!d.candidates || !d.candidates.length) {
    h += '<div style="background:#fff;border:1px solid #e2e8f0;border-radius:8px;padding:40px;text-align:center;color:#64748b;font-size:13px">';
    h += 'No candidates passed the screen. Universe scanned: ' + d.universe_size + '. Skipped: ' + d.skipped_count + '. Try lowering min_score or check Yahoo data freshness.';
    h += '</div></div>';
    el.innerHTML = h;
    return;
  }

  // ═══ Candidate grid ═══
  h += '<div style="display:grid;grid-template-columns:1fr;gap:8px">';
  d.candidates.forEach(function(c, idx) {
    var scoreClass = c.hunter_score >= 75 ? 'pos' : c.hunter_score >= 55 ? 'warn' : 'neutral';
    var scoreColor = c.hunter_score >= 75 ? '#059669' : c.hunter_score >= 55 ? '#d97706' : '#64748b';
    var scoreBg = c.hunter_score >= 75 ? '#ecfdf5' : c.hunter_score >= 55 ? '#fffbeb' : '#f8fafc';

    h += '<div style="background:#fff;border:1px solid #e2e8f0;border-radius:8px;padding:14px 16px;display:grid;grid-template-columns:auto 1fr auto auto;gap:14px;align-items:center;cursor:pointer;transition:border-color 100ms" ' +
         'onmouseover="this.style.borderColor=\'#1A3A78\'" onmouseout="this.style.borderColor=\'#e2e8f0\'" ' +
         'onclick="window._hunterOpenDD(\'' + c.symbol + '\',\'' + reg + '\')">';

    // Rank
    h += '<div style="font-family:\'IBM Plex Mono\',monospace;font-size:18px;font-weight:900;color:#94a3b8;min-width:30px;text-align:right">#' + (idx + 1) + '</div>';

    // Main info
    h += '<div style="min-width:0">';
    h += '<div style="display:flex;align-items:baseline;gap:8px;margin-bottom:3px">';
    h += '<span style="font-family:\'IBM Plex Mono\',monospace;font-size:16px;font-weight:900;color:#0f172a;letter-spacing:0.5px">' + c.symbol + '</span>';
    h += '<span style="font-size:11px;color:#64748b;font-family:Inter,sans-serif;font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + c.name + '</span>';
    h += '</div>';
    h += '<div style="font-size:10px;color:#94a3b8;font-family:\'IBM Plex Mono\',monospace;letter-spacing:0.4px;margin-bottom:5px">' + (c.sector || 'UNKNOWN').toUpperCase() + ' · ' + fmtCcy(c.market_cap) + ' MCAP · ' + csym + (c.price || 0).toFixed(2) + ' SPOT</div>';
    // Signals (the "why")
    if (c.signals && c.signals.length) {
      h += '<div style="display:flex;flex-wrap:wrap;gap:4px">';
      c.signals.forEach(function(sig) {
        h += '<span style="font-size:9px;font-weight:600;color:#0f172a;background:#f1f5f9;border:1px solid #e2e8f0;padding:2px 6px;border-radius:3px;font-family:Inter,sans-serif">' + sig + '</span>';
      });
      h += '</div>';
    }
    if (c.flags && c.flags.length) {
      h += '<div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:4px">';
      c.flags.forEach(function(f) {
        h += '<span style="font-size:9px;font-weight:600;color:#dc2626;background:#fef2f2;border:1px solid #fecaca;padding:2px 6px;border-radius:3px;font-family:Inter,sans-serif">⚠ ' + f + '</span>';
      });
      h += '</div>';
    }
    h += '</div>';

    // Hunter score
    h += '<div style="text-align:right;min-width:60px">';
    h += '<div style="font-family:\'IBM Plex Mono\',monospace;font-size:22px;font-weight:900;color:' + scoreColor + ';line-height:1">' + c.hunter_score + '</div>';
    h += '<div style="font-size:8px;color:#94a3b8;font-family:\'IBM Plex Mono\',monospace;letter-spacing:0.4px;margin-top:2px">SCORE</div>';
    h += '</div>';

    // CTA
    h += '<div style="display:flex;align-items:center;gap:6px"><button style="padding:6px 12px;background:#1A3A78;color:#fff;border:none;border-radius:5px;font-size:10px;font-weight:700;cursor:pointer;font-family:Inter,sans-serif;letter-spacing:0.4px">DEEP DD →</button></div>';

    h += '</div>';
  });
  h += '</div>';

  // Footer note
  h += '<div style="margin-top:16px;padding:10px 14px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:6px;font-size:10px;color:#64748b;font-family:Inter,sans-serif">';
  h += '<strong style="color:#0f172a">How this works:</strong> 7-factor light scan (profitability, growth, balance sheet, insider ownership, short squeeze, momentum, ROE) on ' + d.universe_size + ' tickers. Hard filters: liquidity > ' + csym + '500K daily, price > ' + csym + '1, no obvious distress. Click any row to run full Deep DD with real institutional analysis (16 sections + multi-factor verdict).';
  h += '</div>';

  h += '</div>';
  el.innerHTML = h;
}

window._hunterOpenDD = function(symbol, region) {
  // Open Deep DD for the selected ticker
  if (typeof switchSubTab === 'function') {
    // Persist the symbol so DD entry page picks it up
    window._ddLastSymbol = symbol;
    window._deRegion = region;
    if (typeof switchTabGroup === 'function') switchTabGroup('decide');
    setTimeout(function() {
      if (typeof switchSubTab === 'function') switchSubTab('deepdd');
      setTimeout(function() {
        if (typeof loadDeepDD === 'function') loadDeepDD();
        setTimeout(function() {
          var inp = document.getElementById('ddSymbol');
          if (inp) {
            inp.value = symbol;
            if (typeof window._ddGenerate === 'function') window._ddGenerate();
          }
        }, 200);
      }, 100);
    }, 100);
  }
};

