// REGIONAL REPORTS — Live Data Rendering
// ═══════════════════════════════════════════════════
function loadRegionalReports(){
var ld=document.getElementById('reportsLoading');
var ct=document.getElementById('reportsContent');
var ts=document.getElementById('reportsTimestamp');
var btn=document.getElementById('reportsRefreshBtn');
if(ld)ld.style.display='block';
if(ct)ct.innerHTML='';
if(btn){btn.disabled=true;btn.textContent='⏳ Loading...'}
fetch('/api/regional-reports').then(function(r){return r.json()}).then(function(d){
if(ld)ld.style.display='none';
if(btn){btn.disabled=false;btn.textContent='🔄 Refresh Live Data'}
if(!d.success){if(ct)ct.innerHTML='<div style="color:var(--red);padding:20px;text-align:center">Failed to load reports. <button onclick="loadRegionalReports()" style="color:var(--blue);background:none;border:none;cursor:pointer;text-decoration:underline">Retry</button></div>';return}
if(ts)ts.textContent='Last updated: '+d.timestamp;
var h='';
// 0. ENGINE REPORT — Already in HTML (index.html), skip JS duplicate
// 1. MACRO & CENTRAL BANK
h+=_rptAccordion('macro','🏛️ Macro & Central Bank Intelligence','India + USA key indices, VIX fear gauge, bond yields',true,_rptMacro(d));
// 2. CAPITAL FLOWS (FII/DII)
h+=_rptAccordion('flows','💰 Capital Flow & Liquidity — FII/DII Live','Who is buying & selling Indian markets today?',false,_rptFlows(d));
// 3. CURRENCY & FX RISK
h+=_rptAccordion('currency','💱 Currency & FX Risk Monitor','USD/INR, Dollar Index, cross-border impact analysis',false,_rptCurrency(d));
// 4. SECTOR DEEP DIVES
h+=_rptAccordion('sectors','🏭 Sector Deep Dives — US vs India','Sector ETF performance comparison + commodities',false,_rptSectors(d));
// 5. EM vs DM
h+=_rptAccordion('emdm','🌍 Emerging vs Developed Markets','EM ETF flows, India vs China, capital rotation signals',false,_rptEmDm(d));
// 6. GEOPOLITICAL & THEMATIC
h+=_rptAccordion('geo','🔥 Geopolitical & Thematic Signals','Auto-generated signals from cross-market data patterns',false,_rptGeo(d));
if(ct)ct.innerHTML=h;
}).catch(function(e){
if(ld)ld.style.display='none';
if(btn){btn.disabled=false;btn.textContent='🔄 Refresh Live Data'}
if(ct)ct.innerHTML='<div style="padding:20px;text-align:center;color:var(--red)">Error: '+e.message+'. <button onclick="loadRegionalReports()" style="color:var(--blue);background:none;border:none;cursor:pointer;text-decoration:underline">Retry</button></div>';
})}

// Accordion wrapper
function _rptAccordion(id,title,sub,open,content){
return '<details'+(open?' open':'')+' style="margin-bottom:12px;border:1px solid var(--border);border-radius:14px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,.03)"><summary style="padding:14px 18px;background:var(--surface);cursor:pointer;list-style:none;display:flex;justify-content:space-between;align-items:center;user-select:none" onclick="this.parentElement.classList.toggle(\'rpt-open\')"><div><div style="font-family:Sora,sans-serif;font-size:13px;font-weight:800;color:var(--text)">'+title+'</div><div style="font-size:9px;color:#2d4373;margin-top:2px">'+sub+'</div></div><span style="font-size:14px;color:#2d4373;transition:transform .2s">▾</span></summary><div style="padding:16px 18px;border-top:1px solid var(--border)">'+content+'</div></details>'
}

// ═══ HELPERS ═══
function _rptVal(obj,key){return obj&&obj[key]!==undefined?obj[key]:null}
function _rptPrice(v,pre){if(!v||!v.price)return'<span style="color:var(--text3)">N/A</span>';var c=v.change>=0?'var(--green)':'var(--red)';return '<span style="font-weight:800;font-family:var(--mono);color:var(--text)">'+(pre||'')+(v.price||0).toLocaleString()+'</span> <span style="font-size:9px;font-weight:700;color:'+c+'">'+(v.change>=0?'▲ +':'▼ ')+Math.abs(v.change).toFixed(2)+'%</span>'}
function _rptChgBadge(v){if(!v||v.change===undefined)return'';var c=v.change>=0?'#10b981':'#ef4444';return '<span style="font-size:8px;padding:2px 8px;border-radius:100px;background:'+c+'12;color:'+c+';font-weight:800">'+(v.change>=0?'+':'')+v.change.toFixed(2)+'%</span>'}
function _rptYtdBadge(v){if(!v||!v.ytd)return'';var c=v.ytd>=0?'#10b981':'#ef4444';return '<span style="font-size:8px;padding:2px 8px;border-radius:100px;background:'+c+'12;color:'+c+';font-weight:700">YTD '+(v.ytd>=0?'+':'')+v.ytd.toFixed(1)+'%</span>'}
function _rptCard(label,val,pre,sub,accent){
if(!val||!val.price)return '<div style="padding:12px;border-radius:10px;background:#f1f5f9;border:1px solid var(--border);text-align:center;opacity:.5"><div style="font-size:8px;color:#2d4373;font-weight:700;letter-spacing:.5px">'+label+'</div><div style="font-size:11px;color:#2d4373;margin-top:4px">N/A</div></div>';
var c=val.change>=0?'var(--green)':'var(--red)';
var ac=accent||c;
return '<div style="padding:12px;border-radius:10px;background:var(--surface);border:1px solid var(--border);border-top:3px solid '+ac+';text-align:center"><div style="font-size:8px;color:#2d4373;font-weight:700;letter-spacing:.5px">'+label+'</div><div style="font-size:18px;font-weight:900;color:var(--text);font-family:var(--mono);margin:4px 0">'+(pre||'')+(val.price||0).toLocaleString()+'</div><div style="font-size:10px;font-weight:700;color:'+c+'">'+(val.change>=0?'▲ +':'▼ ')+Math.abs(val.change).toFixed(2)+'%</div>'+(val.ytd?'<div style="font-size:8px;color:#2d4373;margin-top:2px">YTD '+(val.ytd>=0?'+':'')+val.ytd.toFixed(1)+'%</div>':'')+(sub?'<div style="font-size:8px;color:#2d4373;margin-top:2px">'+sub+'</div>':'')+'</div>'
}

// ═══ SECTION RENDERERS ═══

// 1. MACRO
function _rptMacro(d){
var m=d.macro||{};var in_=m.india||{};var us=m.usa||{};var rk=m.risk||{};
var h='<div style="padding:10px 14px;border-radius:8px;background:rgba(26,86,219,.03);border-left:3px solid #1a56db;margin-bottom:14px;font-size:10px;color:var(--text2);line-height:1.7"><strong style="color:#1a56db">🧠 Fund Manager\'s Lens:</strong> This is the first thing every institutional investor checks at 9 AM — <strong>are the major economies expanding or contracting?</strong> Think of indices like the body temperature of a market. If both Nifty and S&P are green, global money is in "risk-on" mode (investors are confident). If VIX is spiking, they\'re scared. Bond yields tell you where the "safe money" is going — when yields rise, stocks face competition from bonds. <strong>The analogy:</strong> Indices are like the vital signs monitor in a hospital. You don\'t need to understand every beep, but if the heartbeat (index) is steady and blood pressure (VIX) is normal — the patient (market) is healthy.</div>';
h+='<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px">';
// INDIA
h+='<div><div style="display:flex;align-items:center;gap:6px;margin-bottom:10px"><span style="font-size:16px">IN</span><span style="font-family:Sora,sans-serif;font-size:12px;font-weight:800;color:var(--text)">India</span></div>';
h+='<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:8px">';
h+=_rptCard('NIFTY 50',in_.nifty50,'','','#1a56db');
h+=_rptCard('SENSEX',in_.sensex,'','','#1a56db');
h+=_rptCard('BANK NIFTY',in_.banknifty,'','','#1A3A78');
h+='</div></div>';
// USA
h+='<div><div style="display:flex;align-items:center;gap:6px;margin-bottom:10px"><span style="font-size:16px">US</span><span style="font-family:Sora,sans-serif;font-size:12px;font-weight:800;color:var(--text)">USA</span></div>';
h+='<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:8px">';
h+=_rptCard('S&P 500',us.sp500,'','','#059669');
h+=_rptCard('DOW JONES',us.dow,'','','#059669');
h+=_rptCard('NASDAQ',us.nasdaq,'','','#06b6d4');
h+=_rptCard('RUSSELL 2K',us.russell2000,'','Small caps','#d97706');
h+='</div></div>';
h+='</div>';
// RISK GAUGES
h+='<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">';
var vix=rk.vix||{};var vp=vix.price||0;
var vc=vp>25?'#ef4444':vp>18?'#f59e0b':vp>14?'#3b82f6':'#10b981';
var vl=vp>25?'HIGH FEAR — expect big swings':vp>18?'ELEVATED — caution advised':vp>14?'NORMAL — standard market':vp>0?'LOW FEAR — calm markets':'N/A';
h+='<div style="padding:14px;border-radius:12px;background:'+vc+'06;border:1px solid '+vc+'20;text-align:center">';
h+='<div style="font-size:8px;color:var(--text3);font-weight:700;letter-spacing:1px">😱 VIX FEAR GAUGE</div>';
h+='<div style="font-size:32px;font-weight:900;color:'+vc+';font-family:var(--mono);margin:4px 0">'+(vp?vp.toFixed(1):'—')+'</div>';
h+='<div style="font-size:9px;color:'+vc+';font-weight:700">'+vl+'</div>';
h+='<div style="margin-top:8px;height:6px;border-radius:8px;background:linear-gradient(90deg,#10b981,#f59e0b,#ef4444);position:relative">';
var vpos=Math.min(95,Math.max(5,vp/40*100));
h+='<div style="position:absolute;top:-3px;left:'+vpos+'%;width:12px;height:12px;border-radius:50%;background:#fff;border:2px solid '+vc+';transform:translateX(-50%)"></div>';
h+='</div></div>';
// US 10Y
var y10=rk.us10y||{};
var yc=y10.price>4.5?'#ef4444':y10.price>3.5?'#f59e0b':'#10b981';
h+='<div style="padding:14px;border-radius:12px;background:'+yc+'06;border:1px solid '+yc+'20;text-align:center">';
h+='<div style="font-size:8px;color:var(--text3);font-weight:700;letter-spacing:1px">📊 US 10-YEAR YIELD</div>';
h+='<div style="font-size:32px;font-weight:900;color:'+yc+';font-family:var(--mono);margin:4px 0">'+(y10.price?y10.price.toFixed(2)+'%':'—')+'</div>';
h+='<div style="font-size:9px;color:'+yc+';font-weight:700">'+(y10.price>4.5?'HIGH — pressures equity valuations & EM flows':y10.price>3.5?'MODERATE — watch for rate-sensitive sectors':'LOW — supportive of equity markets')+'</div>';
h+='</div></div>';
// INSIGHT
h+='<div style="margin-top:12px;padding:10px 14px;border-radius:8px;background:rgba(99,102,241,.04);border-left:3px solid #6366f1;font-size:10px;color:var(--text2);line-height:1.7">';
h+='<strong style="color:#6366f1">💡 Reading:</strong> ';
var nifty_chg=(in_.nifty50||{}).change||0;var sp_chg=(us.sp500||{}).change||0;
if(nifty_chg>0&&sp_chg>0)h+='Both India and US markets are positive today — global risk-on sentiment. ';
else if(nifty_chg<0&&sp_chg<0)h+='Both markets declining — possible global risk-off event. Check VIX and bond yields for confirmation. ';
else if(nifty_chg>0&&sp_chg<0)h+='India outperforming US today — domestic factors or FII rotation into India. ';
else h+='US outperforming India — check FII flows and USD/INR for capital movement signals. ';
if(vp>20)h+='VIX above 20 signals elevated uncertainty — tighter stop losses recommended.';
else h+='VIX below 20 — normal conditions for position building.';
h+='</div>';
return h;
}

// 2. FLOWS (FII/DII)
function _rptFlows(d){
var f=d.flows||{};var fii=f.fii||{};var dii=f.dii||{};
var vc={'STRONG_BUY':'#059669','BUY':'#10b981','NEUTRAL':'#f59e0b','CAUTIOUS':'#d97706','SELL':'#ef4444'}[f.verdict]||'#6b7280';
var h='<div style="padding:10px 14px;border-radius:8px;background:rgba(5,150,105,.03);border-left:3px solid #059669;margin-bottom:14px;font-size:10px;color:var(--text2);line-height:1.7"><strong style="color:#059669">🧠 Fund Manager\'s Lens:</strong> This is arguably <strong>the most important report for Indian market investors</strong>. FII (Foreign Institutional Investors like BlackRock, Vanguard, GIC) collectively control the direction of Indian markets. When they buy, markets go up — when they sell, markets fall. DII (domestic mutual funds, LIC, pension) act as the safety net. <strong>The analogy:</strong> Think of the stock market as a swimming pool. FII flows are like turning the tap ON (buying = water fills up, prices rise) or OFF (selling = water drains, prices fall). DII is like a pump that recirculates water from the deep end — it can\'t fill the pool alone, but it prevents it from draining completely. <strong>When both FII + DII buy together, that\'s like turning on every tap — markets surge.</strong></div>';

// r63.83.0: Detect missing flow data (was rendering "+₹0Cr / NEUTRAL / 0.00x" as if real)
var _hasFlow = (fii.net && fii.net !== 0) || (fii.buy && fii.buy !== 0) || (fii.sell && fii.sell !== 0) ||
               (dii.net && dii.net !== 0) || (dii.buy && dii.buy !== 0) || (dii.sell && dii.sell !== 0) ||
               (f.history && f.history.length > 0);
if (!_hasFlow) {
  h += '<div style="padding:24px 18px;text-align:center;background:#fafbfc;border-radius:10px;border:1px dashed #cbd5e1;margin-bottom:14px">';
  h += '<div style="font-size:30px;opacity:0.4;margin-bottom:8px">💰</div>';
  h += '<div style="font-size:13px;font-weight:800;color:#1A3A78;margin-bottom:6px">FII/DII flow data unavailable today</div>';
  h += '<div style="font-size:10px;color:#64748b;line-height:1.7;max-width:520px;margin:0 auto">NSE typically publishes provisional FII/DII figures after 6:00 PM IST on trading days. If you\'re viewing this before market close, weekend, or on an exchange holiday, fresh data won\'t exist yet. If it\'s well past 6 PM on a trading day, the NSE feed may be temporarily down — retry in 10-15 minutes.</div>';
  h += '<div style="margin-top:10px;font-size:9px;color:#94a3b8;font-family:JetBrains Mono,monospace">Source: nsearchives.nseindia.com (provisional cash-segment figures)</div>';
  h += '</div>';
} else {
  // VERDICT BADGE
  h+='<div style="text-align:center;padding:14px;border-radius:12px;background:'+vc+'08;border:2px solid '+vc+'30;margin-bottom:14px">';
  h+='<div style="font-size:10px;color:var(--text3);font-weight:700;letter-spacing:1px;margin-bottom:4px">INSTITUTIONAL FLOW VERDICT</div>';
  h+='<div style="font-size:22px;font-weight:900;color:'+vc+';font-family:Sora,sans-serif">'+((f.verdict||'').replace('_',' '))+'</div>';
  h+='<div style="font-size:11px;color:var(--text2);margin-top:4px">'+(f.signal||'')+'</div>';
  h+='</div>';
  // FII vs DII CARDS
  h+='<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-bottom:14px">';
  var fc=(fii.net||0)>=0?'#10b981':'#ef4444';
  h+='<div style="padding:14px;border-radius:12px;background:'+fc+'06;border:1px solid '+fc+'20;text-align:center">';
  h+='<div style="font-size:8px;color:var(--text3);font-weight:700">🌍 FII/FPI</div>';
  h+='<div style="font-size:22px;font-weight:900;color:'+fc+';font-family:var(--mono);margin:4px 0">'+((fii.net||0)>=0?'+':'')+'₹'+(fii.net||0).toLocaleString()+'Cr</div>';
  h+='<div style="font-size:8px;color:var(--text3)">Buy: ₹'+(fii.buy||0).toLocaleString()+'Cr · Sell: ₹'+(fii.sell||0).toLocaleString()+'Cr</div>';
  h+='<div style="font-size:8px;color:var(--text3);margin-top:2px">'+(fii.date||'')+'</div></div>';
  var dc=(dii.net||0)>=0?'#10b981':'#ef4444';
  h+='<div style="padding:14px;border-radius:12px;background:'+dc+'06;border:1px solid '+dc+'20;text-align:center">';
  h+='<div style="font-size:8px;color:var(--text3);font-weight:700">🏦 DII (MF/Insurance)</div>';
  h+='<div style="font-size:22px;font-weight:900;color:'+dc+';font-family:var(--mono);margin:4px 0">'+((dii.net||0)>=0?'+':'')+'₹'+(dii.net||0).toLocaleString()+'Cr</div>';
  h+='<div style="font-size:8px;color:var(--text3)">Buy: ₹'+(dii.buy||0).toLocaleString()+'Cr · Sell: ₹'+(dii.sell||0).toLocaleString()+'Cr</div>';
  h+='<div style="font-size:8px;color:var(--text3);margin-top:2px">'+(dii.date||'')+'</div></div>';
  var cmbC=(f.combined||0)>=0?'#10b981':'#ef4444';
  h+='<div style="padding:14px;border-radius:12px;background:'+cmbC+'06;border:1px solid '+cmbC+'20;text-align:center">';
  h+='<div style="font-size:8px;color:var(--text3);font-weight:700">🤝 COMBINED</div>';
  h+='<div style="font-size:22px;font-weight:900;color:'+cmbC+';font-family:var(--mono);margin:4px 0">'+((f.combined||0)>=0?'+':'')+'₹'+(f.combined||0).toLocaleString()+'Cr</div>';
  h+='<div style="font-size:8px;color:var(--text3)">DII/FII Ratio: '+(f.ratio!=null?Number(f.ratio).toFixed(2):'—')+'x</div>';
  h+='</div></div>';
  // HISTORY TABLE
  var hist=f.history||[];
  if(hist.length>0){
  h+='<div style="font-size:11px;font-weight:700;color:var(--text);margin-bottom:6px">📊 Last '+hist.length+' Trading Days</div>';
  h+='<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:9px">';
  h+='<tr style="background:#f1f5f9"><th style="padding:6px 8px;text-align:left;color:var(--text3);border-bottom:1px solid var(--border)">Date</th><th style="padding:6px;text-align:right;color:#1a56db;border-bottom:1px solid var(--border)">FII Net</th><th style="padding:6px;text-align:right;color:#1A3A78;border-bottom:1px solid var(--border)">DII Net</th><th style="padding:6px;text-align:right;font-weight:800;border-bottom:1px solid var(--border)">Combined</th></tr>';
  hist.slice().reverse().forEach(function(r){
  var fn=r.fii_net||0;var dn=r.dii_net||0;var cm=r.combined||0;
  h+='<tr style="border-bottom:1px solid var(--border)"><td style="padding:5px 8px;color:var(--text2)">'+r.date+'</td>';
  h+='<td style="padding:5px;text-align:right;font-weight:700;color:'+(fn>=0?'#10b981':'#ef4444')+';font-family:var(--mono)">'+(fn>=0?'+':'')+'₹'+fn.toLocaleString()+'</td>';
  h+='<td style="padding:5px;text-align:right;font-weight:700;color:'+(dn>=0?'#10b981':'#ef4444')+';font-family:var(--mono)">'+(dn>=0?'+':'')+'₹'+dn.toLocaleString()+'</td>';
  h+='<td style="padding:5px;text-align:right;font-weight:800;color:'+(cm>=0?'#10b981':'#ef4444')+';font-family:var(--mono)">'+(cm>=0?'+':'')+'₹'+cm.toLocaleString()+'</td></tr>';
  });
  h+='</table></div>';
  }
}
h+='<div style="margin-top:8px;padding:8px 12px;border-radius:8px;background:#3b82f608;border-left:3px solid #3b82f6;font-size:9px;color:var(--text2);line-height:1.7"><strong style="color:#3b82f6">What this means:</strong> FII (Foreign like BlackRock) and DII (Indian mutual funds) control market direction. Both buying = strong rally. Both selling = sharp fall. FII selling + DII buying = range-bound.<br><strong style="color:#3b82f6">Your action:</strong> If FII is buying >2000 Cr → markets will likely go up, safe to buy stocks. If FII selling >2000 Cr → wait before deploying fresh capital. DII buying provides floor but cannot push markets alone.</div>';
h+='<div style="margin-top:10px;padding:8px 12px;border-radius:8px;background:rgba(99,102,241,.04);border-left:3px solid #6366f1;font-size:9px;color:var(--text2);line-height:1.7"><strong style="color:#6366f1">💡</strong> FII = Foreign Institutional Investors (global funds like BlackRock, Vanguard). DII = Domestic Institutional Investors (Indian mutual funds, LIC, pension). When both buy together, markets rally hard. When both sell, expect sharp corrections.</div>';
return h;
}

// 3. CURRENCY
function _rptCurrency(d){
var c=d.currency||{};
var h='<div style="padding:10px 14px;border-radius:8px;background:rgba(217,119,6,.03);border-left:3px solid #d97706;margin-bottom:14px;font-size:10px;color:var(--text2);line-height:1.7"><strong style="color:#d97706">🧠 Fund Manager\'s Lens:</strong> Currency is the <strong>invisible tax (or bonus) on every international investment</strong>. If you buy US stocks from India, you make TWO bets — one on the stock, one on USD/INR. A fund manager always checks: is the Dollar strengthening (bad for India, good for US exporters) or weakening (good for EM, bad for Dollar returns)? DXY (Dollar Index) is the master signal. <strong>The analogy:</strong> Currency is like the conveyor belt at an airport. Your suitcase (investment return) might be perfect, but if the belt (exchange rate) moves in the wrong direction, your suitcase ends up somewhere you didn\'t expect. A 15%% stock gain minus 5%% rupee appreciation = only 10%% in your pocket.</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px">';
// USD/INR
h+='<div style="padding:16px;border-radius:12px;background:linear-gradient(135deg,rgba(26,86,219,.04),rgba(99,102,241,.02));border:1px solid var(--border)">';
h+='<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px"><span style="font-size:11px;font-weight:800;color:var(--text)">IN USD/INR</span>'+_rptChgBadge(c.usdinr)+'</div>';
h+='<div style="font-size:28px;font-weight:900;color:var(--text);font-family:var(--mono)">₹'+((c.usdinr||{}).price||0).toFixed(2)+'</div>';
h+='<div style="font-size:9px;color:var(--text3);margin-top:4px">'+c.impact_india+'</div>';
h+='</div>';
// DXY
h+='<div style="padding:16px;border-radius:12px;background:linear-gradient(135deg,rgba(5,150,105,.04),rgba(6,182,212,.02));border:1px solid var(--border)">';
h+='<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px"><span style="font-size:11px;font-weight:800;color:var(--text)">💵 Dollar Index (DXY)</span>'+_rptChgBadge(c.dxy)+'</div>';
h+='<div style="font-size:28px;font-weight:900;color:var(--text);font-family:var(--mono)">'+((c.dxy||{}).price||0).toFixed(2)+'</div>';
h+='<div style="font-size:9px;color:var(--text3);margin-top:4px">'+c.impact_us+'</div>';
h+='</div></div>';
// CROSS RATES
h+='<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:8px;margin-bottom:14px">';
[{k:'eurusd',l:'EUR/USD',p:''},{k:'gbpusd',l:'GBP/USD',p:''},{k:'usdjpy',l:'USD/JPY',p:'¥'},{k:'usdcny',l:'USD/CNY',p:'¥'}].forEach(function(x){
h+=_rptCard(x.l,c[x.k],x.p,'','#3b82f6');
});
h+='</div>';
// DRAG EXAMPLE
var drag=c.drag_example||{};
if(drag.stock_return){
h+='<div style="padding:14px;border-radius:12px;background:rgba(245,158,11,.04);border:1px solid rgba(245,158,11,.15)">';
h+='<div style="font-size:11px;font-weight:800;color:#d97706;margin-bottom:8px">📐 Currency Drag Calculator</div>';
h+='<div style="display:grid;grid-template-columns:1fr auto 1fr auto 1fr;gap:8px;align-items:center;text-align:center">';
h+='<div style="padding:10px;border-radius:8px;background:var(--surface)"><div style="font-size:7px;color:#2d4373">Stock Return</div><div style="font-size:18px;font-weight:900;color:#10b981;font-family:var(--mono)">+'+drag.stock_return+'%</div></div>';
h+='<div style="font-size:16px;color:var(--text3)">−</div>';
h+='<div style="padding:10px;border-radius:8px;background:var(--surface)"><div style="font-size:7px;color:#2d4373">Currency Move</div><div style="font-size:18px;font-weight:900;color:#ef4444;font-family:var(--mono)">'+Math.abs(drag.currency_move)+'%</div></div>';
h+='<div style="font-size:16px;color:var(--text3)">=</div>';
var rrc=drag.real_return>=0?'#10b981':'#ef4444';
h+='<div style="padding:10px;border-radius:8px;background:'+rrc+'08;border:1px solid '+rrc+'20"><div style="font-size:7px;color:#2d4373">Real Return</div><div style="font-size:18px;font-weight:900;color:'+rrc+';font-family:var(--mono)">'+(drag.real_return>=0?'+':'')+drag.real_return+'%</div></div>';
h+='</div>';
h+='<div style="font-size:9px;color:var(--text3);margin-top:8px;line-height:1.6">💡 If you invest in US stocks from India, your returns are affected by USD/INR movements. A 10% stock gain minus 2% rupee strengthening = only 8% actual return. Currency hedged ETFs eliminate this risk but cost ~0.5% extra.</div>';
h+='</div>';
}
return h;
}

// 4. SECTORS
function _rptSectors(d){
var s=d.sectors||{};var us=s.us||{};var ind=s.india||{};var com=s.commodities||{};
var h='<div style="padding:10px 14px;border-radius:8px;background:rgba(245,158,11,.03);border-left:3px solid #f59e0b;margin-bottom:14px;font-size:10px;color:var(--text2);line-height:1.7"><strong style="color:#f59e0b">🧠 Fund Manager\'s Lens:</strong> Sector rotation is <strong>how the smart money plays the business cycle</strong>. At the start of a recovery, they buy financials and industrials. Mid-cycle, they shift to tech and consumer discretionary. Late cycle, they rotate into healthcare and staples. Knowing which sectors are HOT today vs last month tells you where in the cycle we are. <strong>The analogy:</strong> Think of sectors like cricket players in a batting lineup. Tech bats in the power play (early aggression), financials are your middle-order steadiers, and defensives (staples, utilities) are the finishers who hold when things get tough. Knowing who\'s at the crease tells you what innings the market is in.</div>';
h+='<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px">';
// US SECTORS
h+='<div><div style="display:flex;align-items:center;gap:6px;margin-bottom:10px"><span style="font-size:14px">US</span><span style="font-family:Sora,sans-serif;font-size:11px;font-weight:800;color:var(--text)">US Sector ETFs</span></div>';
h+='<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(100px,1fr));gap:6px">';
var usMap={tech:'XLK Tech',financials:'XLF Finance',energy:'XLE Energy',healthcare:'XLV Health',industrials:'XLI Indust.',staples:'XLP Staples',discretionary:'XLY Discr.',realestate:'XLRE Real Est.'};
Object.keys(usMap).forEach(function(k){h+=_rptCard(usMap[k],us[k],'$','','#3b82f6')});
h+='</div></div>';
// INDIA SECTORS
h+='<div><div style="display:flex;align-items:center;gap:6px;margin-bottom:10px"><span style="font-size:14px">IN</span><span style="font-family:Sora,sans-serif;font-size:11px;font-weight:800;color:var(--text)">India Sector ETFs</span></div>';
h+='<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(100px,1fr));gap:6px">';
var inMap={nifty_etf:'NIFTYBEES',bank_etf:'BANKBEES',it_etf:'ITBEES',pharma_etf:'PHARMABEES'};
Object.keys(inMap).forEach(function(k){h+=_rptCard(inMap[k],ind[k],'₹','','#d97706')});
h+='</div></div>';
h+='</div>';
// COMMODITIES
h+='<div style="margin-bottom:10px"><div style="font-family:Sora,sans-serif;font-size:11px;font-weight:800;color:var(--text);margin-bottom:8px">🛢️ Commodities & Crypto</div>';
h+='<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:8px">';
var comMap={gold:'🥇 Gold',silver:'🥈 Silver',crude_wti:'🛢️ WTI Crude',crude_brent:'🛢️ Brent',natgas:'🔥 Nat Gas',bitcoin:'₿ Bitcoin'};
Object.keys(comMap).forEach(function(k){h+=_rptCard(comMap[k],com[k],'$','','#f59e0b')});
h+='</div></div>';
// SECTOR INSIGHT
h+='<div style="padding:10px 14px;border-radius:8px;background:rgba(99,102,241,.04);border-left:3px solid #6366f1;font-size:9px;color:var(--text2);line-height:1.7">';
h+='<strong style="color:#6366f1">💡 Sector Rotation:</strong> ';
var bestUS='',bestUSc=-999;
Object.keys(us).forEach(function(k){if(us[k]&&us[k].change>bestUSc){bestUSc=us[k].change;bestUS=k}});
if(bestUS)h+='Strongest US sector today: <strong style="color:#10b981">'+bestUS.toUpperCase()+' (+'+bestUSc.toFixed(2)+'%)</strong>. ';
var oilChg=(com.crude_wti||{}).change||0;
if(Math.abs(oilChg)>2)h+='Oil moved '+(oilChg>0?'up':'down')+' '+Math.abs(oilChg).toFixed(1)+'% — '+(oilChg>0?'energy stocks benefit, India importers hurt':'energy stocks fall, India benefits from lower import bill')+'.';
h+='</div>';
return h;
}

// 5. EM vs DM
function _rptEmDm(d){
var e=d.em_vs_dm||{};var em=e.emerging||{};var dm=e.developed||{};
var h='<div style="padding:10px 14px;border-radius:8px;background:rgba(217,119,6,.03);border-left:3px solid #d97706;margin-bottom:14px;font-size:10px;color:var(--text2);line-height:1.7"><strong style="color:#d97706">🧠 Fund Manager\'s Lens:</strong> This is the <strong>most critical asset allocation decision</strong> — how much to put in India (Emerging Market) vs USA (Developed Market). When global risk appetite is high, money floods into EM for higher growth. When fear rises, it rushes back to the "safe haven" US Dollar and US treasuries. INDA (India ETF) vs SPY (US ETF) YTD tells you who\'s winning this year. <strong>The analogy:</strong> Think of EM as a high-growth startup and DM as a blue-chip company. The startup (India) can 3x your money but has more volatility. The blue-chip (US) gives steady 10-12% but won\'t surprise you. The art is knowing when to tilt towards which — and this chart tells you.</div>';
h+='<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px">';
h+='<div><div style="font-family:Sora,sans-serif;font-size:11px;font-weight:800;color:#d97706;margin-bottom:8px">🌏 Emerging Markets</div>';
h+='<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">';
h+=_rptCard('EEM (EM ETF)',em.em_etf,'$','Broad EM','#d97706');
h+=_rptCard('INDA (India)',em.india_etf,'$','India ETF','#f59e0b');
h+=_rptCard('FXI (China)',em.china_etf,'$','China ETF','#ef4444');
h+=_rptCard('VWO (EM)',em.vwo,'$','Vanguard EM','#d97706');
h+='</div></div>';
h+='<div><div style="font-family:Sora,sans-serif;font-size:11px;font-weight:800;color:#059669;margin-bottom:8px">🏛️ Developed Markets</div>';
h+='<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">';
h+=_rptCard('SPY (US)',dm.spy,'$','S&P 500 ETF','#059669');
h+=_rptCard('EFA (ex-US)',dm.developed_ex_us,'$','Europe/Japan','#3b82f6');
h+='</div></div>';
h+='</div>';
// COMPARISON
var inda_ytd=(em.india_etf||{}).ytd||0;var fxi_ytd=(em.china_etf||{}).ytd||0;var spy_ytd=(dm.spy||{}).ytd||0;var eem_ytd=(em.em_etf||{}).ytd||0;
h+='<div style="padding:14px;border-radius:12px;background:linear-gradient(135deg,rgba(217,119,6,.04),rgba(5,150,105,.02));border:1px solid var(--border)">';
h+='<div style="font-size:11px;font-weight:800;color:var(--text);margin-bottom:8px">📊 YTD Performance Comparison</div>';
var items=[{l:'US S&P 500 (SPY)',v:spy_ytd},{l:'India (INDA)',v:inda_ytd},{l:'🇨🇳 China (FXI)',v:fxi_ytd},{l:'🌏 EM Broad (EEM)',v:eem_ytd}];
items.sort(function(a,b){return b.v-a.v});
items.forEach(function(it){
var w=Math.min(100,Math.max(5,Math.abs(it.v)*2.5));var c=it.v>=0?'#10b981':'#ef4444';
h+='<div style="display:flex;align-items:center;gap:8px;margin-bottom:4px">';
h+='<div style="width:120px;font-size:9px;font-weight:600;color:var(--text);text-align:right;flex-shrink:0">'+it.l+'</div>';
h+='<div style="flex:1;height:14px;background:#f1f5f9;border-radius:3px;overflow:hidden"><div style="width:'+w+'%;height:100%;background:'+c+';border-radius:3px;opacity:.7"></div></div>';
h+='<div style="width:55px;font-size:10px;font-weight:700;color:'+c+';font-family:var(--mono);text-align:right">'+(it.v>=0?'+':'')+it.v.toFixed(1)+'%</div>';
h+='</div>';
});
h+='</div>';
h+='<div style="margin-top:8px;padding:8px 12px;border-radius:8px;background:#3b82f608;border-left:3px solid #3b82f6;font-size:9px;color:var(--text2);line-height:1.7"><strong style="color:#3b82f6">What this means:</strong> FII (Foreign like BlackRock) and DII (Indian mutual funds) control market direction. Both buying = strong rally. Both selling = sharp fall. FII selling + DII buying = range-bound.<br><strong style="color:#3b82f6">Your action:</strong> If FII is buying >2000 Cr → markets will likely go up, safe to buy stocks. If FII selling >2000 Cr → wait before deploying fresh capital. DII buying provides floor but cannot push markets alone.</div>';
h+='<div style="margin-top:10px;padding:8px 12px;border-radius:8px;background:rgba(99,102,241,.04);border-left:3px solid #6366f1;font-size:9px;color:var(--text2);line-height:1.7"><strong style="color:#6366f1">💡</strong> '+(inda_ytd>spy_ytd?'India is outperforming the US this year — capital is flowing into emerging markets. Consider increasing India allocation.':spy_ytd>inda_ytd?'US markets are leading — the safe-haven Dollar and tech dominance continue. India may catch up if FII flows reverse.':'India and US are neck-and-neck — diversification across both is the optimal play.')+'</div>';
return h;
}

// 6. GEOPOLITICAL
function _rptGeo(d){
var g=d.geopolitical||{};var sigs=g.signals||[];
var _geoIntro='<div style="padding:10px 14px;border-radius:8px;background:rgba(239,68,68,.03);border-left:3px solid #ef4444;margin-bottom:14px;font-size:10px;color:var(--text2);line-height:1.7"><strong style="color:#ef4444">🧠 Fund Manager\'s Lens:</strong> Geopolitics is the <strong>wildcard no spreadsheet can predict</strong>. Wars, trade sanctions, elections, OPEC decisions — these override ALL fundamental analysis. These signals are auto-generated from cross-market patterns: when gold surges + VIX spikes + oil moves, the market is telling you something before the news does. <strong>The analogy:</strong> Geopolitics is like weather for your investment farm. You can have the best seeds (stocks), perfect soil (fundamentals) — but if a hurricane hits, nothing matters. These signals are your weather radar.</div>';
if(!sigs.length)return _geoIntro+'<div style="padding:20px;text-align:center;color:var(--text3);font-size:11px">No active geopolitical signals detected — skies are clear.</div>';
var h='<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:10px">';
sigs.forEach(function(s){
h+='<div style="padding:14px;border-radius:12px;background:'+s.color+'06;border:1px solid '+s.color+'20;border-left:4px solid '+s.color+'">';
h+='<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">';
h+='<span style="font-size:12px;font-weight:800;color:'+s.color+';font-family:Sora,sans-serif">'+s.theme+'</span>';
h+='<span style="font-size:8px;padding:2px 8px;border-radius:100px;background:'+s.color+'15;color:'+s.color+';font-weight:800">'+s.signal+'</span>';
h+='</div>';
h+='<div style="font-size:10px;color:var(--text2);line-height:1.6">'+s.detail+'</div>';
h+='</div>';
});
h+='</div>';
h+='<div style="margin-top:8px;padding:8px 12px;border-radius:8px;background:#3b82f608;border-left:3px solid #3b82f6;font-size:9px;color:var(--text2);line-height:1.7"><strong style="color:#3b82f6">What this means:</strong> FII (Foreign like BlackRock) and DII (Indian mutual funds) control market direction. Both buying = strong rally. Both selling = sharp fall. FII selling + DII buying = range-bound.<br><strong style="color:#3b82f6">Your action:</strong> If FII is buying >2000 Cr → markets will likely go up, safe to buy stocks. If FII selling >2000 Cr → wait before deploying fresh capital. DII buying provides floor but cannot push markets alone.</div>';
h+='<div style="margin-top:10px;padding:8px 12px;border-radius:8px;background:rgba(99,102,241,.04);border-left:3px solid #6366f1;font-size:9px;color:var(--text2);line-height:1.7"><strong style="color:#6366f1">💡</strong> These signals are auto-generated from live cross-market data patterns — not manual analysis. They update every 5 minutes. Use them as directional context, not trade triggers.</div>';
return h;
}

// Scroll to section — uses CSS scroll-margin-top for sticky header offset
