if(rg>20)sc+=8;else if(rg>10)sc+=4;else if(rg<0)sc-=6;
if(eg>20)sc+=7;else if(eg>10)sc+=3;else if(eg<0)sc-=6;
sc=Math.max(-100,Math.min(100,sc));
