// ═══ 1. DARK/LIGHT THEME TOGGLE ═══
(function initTheme(){
const saved='light'; localStorage.setItem('celesys-theme','light');
document.documentElement.setAttribute('data-theme',saved);
window._currentTheme=saved;
})();

function toggleTheme(){
const cur=document.documentElement.getAttribute('data-theme')==='dark'?'dark':'light';
const next=cur==='dark'?'light':'dark';
document.documentElement.setAttribute('data-theme',next);
window._currentTheme=next;
try{localStorage.setItem('theme',next);}catch(e){}
const btn=document.getElementById('themeToggleBtn');
if(btn)btn.innerHTML=next==='dark'?'\u2600\uFE0F':'\u{1F303}';
}

// ═══ 1b. DARK-MODE DARKIFIER for JS-rendered reports (inline-styled light cards) ═══
// Class-based dark CSS can't reach inline styles in dynamically-rendered reports
// (Institutional Terminal, Deep DD, "In plain English" boxes, engines, etc.).
// Rewrites light inline backgrounds/text -> dark equivalents when dark mode is on,
// stores the original so toggling back to light restores exactly. Two observers:
// childList (new renders) + data-theme attribute (theme flips).
(function(){
  var BG={
    '#ffffff':'#152238','#fff':'#152238','#f8fafc':'#0f1a2e','#f9fafb':'#0f1a2e',
    '#f1f5f9':'#1a2742','#f3f4f6':'#1a2742','#e2e8f0':'#243352','#eef2ff':'#1c2440',
    '#eff6ff':'#13233b','#f0f9ff':'#13233b','#e0f2fe':'#13233b','#ecfeff':'#0e2a30',
    '#f0fdfa':'#0c2a26','#f0fdf4':'#0e2a1e','#dcfce7':'#0e2a1e','#fef2f2':'#2a1414',
    '#fee2e2':'#2a1414','#fffbeb':'#2a2410','#fefce8':'#26240f','#fff7ed':'#2a1d10',
    '#faf5ff':'#1e1430','#fdf4ff':'#241433'
  };
  var TX={
    '#0f172a':'#f1f5f9','#1e293b':'#e2e8f0','#0f766e':'#5eead4','#334155':'#cbd5e1',
    '#475569':'#94a3b8','#64748b':'#94a3b8','#1e40af':'#93c5fd','#0369a1':'#7dd3fc',
    '#166534':'#6ee7b7','#15803d':'#6ee7b7','#92400e':'#fcd34d','#b45309':'#fbbf24',
    '#991b1b':'#fca5a5','#b91c1c':'#fca5a5'
  };
  function isDark(){ try{ return (document.documentElement.getAttribute('data-theme')==='dark')||(document.body&&document.body.getAttribute('data-theme')==='dark'); }catch(e){ return false; } }
  function darkifyEl(el){
    if(!el||!el.getAttribute||el.getAttribute('data-lstyle')!=null) return;
    var st=el.getAttribute('style'); if(!st) return;
    var out=st, k;
    for(k in BG){ out=out.replace(new RegExp('(^|[;\\s])(background(?:-color)?\\s*:\\s*)'+k+'\\b','gi'),'$1$2'+BG[k]); }
    for(k in TX){ out=out.replace(new RegExp('(^|[;\\s])(color\\s*:\\s*)'+k+'\\b','gi'),'$1$2'+TX[k]); }
    if(out!==st){ el.setAttribute('data-lstyle',st); el.setAttribute('style',out); }
  }
  function undarkifyEl(el){ if(!el||!el.getAttribute) return; var o=el.getAttribute('data-lstyle'); if(o!=null){ el.setAttribute('style',o); el.removeAttribute('data-lstyle'); } }
  function walk(root,fn){ if(!root) return; if(root.getAttribute&&root.getAttribute('style'))fn(root); if(root.querySelectorAll){ var els=root.querySelectorAll('[style]'); for(var i=0;i<els.length;i++)fn(els[i]); } }
  window._applyReportDark=function(){ var d=isDark(); try{ var sc=document.querySelectorAll(d?'[style]':'[data-lstyle]'); for(var i=0;i<sc.length;i++){ d?darkifyEl(sc[i]):undarkifyEl(sc[i]); } }catch(e){} };
  window._darkifyTree=function(r){ if(isDark()) walk(r,darkifyEl); };
  try{
    var obs=new MutationObserver(function(muts){ if(!isDark())return; for(var j=0;j<muts.length;j++){ var an=muts[j].addedNodes; for(var i=0;i<an.length;i++){ if(an[i].nodeType===1) walk(an[i],darkifyEl); } } });
    obs.observe(document.documentElement,{childList:true,subtree:true});
    var obs2=new MutationObserver(function(){ if(window._applyReportDark) window._applyReportDark(); });
    obs2.observe(document.documentElement,{attributes:true,attributeFilter:['data-theme']});
    if(document.body) obs2.observe(document.body,{attributes:true,attributeFilter:['data-theme']});
  }catch(e){}
  try{ if(isDark() && window._applyReportDark) window._applyReportDark(); }catch(e){}
})();

// ═══ 2. PDF EXPORT ═══
async function exportPDF(){
if(!window._isPdfUser)return;

// If on the investor-decide tab, use the dedicated print-based PDF export
// html2canvas-based export fails on complex investor-decide pages (blank pages, truncation)
if(window._lastInvestorData && document.getElementById('deResult') && document.getElementById('deResult').innerHTML.length > 500){
  _investorExportPDF();
  return;
}
const btn=document.getElementById('pdfExportBtn');
if(btn){btn.innerHTML='&#9203; Generating...';btn.disabled=true;}
try{
// html2pdf loaded statically via script tag
if(!window.html2pdf){
alert('PDF library still loading. Please wait a moment and try again.');
if(btn){btn.innerHTML='&#128196;';btn.disabled=false;}
return;
}

// Get ticker name from current report header
const ticker=(document.getElementById('tickerTag')?.textContent||'Report').trim();
const company=(document.getElementById('companyName')?.textContent||'').trim();
const filename=(ticker+'_'+(company||'Celesys')+'_Report').replace(/[^a-zA-Z0-9_]/g,'_')+'.pdf';

// Clone only VISIBLE sections to avoid rendering hidden tabs
const wrapper=document.createElement('div');
wrapper.style.cssText='padding:16px;font-family:DM Sans,sans-serif;max-width:800px';

// Add header
wrapper.innerHTML='<div style="text-align:center;margin-bottom:16px;padding-bottom:12px;border-bottom:2px solid #1a56db"><div style="font-size:22px;font-weight:800;color:#1a56db;font-family:Sora,sans-serif">'+ticker+' — '+(company||'Stock Analysis')+'</div><div style="font-size:11px;color:#666;margin-top:4px">Celesys AI Report · '+(document.getElementById('timestamp')?.textContent||new Date().toLocaleDateString())+'</div></div>';

// Gather visible .sc sections from current tab
const visible=document.querySelectorAll('#tabContentArea .sc[data-tab]');
let count=0;
visible.forEach(sc=>{
if(sc.offsetParent!==null&&sc.style.display!=='none'){
const clone=sc.cloneNode(true);
// Remove interactive elements
clone.querySelectorAll('button,input,canvas,details').forEach(e=>{
if(e.tagName==='CANVAS'){
try{const img=document.createElement('img');img.src=sc.querySelector('canvas')?.toDataURL('image/png')||'';img.style.cssText='width:100%;max-height:200px';e.replaceWith(img);}catch(ex){e.remove();}
}else if(e.tagName==='DETAILS'){e.setAttribute('open','');}
else{e.remove();}
});
wrapper.appendChild(clone);
count++;
}
});

if(count===0){throw new Error('No visible content. Switch to a tab with data first.');}

// Add footer
wrapper.innerHTML+='<div style="margin-top:20px;padding-top:10px;border-top:1px solid #ddd;text-align:center;font-size:9px;color:#999">Generated by Celesys AI · celesys.ai · For educational purposes only. Not financial advice.</div>';

document.body.appendChild(wrapper);

const opt={
margin:[8,6,8,6],
filename:filename,
image:{type:'jpeg',quality:0.85},
html2canvas:{scale:1.2,useCORS:true,logging:false,backgroundColor:'#ffffff'},
jsPDF:{unit:'mm',format:'a4',orientation:'portrait'},
pagebreak:{mode:['avoid-all','css','legacy']}
};

await html2pdf().set(opt).from(wrapper).save();
document.body.removeChild(wrapper);

}catch(e){
console.error('PDF error:',e);
alert('PDF generation failed: '+e.message+'\n\nTip: Use Ctrl+P and Save as PDF as an alternative.');
}finally{
if(btn){btn.innerHTML='&#128196;';btn.disabled=false;}
}
}

// ═══ 3. SHARE (WhatsApp, Email, Copy) ═══
function shareReport(method){
const ticker=(document.getElementById('tickerTag')?.textContent||'Stock').trim();
const company=(document.getElementById('companyName')?.textContent||'').trim();
const price=window._stockData?.current_price||'';
const curr=window._stockCurr||'$';
const url=window.location.href;
const text=`📊 *${ticker}${company?' — '+company:''}* ${price?curr+price:''}

🤖 AI Stock Analysis by Celesys AI
• Piotroski F-Score, DCF Valuation, Monte Carlo
• Options Greeks, Kelly Criterion, Moat Analysis
• Elite Decision Engine with 8-Step Scoring

🔗 Analyze any stock FREE: ${url}`;

if(method==='whatsapp'){
window.open('https://api.whatsapp.com/send?text='+encodeURIComponent(text),'_blank');
}else if(method==='email'){
window.open('mailto:?subject='+encodeURIComponent(ticker+' — AI Stock Analysis | Celesys AI')+'&body='+encodeURIComponent(text),'_blank');
}else if(method==='copy'){
navigator.clipboard.writeText(text).then(()=>{
const btn=document.getElementById('copyShareBtn');
if(btn){const orig=btn.innerHTML;btn.innerHTML='&#9989; Copied!';setTimeout(()=>btn.innerHTML=orig,2000);}
}).catch(()=>prompt('Copy this link:',text));
}else if(navigator.share){
navigator.share({title:ticker+' Analysis',text:text,url:url}).catch(()=>{});
}
}

// ═══ 4. COMPARE 2 STOCKS ═══
async function compareStocks(){
const t1=document.getElementById('cmp_stock1')?.value?.trim();
const t2=document.getElementById('cmp_stock2')?.value?.trim();
const el=document.getElementById('cmp_result');
if(!t1||!t2||!el){el.innerHTML='<div style="color:var(--red);font-size:11px">Enter both stock names.</div>';return;}
el.innerHTML='<div style="text-align:center;padding:30px;color:var(--text3)"><div style="font-size:24px;animation:spin 1s linear infinite">&#9203;</div><div style="margin-top:6px;font-size:10px">Fetching data for both stocks...</div></div>';

try{
const [r1,r2]=await Promise.all([
fetch('/api/stock-data?company='+encodeURIComponent(t1)).then(r=>r.json()),
fetch('/api/stock-data?company='+encodeURIComponent(t2)).then(r=>r.json())
]);
if(!r1.success||!r2.success){el.innerHTML='<div style="color:var(--red);font-size:11px">Could not fetch data. Check stock names.</div>';return;}
renderComparison(r1,r2,el);
}catch(e){el.innerHTML='<div style="color:var(--red);font-size:11px">Error: '+e.message+'</div>';}
}

function renderComparison(a,b,el){
const S=a.currency==='INR'?'&#8377;':'$';
const _f=(v)=>{if(v==='N/A'||v===null||v===undefined)return 'N/A';const n=parseFloat(v);if(isNaN(n))return String(v);return n.toLocaleString('en-IN',{maximumFractionDigits:2});};
const _w=(va,vb,higher)=>{
if(va==='N/A'||vb==='N/A')return ['var(--text3)','var(--text3)'];
const na=parseFloat(va),nb=parseFloat(vb);
if(isNaN(na)||isNaN(nb))return ['var(--text3)','var(--text3)'];
if(higher){return na>nb?['#10b981','#ef4444']:na<nb?['#ef4444','#10b981']:['#f59e0b','#f59e0b'];}
else{return na<nb?['#10b981','#ef4444']:na>nb?['#ef4444','#10b981']:['#f59e0b','#f59e0b'];}
};

const metrics=[
{label:'Price',a:_f(a.current_price),b:_f(b.current_price),unit:S,higher:null},
{label:'Market Cap',a:_f(a.market_cap),b:_f(b.market_cap),unit:S,higher:true},
{label:'P/E Ratio',a:_f(a.pe_ratio),b:_f(b.pe_ratio),higher:false},
{label:'P/B Ratio',a:_f(a.pb_ratio),b:_f(b.pb_ratio),higher:false},
{label:'ROE',a:_f(a.roe),b:_f(b.roe),unit:'%',higher:true},
{label:'Profit Margin',a:_f(a.profit_margin),b:_f(b.profit_margin),unit:'%',higher:true},
{label:'Revenue Growth',a:_f(a.revenue_growth),b:_f(b.revenue_growth),unit:'%',higher:true},
{label:'Debt/Equity',a:_f(a.debt_to_equity),b:_f(b.debt_to_equity),higher:false},
{label:'Beta',a:_f(a.beta),b:_f(b.beta),higher:false},
{label:'Dividend Yield',a:_f(a.dividend_yield),b:_f(b.dividend_yield),unit:'%',higher:true},
{label:'EPS (TTM)',a:_f(a.eps_ttm),b:_f(b.eps_ttm),unit:S,higher:true},
{label:'Free Cash Flow',a:_f(a.free_cash_flow),b:_f(b.free_cash_flow),unit:S,higher:true},
{label:'Current Ratio',a:_f(a.current_ratio),b:_f(b.current_ratio),higher:true},
{label:'52W High',a:_f(a.week52_high),b:_f(b.week52_high),unit:S,higher:null},
{label:'52W Low',a:_f(a.week52_low),b:_f(b.week52_low),unit:S,higher:null},
{label:'Operating Margin',a:_f(a.operating_margin),b:_f(b.operating_margin),unit:'%',higher:true},
{label:'PEG Ratio',a:_f(a.peg_ratio),b:_f(b.peg_ratio),higher:false},
];

let scoreA=0,scoreB=0;
metrics.forEach(m=>{
if(m.higher===null)return;
const na=parseFloat(String(m.a).replace(/[^0-9.-]/g,'')),nb=parseFloat(String(m.b).replace(/[^0-9.-]/g,''));
if(isNaN(na)||isNaN(nb))return;
if(m.higher){if(na>nb)scoreA++;else if(nb>na)scoreB++;}
else{if(na<nb)scoreA++;else if(nb<na)scoreB++;}
});
const winner=scoreA>scoreB?a.company_name:scoreB>scoreA?b.company_name:'Tie';
const winC=scoreA>scoreB?'#10b981':scoreB>scoreA?'#3b82f6':'#f59e0b';

let h=`<div style="padding:16px;border-radius:12px;background:#ffffff;text-align:center;margin-bottom:14px">
<div style="font-size:9px;letter-spacing:2px;color:#4a6fa5">HEAD-TO-HEAD COMPARISON</div>
<div style="font-size:18px;font-weight:800;color:#0A1628;margin:4px 0">${a.company_name} <span style="color:var(--text3);font-size:14px">vs</span> ${b.company_name}</div>
<div style="font-size:13px;font-weight:700;color:${winC}">Winner: ${winner} (${scoreA}-${scoreB})</div>
</div>`;

h+=`<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:10px">
<tr style="background:rgba(59,130,246,.06)"><th style="padding:8px;text-align:left;color:var(--text3);border-bottom:1px solid var(--border)">Metric</th><th style="padding:8px;text-align:right;color:#3b82f6;border-bottom:1px solid var(--border)">${a.company_name}</th><th style="padding:8px;text-align:right;color:#8b5cf6;border-bottom:1px solid var(--border)">${b.company_name}</th><th style="padding:8px;text-align:center;color:var(--text3);border-bottom:1px solid var(--border)">Winner</th></tr>`;
metrics.forEach(m=>{
const colors=m.higher!==null?_w(m.a,m.b,m.higher):['var(--text)','var(--text)'];
const w=m.higher===null?'-':colors[0]==='#10b981'?a.company_name.split(' ')[0]:colors[1]==='#10b981'?b.company_name.split(' ')[0]:'Tie';
h+=`<tr><td style="padding:6px 8px;border-bottom:1px solid var(--border);color:var(--text2)">${m.label}</td><td style="padding:6px 8px;text-align:right;border-bottom:1px solid var(--border);color:${colors[0]};font-weight:700;font-family:var(--mono)">${m.unit||''}${m.a}</td><td style="padding:6px 8px;text-align:right;border-bottom:1px solid var(--border);color:${colors[1]};font-weight:700;font-family:var(--mono)">${m.unit||''}${m.b}</td><td style="padding:6px 8px;text-align:center;border-bottom:1px solid var(--border);font-size:9px;color:var(--text3)">${w}</td></tr>`;
});
h+='</table></div>';

h+=`<div style="padding:12px;border-radius:8px;background:rgba(139,92,246,.04);border-left:3px solid #8b5cf6;margin-top:12px">
<div style="font-size:10px;font-weight:700;color:#8b5cf6">&#128161; Comparison Insight:</div>
<div style="font-size:9px;color:var(--text2);margin-top:4px;line-height:1.8">
${winner!=='Tie'?'<strong>'+winner+'</strong> wins on '+Math.max(scoreA,scoreB)+' out of '+metrics.filter(m=>m.higher!==null).length+' comparable metrics. ':'Both stocks are evenly matched. '}
${scoreA>scoreB?a.company_name+' has better fundamentals overall. ':scoreB>scoreA?b.company_name+' has better fundamentals overall. ':'Consider sector trends and growth potential to break the tie. '}
Remember: no single comparison tells the whole story. Consider industry dynamics, management quality, and your investment timeline.
</div></div>`;
el.innerHTML=h;
}

