function _fetchAlgoSignal(sym){algoSelect(sym,null);}

// ═══ "WHAT SHOULD I DO NOW?" — One-tap decision engine ═══
function whatNow(){
var el=document.getElementById('whatNowResult');if(!el)return;
// Premium gate removed — whatNow available for all
el.style.display='block';
var reg=window._wnRegion||'IN';
var sym=reg==='US'?'SPY':'NIFTY';
var sym2=reg==='US'?'QQQ':'BANKNIFTY';
el.innerHTML='<div style="padding:12px;border-radius:12px;background:var(--surface);border:1px solid var(--border);box-shadow:var(--shadow)"><div style="display:flex;align-items:center;gap:8px"><div style="width:14px;height:14px;border:2px solid #059669;border-top-color:transparent;border-radius:50%;animation:spin .5s linear infinite"></div><span style="font-size:11px;color:#2d4373">Reading '+(reg==='US'?'US':'Indian')+' market pulse — '+sym+' + '+sym2+'...</span></div></div>';
// Fetch both indices
Promise.all([
fetch('/api/algo-signal?symbol='+sym+'&region='+reg).then(function(r){if(!r.ok)throw new Error('API error');return r.json()}),
fetch('/api/algo-signal?symbol='+sym2+'&region='+reg).then(function(r){if(!r.ok)throw new Error('API error');return r.json()}).catch(function(){return null})
]).then(function(results){
var d=results[0];var d2=results[1];
if(!d||!d.success){el.innerHTML='<div style="color:var(--red);padding:8px">Failed to read market</div>';return}
var sig=d.signal||'HOLD / WAIT';var dir=d.direction||'NEUTRAL';var tr=d.trade||{};
var _tc=d.tradeConfidence||{};var _win=_tc.estimatedWin||0;var _grade=_tc.grade||'C';
var _eng=d.engines||{};var _vix=Number((d.options||{}).vix||0);
var sC=sig.includes('BUY')?'#059669':sig==='AVOID'?'#dc2626':'#d97706';
var dC=dir==='BULLISH'?'#059669':dir==='BEARISH'?'#dc2626':'#d97706';
var S=reg==='US'?'$':'₹';
var h='<div style="padding:16px;border-radius:14px;background:var(--surface);border:2px solid '+sC+'30;box-shadow:0 8px 32px '+sC+'10">';
// Decision
h+='<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">';
h+='<div><div style="font-size:24px;font-weight:900;color:'+sC+';font-family:Sora,sans-serif">'+sig+'</div>';
h+='<div style="font-size:11px;color:var(--text2)">'+sym+' · '+dir+' · Win: '+_win+'% · Grade: '+_grade+'</div></div>';
h+='<div style="width:48px;height:48px;border-radius:50%;background:'+sC+'12;display:flex;align-items:center;justify-content:center;font-size:18px;font-weight:900;color:'+sC+';font-family:var(--mono)">'+_win+'</div>';
h+='</div>';
// Trade action
if(tr.action&&sig!=='HOLD / WAIT'&&sig!=='AVOID'){
h+='<div style="padding:10px;border-radius:8px;background:'+dC+'06;border:1px solid '+dC+'15;margin-bottom:8px">';
h+='<div style="font-size:11px;font-weight:800;color:'+dC+'">'+tr.action+'</div>';
h+='<div style="display:flex;gap:12px;font-size:10px;margin-top:4px;font-family:var(--mono)">';
h+='<span>Entry: <strong>'+S+tr.premEntry.toFixed(0)+'</strong></span>';
h+='<span style="color:#dc2626">SL: <strong>'+S+tr.premSL.toFixed(0)+'</strong></span>';
h+='<span style="color:#059669">Target: <strong>'+S+tr.premT2.toFixed(0)+'</strong></span>';
h+='<span style="color:var(--purple)">R:R: <strong>'+(tr.rrRatio||'—')+'</strong></span>';
h+='</div></div>';
}else{
h+='<div style="padding:10px;border-radius:8px;background:#d9770606;border:1px solid #d9770615;font-size:11px;color:#d97706;font-weight:700;margin-bottom:8px">⏸️ No clear setup — WAIT for better opportunity</div>';
}
// VIX + Reason
h+='<div style="display:flex;gap:8px;font-size:9px;flex-wrap:wrap">';
if(_vix>0){var vxC=_vix<14?'#059669':_vix<20?'#1a56db':_vix<25?'#d97706':'#dc2626';h+='<span style="padding:2px 8px;border-radius:8px;background:'+vxC+'08;color:'+vxC+';font-weight:700">Fear: '+_vix.toFixed(1)+' '+(_vix<14?'Calm':_vix<20?'OK':_vix<25?'Nervous':'High')+'</span>';}
if(d.reasoning)h+='<span style="color:var(--text3);flex:1;min-width:200px">'+d.reasoning.substring(0,150)+'...</span>';
h+='</div>';
// Deep dive link
h+='<div style="margin-top:8px;text-align:center"><button onclick="switchTabGroup(\'trading\');setTimeout(function(){switchTab(\'trades\');algoSelect(\''+sym+'\',null)},200)" style="padding:4px 16px;border-radius:6px;background:linear-gradient(135deg,#1A3A78,#1e40af);color:#fff;border:none;font-size:9px;font-weight:700;cursor:pointer">📊 Full '+sym+' Analysis →</button></div>';
h+='</div>';
// Second index summary
if(d2&&d2.success){
var sig2=d2.signal||'HOLD';var dir2=d2.direction||'NEUTRAL';
var sC2=sig2.includes('BUY')?'#059669':sig2==='AVOID'?'#dc2626':'#d97706';
h+='<div style="padding:10px;border-radius:10px;border:1px solid '+sC2+'20;background:'+sC2+'04;margin-top:8px;display:flex;justify-content:space-between;align-items:center">';
h+='<div><div style="font-size:8px;color:var(--text3);font-weight:700">'+sym2+'</div><div style="font-size:16px;font-weight:900;color:'+sC2+'">'+sig2+'</div><div style="font-size:8px;color:var(--text3)">'+dir2+'</div></div>';
var tr2=d2.trade||{};
if(tr2.action){h+='<div style="text-align:right;font-size:8px;font-family:var(--mono)"><div style="color:var(--text3)">'+tr2.action+'</div><div>Entry: '+S+tr2.premEntry.toFixed(0)+' · SL: '+S+tr2.premSL.toFixed(0)+'</div></div>';}
h+='<button onclick="switchTabGroup(\'trading\');setTimeout(function(){switchTab(\'trades\');algoSelect(\''+sym2+'\',null)},200)" style="padding:3px 10px;border-radius:5px;background:'+sC2+';color:#fff;border:none;font-size:8px;font-weight:700;cursor:pointer">→</button>';
h+='</div>';
}
// Close button
h+='<div style="text-align:center;margin-top:6px"><button onclick="document.getElementById(\'whatNowResult\').style.display=\'none\'" style="padding:3px 12px;border-radius:8px;background:#f1f5f9;border:1px solid var(--border);color:#2d4373;font-size:8px;cursor:pointer">✕ Close</button></div>';
el.innerHTML=h;
}).catch(function(e){el.innerHTML='<div style="color:var(--red);padding:8px;font-size:10px">'+e.message+'</div>'});
}

// ═══ VOICE INPUT for AI Assistant ═══
function startVoiceInput(){
if(!('webkitSpeechRecognition' in window)&&!('SpeechRecognition' in window)){
alert('Voice input not supported in this browser. Try Chrome or Edge.');return;
}
var SR=window.SpeechRecognition||window.webkitSpeechRecognition;
var recognition=new SR();
recognition.lang='en-IN';recognition.continuous=false;recognition.interimResults=false;
var btn=document.getElementById('voiceBtn');
if(btn){btn.style.background='#dc2626';btn.textContent='🎙️ Listening...';}
recognition.onresult=function(e){
var text=e.results[0][0].transcript;
var input=document.getElementById('aiQuestion');
if(input)input.value=text;
if(btn){btn.style.background='#f1f5f9';btn.textContent='🎙️';}
askAI();
};
recognition.onerror=function(){if(btn){btn.style.background='#f1f5f9';btn.textContent='🎙️';}};
recognition.onend=function(){if(btn){btn.style.background='#f1f5f9';btn.textContent='🎙️';}};
recognition.start();
}

// ═══ EXPLAIN MY LOSS — Post-trade analysis ═══
function explainLoss(tradeId){
var el=document.getElementById('lossExplain_'+tradeId);
if(el&&el.style.display==='block'){el.style.display='none';return}
if(!el){
var row=document.querySelector('[data-tradeid="'+tradeId+'"]');
if(!row)return;
el=document.createElement('div');el.id='lossExplain_'+tradeId;
el.style.cssText='padding:10px;background:#f1f5f9;border-radius:8px;margin:6px 0';
row.after(el);
}
el.style.display='block';
el.innerHTML='<div style="font-size:9px;color:var(--text3)">Analyzing what went wrong...</div>';
// Get the trade data
var trades=window._journalTrades||[];
var trade=trades.find(function(t){return t.id===tradeId});
if(!trade){el.innerHTML='<div style="color:var(--red);font-size:9px">Trade not found</div>';return}
var entry=trade.entryPrem||0;var exit=trade.exitPrem||0;var pnl=trade.pnl||0;
var sym=trade.symbol||'';
// Analyze
var h='<div style="font-size:10px;font-weight:800;color:#dc2626;margin-bottom:6px">🔍 Loss Analysis — '+sym+' '+trade.optType+' '+trade.strike+'</div>';
h+='<div style="font-size:9px;color:var(--text2);line-height:1.7">';
if(exit>0&&entry>0){
var lossPct=((exit-entry)/entry*100).toFixed(1);
h+='<strong>Entry:</strong> ₹'+entry+' → <strong>Exit:</strong> ₹'+exit+' (<span style="color:#dc2626">'+lossPct+'%</span>)<br>';
if(Math.abs(parseFloat(lossPct))>30){
h+='⚠️ <strong>Large loss ('+lossPct+'%).</strong> Your SL was either too wide or not respected.<br>';
h+='💡 <strong>Fix:</strong> Set SL at entry and NEVER move it against you. Maximum 20% premium loss per trade.<br>';
}else if(Math.abs(parseFloat(lossPct))>15){
h+='⚠️ <strong>Moderate loss.</strong> This is within acceptable range if your winners are bigger.<br>';
}else{
h+='✅ <strong>Small loss — well managed.</strong> This is healthy risk control.<br>';
}
}
// Check if direction was wrong
h+='<strong>Possible causes:</strong><br>';
h+='• Direction wrong — market moved against your bias<br>';
h+='• Timing wrong — entered too early/late<br>';
h+='• IV crush — options lost value even though stock moved right<br>';
h+='• Theta decay — held too long near expiry<br>';
h+='<br><strong>Questions to ask yourself:</strong><br>';
h+='• Did I follow my SL? If not, that\'s a discipline issue.<br>';
h+='• Was the setup confluent (3+ factors aligned)?<br>';
h+='• Did I check IV before entry? High IV = expensive options.<br>';
h+='• Was I revenge trading after a previous loss?<br>';
h+='</div>';
el.innerHTML=h;
}

// ═══ STOCK INTELLIGENCE TAB ═══
window._siRegion='IN';
function switchSIRegion(reg){
window._siRegion=reg;
document.getElementById('siRegIN').style.background=reg==='IN'?'#1a56db':'var(--bg2)';
document.getElementById('siRegIN').style.color=reg==='IN'?'#fff':'var(--text3)';
document.getElementById('siRegUS').style.background=reg==='US'?'#1a56db':'var(--bg2)';
document.getElementById('siRegUS').style.color=reg==='US'?'#fff':'var(--text3)';
document.getElementById('siStocksIN').style.display=reg==='IN'?'flex':'none';
document.getElementById('siStocksUS').style.display=reg==='US'?'flex':'none';
// Clear results on region switch
var siR=document.getElementById('siResult');
if(siR)siR.innerHTML='<div style="text-align:center;padding:40px"><div style="font-size:40px;margin-bottom:8px;opacity:.3">🔬</div><div style="font-size:14px;font-weight:700;color:var(--text);margin-bottom:4px">Select a '+(reg==='US'?'US':'Indian')+' stock above</div><div style="font-size:11px;color:var(--text3);max-width:420px;margin:0 auto">Region switched to <strong>'+(reg==='US'?'USA':'India')+'</strong>. Pick a stock or type any ticker to get the full 13-section report.</div></div>';
var tpR=document.getElementById('topPicksResult');
if(tpR)tpR.innerHTML='<div style="text-align:center;padding:20px;color:var(--text3);font-size:10px">Click <strong>Scan All Stocks</strong> to analyze <strong>'+(reg==='US'?'70+ US':'200+ NSE')+'</strong> stocks for '+(reg==='US'?'USA':'India')+'</div>';
// Reset loading flags
_topPicksLoading=false;
_sectorLoading=false;
var secR=document.getElementById('sectorIntelResult');
if(secR)secR.innerHTML='<div style="text-align:center;padding:20px;color:var(--text3);font-size:10px">Click <strong>Scan Sectors</strong> to find top 5 stocks per sector for '+(reg==='US'?'USA':'India')+'</div>';
}
var _siLoading=false;
function runStockIntel(sym){
if(!sym)return;
if(_siLoading){return}  // Prevent rapid clicks
_siLoading=true;
setTimeout(function(){_siLoading=false},3000);  // 3s cooldown between requests
var el=document.getElementById('siResult');if(!el)return;
var reg=window._siRegion||'IN';
var S=reg==='US'?'$':'₹';
el.innerHTML='<div style="padding:20px"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px"><div><div style="height:14px;width:100px;border-radius:8px;background:#f1f5f9;animation:shimmer 1.5s infinite;background-size:200% 100%;background-image:linear-gradient(90deg,var(--bg2) 25%,var(--bg3) 50%,var(--bg2) 75%);margin-bottom:6px"></div><div style="height:24px;width:150px;border-radius:8px;background:#f1f5f9;animation:shimmer 1.5s infinite;background-size:200% 100%;background-image:linear-gradient(90deg,var(--bg2) 25%,var(--bg3) 50%,var(--bg2) 75%)"></div></div><div style="width:60px;height:60px;border-radius:50%;background:#f1f5f9;animation:shimmer 1.5s infinite;background-size:200% 100%;background-image:linear-gradient(90deg,var(--bg2) 25%,var(--bg3) 50%,var(--bg2) 75%)"></div></div><div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:12px"><div style="height:80px;border-radius:10px;background:#f1f5f9;animation:shimmer 1.5s infinite;background-size:200% 100%;background-image:linear-gradient(90deg,var(--bg2) 25%,var(--bg3) 50%,var(--bg2) 75%)"></div><div style="height:80px;border-radius:10px;background:#f1f5f9;animation:shimmer 1.5s infinite;animation-delay:.15s;background-size:200% 100%;background-image:linear-gradient(90deg,var(--bg2) 25%,var(--bg3) 50%,var(--bg2) 75%)"></div><div style="height:80px;border-radius:10px;background:#f1f5f9;animation:shimmer 1.5s infinite;animation-delay:.3s;background-size:200% 100%;background-image:linear-gradient(90deg,var(--bg2) 25%,var(--bg3) 50%,var(--bg2) 75%)"></div></div><div style="text-align:center;font-size:11px;color:#2d4373"><div style="display:inline-block;width:14px;height:14px;border:2px solid #0891b2;border-top-color:transparent;border-radius:50%;animation:spin .5s linear infinite;vertical-align:middle;margin-right:6px"></div>Analyzing '+sym+' — fundamentals, valuation, price action & smart money</div></div>';
fetch('/api/stock-intel?symbol='+encodeURIComponent(sym)+'&region='+reg).then(function(r){if(!r.ok)throw new Error('API error '+r.status);return r.json()}).then(function(d){
if(!d.success){el.innerHTML='<div style="color:var(--red);padding:16px">'+d.error+'</div>';return}
var h='';
// ── HERO DECISION CARD ──
h+='<div style="border-radius:16px;border:2px solid '+d.decColor+'30;box-shadow:0 8px 32px '+d.decColor+'10;margin-bottom:16px">';
h+='<div style="padding:20px 24px;background:linear-gradient(135deg,'+d.decColor+'10,'+d.decColor+'04)">';
h+='<div style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:12px">';
// Left: Decision
h+='<div><div style="font-size:10px;color:var(--text3);font-weight:700;letter-spacing:1px;margin-bottom:4px">'+d.companyName+' · '+d.sector+'</div>';
h+='<div style="font-size:36px;font-weight:900;color:'+d.decColor+';font-family:Sora,sans-serif;letter-spacing:-1px">'+d.decision+'</div>';
h+='<div style="font-size:14px;font-weight:700;color:var(--text);margin-top:4px">'+d.symbol+' · '+d.csym+d.price.toLocaleString("en-IN")+'</div></div>';
// Right: Score circle
h+='<div style="text-align:center"><svg width="80" height="80" viewBox="0 0 80 80"><circle cx="40" cy="40" r="34" fill="none" stroke="var(--bg2)" stroke-width="5"/>';
var _cl=2*3.14159*34;var _co=_cl*(1-d.confidence/100);
h+='<circle cx="40" cy="40" r="34" fill="none" stroke="'+d.decColor+'" stroke-width="5" stroke-linecap="round" stroke-dasharray="'+_cl+'" stroke-dashoffset="'+_co+'" transform="rotate(-90 40 40)"/>';
h+='<text x="40" y="36" text-anchor="middle" font-size="20" font-weight="900" fill="'+d.decColor+'" font-family="var(--mono)">'+d.confidence+'</text>';
h+='<text x="40" y="50" text-anchor="middle" font-size="8" fill="var(--text3)">CONFIDENCE</text></svg></div>';
h+='</div>';
// Trade plan strip
if(d.tradePlan){var tp=d.tradePlan;
h+='<div style="display:flex;gap:0;margin-top:12px;border-radius:10px;overflow:hidden;font-size:10px;text-align:center">';
h+='<div style="flex:1;padding:8px;background:#05966910"><div style="font-size:7px;color:#059669;font-weight:700">ENTRY ZONE</div><div style="font-weight:800;color:#059669;font-family:var(--mono)">'+d.csym+tp.entry[0]+' – '+d.csym+tp.entry[1]+'</div></div>';
h+='<div style="flex:1;padding:8px;background:#dc262610"><div style="font-size:7px;color:#dc2626;font-weight:700">STOP LOSS</div><div style="font-weight:800;color:#dc2626;font-family:var(--mono)">'+d.csym+tp.sl+'</div></div>';
h+='<div style="flex:1;padding:8px;background:#05966910"><div style="font-size:7px;color:#059669;font-weight:700">TARGET 1</div><div style="font-weight:800;color:#059669;font-family:var(--mono)">'+d.csym+tp.t1+'</div></div>';
h+='<div style="flex:1;padding:8px;background:#04785710"><div style="font-size:7px;color:#047857;font-weight:700">TARGET 2</div><div style="font-weight:800;color:#047857;font-family:var(--mono)">'+d.csym+tp.t2+'</div></div>';
h+='<div style="flex:0.6;padding:8px;background:#1A3A7810"><div style="font-size:7px;color:#1A3A78;font-weight:700">R:R</div><div style="font-weight:800;color:#1A3A78;font-family:var(--mono)">1:'+tp.rr+'</div></div>';
h+='</div>';}
h+='</div></div>';

// ── 3-SCORE GAUGE ROW ──
var sections=[d.fundamental,d.valuation,d.priceAction];
var secNames=['Fundamentals','Valuation','Price Action'];
var secVerdicts=[d.fundamental.verdict,d.valuation.verdict,d.priceAction.trend];
var secColors=sections.map(function(s){return s.score>=65?'#059669':s.score>=40?'#d97706':'#dc2626'});
h+='<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:16px">';
sections.forEach(function(sec,i){
h+='<div style="padding:14px;border-radius:12px;background:var(--surface);border:1px solid var(--border);text-align:center;box-shadow:var(--shadow-sm)">';
h+='<div style="font-size:9px;color:var(--text3);font-weight:700;margin-bottom:6px">'+secNames[i]+'</div>';
// Mini gauge
h+='<div style="position:relative;width:50px;height:50px;margin:0 auto 6px"><svg width="50" height="50" viewBox="0 0 50 50"><circle cx="25" cy="25" r="20" fill="none" stroke="var(--bg2)" stroke-width="4"/>';
var _mcl=2*3.14159*20;var _mco=_mcl*(1-sec.score/100);
h+='<circle cx="25" cy="25" r="20" fill="none" stroke="'+secColors[i]+'" stroke-width="4" stroke-linecap="round" stroke-dasharray="'+_mcl+'" stroke-dashoffset="'+_mco+'" transform="rotate(-90 25 25)"/>';
h+='<text x="25" y="28" text-anchor="middle" font-size="14" font-weight="900" fill="'+secColors[i]+'" font-family="var(--mono)">'+sec.score+'</text></svg></div>';
h+='<div style="font-size:10px;font-weight:800;color:'+secColors[i]+'">'+secVerdicts[i]+'</div>';
h+='</div>';
});
h+='</div>';

// ── DETAIL SECTIONS (Progressive Disclosure) ──
function siSection(title,emoji,content){
return '<details style="margin-bottom:8px;border:1px solid var(--border);border-radius:10px;overflow:hidden"><summary style="padding:10px 14px;background:#f1f5f9;cursor:pointer;list-style:none;display:flex;justify-content:space-between;align-items:center"><span style="font-size:11px;font-weight:800;color:var(--text)">'+emoji+' '+title+'</span><span style="font-size:8px;color:#2d4373">tap ▾</span></summary><div style="padding:12px 14px">'+content+'</div></details>';
}

// 1. Fundamentals detail
var fc='';
d.fundamental.flags.forEach(function(f){var c=f.startsWith('+')?'#059669':f.startsWith('-')?'#dc2626':'var(--text2)';fc+='<div style="font-size:9px;color:'+c+';line-height:1.6;padding:2px 0">'+f+'</div>';});
function _mc(label,val,unit,goodFn,badFn,tip){
if(!val&&val!==0)return '';
var v=parseFloat(val);if(isNaN(v))return '';
var c=goodFn(v)?'#059669':badFn(v)?'#dc2626':'#d97706';
return '<div style="padding:8px;border-radius:8px;background:'+c+'06;border:1px solid '+c+'12"><div style="font-size:7px;color:#2d4373;font-weight:700">'+label+'</div><div style="font-size:14px;font-weight:900;color:'+c+';font-family:var(--mono)">'+v+(unit||'')+'</div><div style="font-size:7px;color:'+c+'">'+tip(v)+'</div></div>';
}
fc+='<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(90px,1fr));gap:6px;margin-top:8px;font-size:9px;text-align:center">';
fc+=_mc('Revenue Growth',d.fundamental.revGrowth,'%',function(v){return v>10},function(v){return v<0},function(v){return v>20?'🚀 Excellent':v>5?'✅ Good':v<0?'⚠️ Declining':'Slow'});
fc+=_mc('Earnings Growth',d.fundamental.earnGrowth,'%',function(v){return v>15},function(v){return v<-5},function(v){return v>20?'🚀 Surging':v>0?'✅ Growing':'⚠️ Shrinking'});
fc+=_mc('Profit Margin',d.fundamental.profitMargin,'%',function(v){return v>12},function(v){return v<3},function(v){return v>20?'💪 Very strong':v>10?'✅ Healthy':'⚠️ Thin'});
fc+=_mc('Gross Margin',d.fundamental.grossMargin,'%',function(v){return v>35},function(v){return v<15},function(v){return v>40?'🏰 Wide moat':v>25?'✅ Good':'Competitive pressure'});
fc+=_mc('ROE',d.fundamental.roe,'%',function(v){return v>15},function(v){return v<5},function(v){return v>20?'🏆 Excellent — great capital use':v>10?'✅ Good':'Weak capital use'});
fc+=_mc('ROCE',d.fundamental.roce,'%',function(v){return v>12},function(v){return v<5},function(v){return v>15?'Efficient operations':v>8?'Decent':'Low return on capital'});
fc+=_mc('Debt/Equity',d.fundamental.debtEquity,'%',function(v){return v<50},function(v){return v>150},function(v){return v<30?'💚 Low debt':v<100?'OK':'🚨 Heavy debt — risky'});
fc+='</div>';
if(d.fundamental.revGrowth===0&&d.fundamental.roe===0&&d.fundamental.profitMargin===0){
fc+='<div style="padding:8px;border-radius:6px;background:#d9770608;border:1px solid #d9770615;margin-top:6px;font-size:9px;color:#d97706">⚠️ Limited fundamental data from Yahoo Finance for this stock. The scoring relies more on price action (45% weight). Try the Overview tab after analyzing this stock for more data.</div>';
}
h+=siSection('Fundamental Analysis — Is the business good?','📊',fc);

// 2. Valuation detail
var vc='';
d.valuation.flags.forEach(function(f){var c=f.startsWith('+')?'#059669':f.startsWith('-')?'#dc2626':'var(--text2)';vc+='<div style="font-size:9px;color:'+c+';line-height:1.6;padding:2px 0">'+f+'</div>';});
vc+='<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(90px,1fr));gap:6px;margin-top:8px;font-size:9px;text-align:center">';
vc+=_mc('PE Ratio',d.valuation.pe,'x',function(v){return v>0&&v<20},function(v){return v>40},function(v){return v===0?'N/A':v<15?'💎 Cheap':v<25?'Fair':v<40?'Pricey':'🚨 Expensive'});
vc+=_mc('Forward PE',d.valuation.fwdPE,'x',function(v){return v>0&&v<d.valuation.pe},function(v){return v>d.valuation.pe},function(v){return v===0?'N/A':v<d.valuation.pe?'🟢 Earnings growing':'🔴 May shrink'});
vc+=_mc('PEG',d.valuation.peg,'',function(v){return v>0&&v<1},function(v){return v>2},function(v){return v===0?'N/A':v<1?'💎 Growth at discount':v<2?'Fair':'🚨 Overpriced for growth'});
vc+=_mc('P/B',d.valuation.pb,'x',function(v){return v>0&&v<3},function(v){return v>8},function(v){return v===0?'N/A':v<1?'Below book!':v<3?'Reasonable':'Premium valuation'});
vc+='</div>';
// Analyst target price
if(d.valuation.targetPrice>0){
var _up=((d.valuation.targetPrice-d.price)/d.price*100).toFixed(1);
var _uC=parseFloat(_up)>0?'#059669':'#dc2626';
vc+='<div style="padding:8px 12px;border-radius:8px;background:'+_uC+'06;border:1px solid '+_uC+'15;margin-top:8px;display:flex;justify-content:space-between;align-items:center">';
vc+='<div><div style="font-size:8px;color:var(--text3);font-weight:700">ANALYST TARGET PRICE</div><div style="font-size:14px;font-weight:900;color:'+_uC+';font-family:var(--mono)">'+d.csym+d.valuation.targetPrice.toLocaleString()+'</div></div>';
vc+='<div style="text-align:right"><div style="font-size:16px;font-weight:900;color:'+_uC+'">'+_up+'%</div><div style="font-size:8px;color:var(--text3)">'+(d.valuation.analystCount||0)+' analysts</div></div>';
vc+='</div>';
}
if(d.valuation.pe===0&&d.valuation.fwdPE===0){
vc+='<div style="padding:8px;border-radius:6px;background:#d9770608;border:1px solid #d9770615;margin-top:6px;font-size:9px;color:#d97706">⚠️ Valuation data not available — likely an index or ETF, or Yahoo Finance didn\'t return PE data for this stock.</div>';
}
h+=siSection('Valuation — Am I paying a fair price?','💰',vc);

// 3. Price Action
var pac='<div style="font-size:10px;color:var(--text);margin-bottom:6px"><strong>Trend:</strong> <span style="color:'+(d.priceAction.trend==='BULLISH'?'#059669':d.priceAction.trend==='BEARISH'?'#dc2626':'#d97706')+'">'+d.priceAction.trend+'</span> — '+d.priceAction.trendDetail+'</div>';
pac+='<div style="display:grid;grid-template-columns:repeat(2,1fr);gap:6px;font-size:9px">';
pac+='<div style="padding:6px;border-radius:6px;background:#05966906;border-left:3px solid #059669"><strong>Floor (Support)</strong><br>'+d.csym+d.priceAction.support.toLocaleString("en-IN")+'</div>';
pac+='<div style="padding:6px;border-radius:6px;background:#dc262606;border-left:3px solid #dc2626"><strong>Ceiling (Resistance)</strong><br>'+d.csym+d.priceAction.resistance.toLocaleString("en-IN")+'</div>';
pac+='<div style="padding:6px;border-radius:6px;background:#f1f5f9"><strong>Volume</strong>: '+d.priceAction.volConfirm+'</div>';
pac+='<div style="padding:6px;border-radius:6px;background:#f1f5f9"><strong>Breakout above</strong>: '+d.csym+d.priceAction.breakout.toLocaleString("en-IN")+'</div>';
pac+='</div>';
h+=siSection('Price Action — What is the chart saying?','📈',pac);

// 4. Confluence
h+=siSection('Confluence — Do all signals agree?','🎯','<div style="font-size:10px;line-height:1.6">'+d.confluence.alignment.join('<br>')+'</div><div style="margin-top:6px;font-size:9px;color:var(--text3)">Confluence score: <strong style="color:var(--text)">'+d.confluence.score+'/100</strong> (Fundamentals 30% + Valuation 25% + Price 45%)</div>');

// 8. Market Context + India-specific data
var mctx='<div style="font-size:10px"><strong>Sector:</strong> '+d.sector+' / '+d.industry+'<br><strong>Aligned with market?</strong> '+(d.marketContext.aligned?'Yes — stock moving with broader trend ✅':'No — swimming against the current ⚠️')+'</div>';
var nse=d.nseExtra||{};
if(nse.dataSource){
mctx+='<div style="font-size:8px;color:var(--text3);margin-top:6px">📡 Data source: <strong>'+nse.dataSource+'</strong></div>';
}
// India-specific: Delivery %, Promoter, FII/DII, Sector PE
if(nse.deliveryPct>0||nse.promoterHolding>0||nse.sectorPE>0){
mctx+='<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(90px,1fr));gap:6px;margin-top:8px;font-size:9px;text-align:center">';
if(nse.deliveryPct>0){var dC=nse.deliveryPct>50?'#059669':nse.deliveryPct>30?'#d97706':'#dc2626';mctx+='<div style="padding:6px;border-radius:6px;background:'+dC+'06;border:1px solid '+dC+'12"><div style="font-size:7px;color:#2d4373">Delivery %</div><div style="font-weight:800;color:'+dC+'">'+nse.deliveryPct.toFixed(1)+'%</div><div style="font-size:6px;color:'+dC+'">'+(nse.deliveryPct>50?'Genuine buying':'Speculative')+'</div></div>';}
if(nse.promoterHolding>0){mctx+='<div style="padding:6px;border-radius:6px;background:#f1f5f9"><div style="font-size:7px;color:#2d4373">Promoter</div><div style="font-weight:800">'+nse.promoterHolding.toFixed(1)+'%</div></div>';}
if(nse.fiiHolding>0){mctx+='<div style="padding:6px;border-radius:6px;background:#f1f5f9"><div style="font-size:7px;color:#2d4373">FII</div><div style="font-weight:800">'+nse.fiiHolding.toFixed(1)+'%</div></div>';}
if(nse.diiHolding>0){mctx+='<div style="padding:6px;border-radius:6px;background:#f1f5f9"><div style="font-size:7px;color:#2d4373">DII</div><div style="font-weight:800">'+nse.diiHolding.toFixed(1)+'%</div></div>';}
if(nse.sectorPE>0){mctx+='<div style="padding:6px;border-radius:6px;background:#f1f5f9"><div style="font-size:7px;color:#2d4373">Sector PE</div><div style="font-weight:800">'+nse.sectorPE.toFixed(1)+'x</div></div>';}
if(nse.eps>0){mctx+='<div style="padding:6px;border-radius:6px;background:#f1f5f9"><div style="font-size:7px;color:#2d4373">EPS</div><div style="font-weight:800">₹'+nse.eps.toFixed(1)+'</div></div>';}
if(nse.bookValue>0){mctx+='<div style="padding:6px;border-radius:6px;background:#f1f5f9"><div style="font-size:7px;color:#2d4373">Book Value</div><div style="font-weight:800">₹'+nse.bookValue.toFixed(0)+'</div></div>';}
mctx+='</div>';
}
// Quarterly results table
if(nse.quarterlyResults&&nse.quarterlyResults.length>0){
mctx+='<div style="margin-top:8px;font-size:10px;font-weight:700;color:var(--text);margin-bottom:4px">📊 Quarterly Results</div>';
mctx+='<table style="width:100%;border-collapse:collapse;font-size:8px"><thead><tr style="background:#f1f5f9"><th style="padding:4px">Quarter</th><th style="padding:4px;text-align:right">Revenue (Cr)</th><th style="padding:4px;text-align:right">Net Profit (Cr)</th><th style="padding:4px;text-align:right">EPS</th></tr></thead><tbody>';
nse.quarterlyResults.forEach(function(qr){
var npC=qr.netProfit>0?'#059669':'#dc2626';
mctx+='<tr style="border-bottom:1px solid var(--border)"><td style="padding:3px">'+qr.period+'</td><td style="padding:3px;text-align:right;font-family:var(--mono)">₹'+(qr.revenue/10000000).toFixed(0)+'</td><td style="padding:3px;text-align:right;color:'+npC+';font-weight:700;font-family:var(--mono)">₹'+(qr.netProfit/10000000).toFixed(0)+'</td><td style="padding:3px;text-align:right;font-family:var(--mono)">₹'+qr.eps.toFixed(1)+'</td></tr>';
});
mctx+='</tbody></table>';
}
h+=siSection('Market Context — Is the tide with us?','🌊',mctx);

// 9. Entry Timing
var et=d.entryTiming;
var etC=et.type==='BREAKOUT'?'#059669':et.type==='PULLBACK'?'#1a56db':'#d97706';
h+=siSection('Entry Timing — When to pull the trigger?','⏱️','<div style="padding:8px;border-radius:8px;background:'+etC+'08;border:1px solid '+etC+'20"><div style="font-size:11px;font-weight:800;color:'+etC+'">'+et.signal+'</div><div style="font-size:9px;color:var(--text2);margin-top:2px">'+et.condition+'</div></div>');

// 10. Position Sizing
var szC=d.sizing.level==='AGGRESSIVE'?'#059669':d.sizing.level==='MODERATE'?'#d97706':'#6b7280';
h+=siSection('Position Sizing — How much to bet?','📐','<div style="font-size:12px;font-weight:800;color:'+szC+'">'+d.sizing.level+'</div><div style="font-size:9px;color:var(--text2)">'+d.sizing.detail+'</div>');

// 11. Smart Money
var smc='';d.smartMoney.forEach(function(s){smc+='<div style="font-size:9px;color:var(--text2);line-height:1.6;padding:2px 0">'+s+'</div>';});
h+=siSection('Smart Money — What are institutions doing?','🏦',smc);

// India-only: Shareholding + Delivery + Quarterly Results
if(d.nseExtra&&(d.nseExtra.promoterHolding>0||d.nseExtra.deliveryPct>0)){
var nseC='';
// Shareholding pie
if(d.nseExtra.promoterHolding>0||d.nseExtra.fiiHolding>0){
nseC+='<div style="font-size:10px;font-weight:800;color:var(--text);margin-bottom:6px">📊 Shareholding Pattern</div>';
nseC+='<div style="display:flex;gap:6px;margin-bottom:8px;flex-wrap:wrap">';
var _hp=function(label,val,c){return val>0?'<div style="flex:1;min-width:70px;padding:6px 8px;border-radius:8px;background:'+c+'08;border:1px solid '+c+'15;text-align:center"><div style="font-size:7px;color:#2d4373;font-weight:700">'+label+'</div><div style="font-size:16px;font-weight:900;color:'+c+';font-family:var(--mono)">'+val.toFixed(1)+'%</div></div>':'';};
nseC+=_hp('Promoters',d.nseExtra.promoterHolding,'#1A3A78');
nseC+=_hp('FII',d.nseExtra.fiiHolding,'#1a56db');
nseC+=_hp('DII',d.nseExtra.diiHolding,'#059669');
var pub=100-d.nseExtra.promoterHolding-d.nseExtra.fiiHolding-d.nseExtra.diiHolding;
if(pub>0)nseC+=_hp('Public',pub,'#d97706');
nseC+='</div>';
// Insights
if(d.nseExtra.promoterHolding>60)nseC+='<div style="font-size:8px;color:#059669;margin-bottom:2px">✅ Strong promoter conviction (>60%) — aligned with shareholders</div>';
if(d.nseExtra.promoterHolding<30&&d.nseExtra.promoterHolding>0)nseC+='<div style="font-size:8px;color:#dc2626;margin-bottom:2px">⚠️ Low promoter holding (<30%) — weak ownership signal</div>';
if(d.nseExtra.fiiHolding>25)nseC+='<div style="font-size:8px;color:#1a56db;margin-bottom:2px">🌍 High FII interest ('+d.nseExtra.fiiHolding.toFixed(0)+'%) — global investors like this</div>';
}
// Delivery %
if(d.nseExtra.deliveryPct>0){
var delC=d.nseExtra.deliveryPct>50?'#059669':d.nseExtra.deliveryPct>30?'#d97706':'#dc2626';
nseC+='<div style="margin-top:6px;padding:8px;border-radius:8px;background:'+delC+'06;border:1px solid '+delC+'15">';
nseC+='<div style="font-size:9px"><span style="font-weight:800;color:'+delC+'">Delivery: '+d.nseExtra.deliveryPct.toFixed(1)+'%</span> — ';
nseC+=d.nseExtra.deliveryPct>50?'Genuine buying — investors taking delivery':'Mostly speculative/intraday trading';
nseC+='</div></div>';
}
// Sector PE comparison
if(d.nseExtra.sectorPE>0&&d.valuation.pe>0){
var speC=d.valuation.pe<d.nseExtra.sectorPE?'#059669':'#dc2626';
nseC+='<div style="margin-top:6px;padding:8px;border-radius:8px;background:'+speC+'06;border:1px solid '+speC+'15;font-size:9px">';
nseC+='Stock PE <strong>'+d.valuation.pe+'x</strong> vs Sector PE <strong>'+d.nseExtra.sectorPE.toFixed(0)+'x</strong> — ';
nseC+=d.valuation.pe<d.nseExtra.sectorPE?'<span style="color:#059669;font-weight:700">Trading at discount to sector ✅</span>':'<span style="color:#dc2626;font-weight:700">Premium to sector</span>';
nseC+='</div>';
}
// Quarterly Results
if(d.nseExtra.quarterlyResults&&d.nseExtra.quarterlyResults.length>0){
nseC+='<div style="margin-top:8px;font-size:10px;font-weight:800;color:var(--text)">📈 Quarterly Results (Last '+d.nseExtra.quarterlyResults.length+'Q)</div>';
nseC+='<div style="overflow-x:auto;margin-top:4px"><table style="width:100%;border-collapse:collapse;font-size:8px"><thead><tr style="background:#f1f5f9"><th style="padding:4px 6px;text-align:left">Period</th><th style="padding:4px 6px;text-align:right">Revenue (Cr)</th><th style="padding:4px 6px;text-align:right">Net Profit (Cr)</th><th style="padding:4px 6px;text-align:right">EPS</th></tr></thead><tbody>';
d.nseExtra.quarterlyResults.forEach(function(qr){
var pC=qr.netProfit>0?'#059669':'#dc2626';
nseC+='<tr style="border-bottom:1px solid var(--border)"><td style="padding:3px 6px">'+qr.period+'</td>';
nseC+='<td style="padding:8px 10px;text-align:right;font-family:var(--mono)">₹'+(qr.revenue/10000000).toFixed(0)+'</td>';
nseC+='<td style="padding:8px 10px;text-align:right;font-family:var(--mono);color:'+pC+'">₹'+(qr.netProfit/10000000).toFixed(0)+'</td>';
nseC+='<td style="padding:8px 10px;text-align:right;font-family:var(--mono)">₹'+qr.eps.toFixed(1)+'</td></tr>';
});
nseC+='</tbody></table></div>';
}
// EPS + Book Value
if(d.nseExtra.eps>0||d.nseExtra.bookValue>0){
nseC+='<div style="display:flex;gap:6px;margin-top:6px">';
if(d.nseExtra.eps>0)nseC+='<div style="flex:1;padding:6px;border-radius:6px;background:#f1f5f9;text-align:center"><div style="font-size:7px;color:#2d4373;font-weight:700">EPS</div><div style="font-size:12px;font-weight:800;font-family:var(--mono)">₹'+d.nseExtra.eps.toFixed(1)+'</div></div>';
if(d.nseExtra.bookValue>0)nseC+='<div style="flex:1;padding:6px;border-radius:6px;background:#f1f5f9;text-align:center"><div style="font-size:7px;color:#2d4373;font-weight:700">Book Value</div><div style="font-size:12px;font-weight:800;font-family:var(--mono)">₹'+d.nseExtra.bookValue.toFixed(0)+'</div></div>';
nseC+='</div>';
}
h+=siSection('NSE Data — Shareholding, Delivery & Quarterly Results','IN',nseC);
}

// 12. Risk Factors
var rfc='';d.risks.forEach(function(r){rfc+='<div style="font-size:9px;color:#dc2626;line-height:1.6;padding:2px 0">⚠️ '+r+'</div>';});
h+=siSection('Risk Factors — What could go wrong?','🛑',rfc);

// 13. Invalidation
h+=siSection('Invalidation — When to abandon this idea','❌','<div style="font-size:10px;color:var(--text);line-height:1.6;padding:8px;border-radius:8px;background:#dc262606;border:1px solid #dc262612">'+d.invalidation+'</div>');

// 7. Simple Explanation (always visible at bottom)
h+='<div style="padding:14px;border-radius:12px;background:linear-gradient(135deg,rgba(8,145,178,.06),rgba(8,145,178,.02));border:1px solid rgba(8,145,178,.15);margin-top:8px">';
h+='<div style="font-size:10px;font-weight:800;color:#0891b2;margin-bottom:6px">🎓 In Simple Words</div>';
h+='<div style="font-size:10px;color:var(--text);line-height:1.6;margin-bottom:6px"><strong>Why:</strong> '+d.simple.why+'</div>';
h+='<div style="font-size:10px;color:#dc2626;line-height:1.6"><strong>Risk:</strong> '+d.simple.risk+'</div>';
h+='</div>';

el.innerHTML=h;
_siLoading=false;
}).catch(function(e){_siLoading=false;el.innerHTML='<div style="color:var(--red);padding:16px">Error: '+e.message+'</div>'});
}

// ═══ TOP PICKS — Comprehensive Intelligence Reports ═══
var _topPicksLoading=false;
function loadTopPicks(){
if(_topPicksLoading)return;
_topPicksLoading=true;
var reg=window._siRegion||'IN';
var S=reg==='US'?'$':'₹';
var el=document.getElementById('topPicksResult');
if(!el)return;
el.innerHTML='<div style="padding:16px"><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:12px">'+[1,2,3,4].map(function(i){return '<div style="height:90px;border-radius:10px;background:#f1f5f9;animation:shimmer 1.5s infinite;animation-delay:'+(i*0.1)+'s;background-size:200% 100%;background-image:linear-gradient(90deg,var(--bg2) 25%,var(--bg3) 50%,var(--bg2) 75%)"></div>'}).join('')+'</div><div style="text-align:center;font-size:10px;color:#2d4373"><div style="display:inline-block;width:14px;height:14px;border:2px solid #0891b2;border-top-color:transparent;border-radius:50%;animation:spin .5s linear infinite;vertical-align:middle;margin-right:6px"></div>Scanning '+(reg==='US'?'70+ US':'200+ NSE India')+' stocks, ETFs &amp; niche picks... First run ~2-3 min.</div></div>';
fetch('/api/top-picks?region='+reg).then(function(r){if(!r.ok)throw new Error('API error '+r.status);return r.json()}).then(function(d){
_topPicksLoading=false;
if(!d.success){el.innerHTML='<div style="color:var(--red);padding:12px;font-size:10px">'+d.error+'</div>';return}

function renderRow(pk,i){
var c=pk.decision==='BUY'?'#059669':pk.decision==='HOLD'?'#d97706':'#dc2626';
var r='<div style="display:grid;grid-template-columns:24px 1fr 70px 60px 50px 50px 50px 60px;gap:4px;align-items:center;padding:6px 8px;border-bottom:1px solid var(--border);font-size:9px;cursor:pointer;transition:background .15s" onclick="runStockIntel(\''+pk.symbol+'\')" onmouseover="this.style.background=\'#f1f5f9\'" onmouseout="this.style.background=\'transparent\'">';
r+='<span style="font-weight:800;color:var(--text3)">'+(i+1)+'</span>';
r+='<div><div style="font-weight:800;color:var(--text)">'+pk.symbol+'</div><div style="font-size:7px;color:var(--text3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100px">'+(pk.companyName||'')+'</div></div>';
r+='<span style="font-weight:800;color:var(--text);font-family:var(--mono);text-align:right">'+S+pk.price.toLocaleString("en-IN")+'</span>';
r+='<span style="font-weight:800;color:'+c+';text-align:center">'+pk.confidence+'%</span>';
r+='<span style="font-size:8px;color:'+(pk.cagr3M>=0?'#059669':'#dc2626')+';text-align:right;font-family:var(--mono)">'+(pk.cagr3M>=0?'+':'')+pk.cagr3M+'%</span>';
r+='<span style="font-size:8px;color:'+(pk.cagr1Y>=0?'#059669':'#dc2626')+';text-align:right;font-family:var(--mono)">'+(pk.cagr1Y>=0?'+':'')+pk.cagr1Y+'%</span>';
r+='<span style="font-size:8px;color:var(--text3);text-align:right;font-family:var(--mono)">'+(pk.pe>0?pk.pe+'x':'—')+'</span>';
r+='<span style="font-size:8px;font-weight:800;color:'+c+';text-align:center;padding:2px 4px;border-radius:8px;background:'+c+'10">'+pk.decision+'</span>';
r+='</div>';
return r;
}

function renderSection(title,emoji,color,picks,extra){
if(!picks||!picks.length)return '';
var s='<div style="margin-bottom:14px;border:1px solid '+color+'20;border-radius:12px;overflow:hidden">';
s+='<div style="padding:8px 12px;background:'+color+'08;display:flex;justify-content:space-between;align-items:center">';
s+='<span style="font-size:12px;font-weight:800;color:'+color+'">'+emoji+' '+title+'</span>';
if(extra)s+='<span style="font-size:8px;color:var(--text3)">'+extra+'</span>';
s+='</div>';
// Table header
s+='<div style="display:grid;grid-template-columns:24px 1fr 70px 60px 50px 50px 50px 60px;gap:4px;padding:4px 8px;font-size:7px;color:var(--text3);font-weight:700;border-bottom:1px solid var(--border)">';
s+='<span>#</span><span>Stock</span><span style="text-align:right">Price</span><span style="text-align:center">Score</span><span style="text-align:right">3M</span><span style="text-align:right">1Y</span><span style="text-align:right">PE</span><span style="text-align:center">Verdict</span></div>';
picks.forEach(function(pk,i){s+=renderRow(pk,i)});
s+='</div>';
return s;
}

var h='';
// Overall Top 5
h+=renderSection('Overall Top 5 — Best Stocks Right Now','🏆','#0891b2',d.top5,'Ranked by F(30%)+V(25%)+PA(45%)');
// Large Cap
h+=renderSection('Large Cap — Safe & Steady','🏦','#1a56db',d.largecap,'Market leaders');
// Mid Cap
h+=renderSection('Mid Cap — Growth Sweet Spot','🚀','#1A3A78',d.midcap,'High growth potential');
// Small Cap
h+=renderSection('Small Cap — High Risk, High Reward','💎','#d97706',d.smallcap,'Multibagger potential');
// ETFs
if(d.etfs&&d.etfs.length){
var ef='<div style="margin-bottom:14px;border:1px solid #05966920;border-radius:12px;overflow:hidden">';
ef+='<div style="padding:8px 12px;background:#05966908;display:flex;justify-content:space-between;align-items:center"><span style="font-size:12px;font-weight:800;color:#059669">📊 ETFs & Index Funds — Passive Wealth</span><span style="font-size:8px;color:var(--text3)">Diversified exposure</span></div>';
ef+='<div style="display:grid;grid-template-columns:24px 1fr 70px 60px 50px 50px 50px 60px;gap:4px;padding:4px 8px;font-size:7px;color:var(--text3);font-weight:700;border-bottom:1px solid var(--border)">';
ef+='<span>#</span><span>ETF</span><span style="text-align:right">Price</span><span style="text-align:center">Score</span><span style="text-align:right">3M</span><span style="text-align:right">1Y CAGR</span><span style="text-align:right">Div%</span><span style="text-align:center">Verdict</span></div>';
d.etfs.forEach(function(pk,i){
var c=pk.decision==='BUY'?'#059669':pk.decision==='HOLD'?'#d97706':'#dc2626';
ef+='<div style="display:grid;grid-template-columns:24px 1fr 70px 60px 50px 50px 50px 60px;gap:4px;align-items:center;padding:6px 8px;border-bottom:1px solid var(--border);font-size:9px;cursor:pointer;transition:background .15s" onclick="runStockIntel(\''+pk.symbol+'\')" onmouseover="this.style.background=\'#f1f5f9\'" onmouseout="this.style.background=\'transparent\'">';
ef+='<span style="font-weight:800;color:var(--text3)">'+(i+1)+'</span>';
ef+='<div><div style="font-weight:800;color:var(--text)">'+pk.symbol+'</div><div style="font-size:7px;color:var(--text3)">'+(pk.etfName||pk.sector||'')+'</div></div>';
ef+='<span style="font-weight:800;color:var(--text);font-family:var(--mono);text-align:right">'+S+pk.price.toLocaleString("en-IN")+'</span>';
ef+='<span style="font-weight:800;color:'+c+';text-align:center">'+pk.confidence+'%</span>';
ef+='<span style="font-size:8px;color:'+(pk.cagr3M>=0?'#059669':'#dc2626')+';text-align:right;font-family:var(--mono)">'+(pk.cagr3M>=0?'+':'')+pk.cagr3M+'%</span>';
ef+='<span style="font-size:8px;color:'+(pk.cagr1Y>=0?'#059669':'#dc2626')+';text-align:right;font-family:var(--mono);font-weight:700">'+(pk.cagr1Y>=0?'+':'')+pk.cagr1Y+'%</span>';
ef+='<span style="font-size:8px;color:#059669;text-align:right;font-family:var(--mono)">'+(pk.divYield>0?pk.divYield+'%':'—')+'</span>';
ef+='<span style="font-size:8px;font-weight:800;color:'+c+';text-align:center;padding:2px 4px;border-radius:8px;background:'+c+'10">'+pk.decision+'</span>';
ef+='</div>';
});
ef+='</div>';
h+=ef;
}
// Niche
h+=renderSection('Niche & Thematic — Emerging Trends','🔮','#dc2626',d.niche,'AI, Crypto, Defence, Green');
// Dividend
h+=renderSection('Top Dividend Payers — Passive Income','💰','#047857',d.dividend,'Sorted by yield');
// Momentum
h+=renderSection('Momentum Leaders — Hot Right Now','🔥','#ea580c',d.momentum,'Best 3-month returns');
// Value
h+=renderSection('Value Picks — Cheap + Growing','🎯','#1a56db',d.value,'Low PE + positive growth');

h+='<div style="text-align:center;margin-top:10px;padding:10px;border-radius:8px;background:#f1f5f9;font-size:9px;color:#2d4373;line-height:1.6">Scanned <strong style="color:var(--text)">'+d.totalScanned+'</strong> securities · <strong style="color:var(--text)">'+d.totalScored+'</strong> analyzed · Ranked by Fundamentals(30%) + Valuation(25%) + Price Action(45%)<br>Click any stock for full 13-section report · CAGR = Compound Annual Growth Rate · Not financial advice</div>';
el.innerHTML=h;
}).catch(function(e){_topPicksLoading=false;el.innerHTML='<div style="color:var(--red);padding:12px;font-size:10px">Error: '+e.message+'</div>'});
}

// ═══ P&L PAYOFF CURVE VIEWER ═══
function showPayoffCurve(sym){
var el=document.getElementById('payoffCurveArea');
if(!el){el=document.createElement('div');el.id='payoffCurveArea';el.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;z-index:999;background:rgba(0,0,0,.6);display:flex;align-items:center;justify-content:center;padding:20px';document.body.appendChild(el)}
el.style.display='flex';
el.onclick=function(ev){if(ev.target===el)el.style.display='none';};
el.innerHTML='<div style="width:90%;max-width:700px;max-height:90vh;overflow-y:auto;background:var(--surface);border-radius:16px;padding:24px;box-shadow:0 20px 60px rgba(0,0,0,.3);position:relative"><button onclick="document.getElementById(\'payoffCurveArea\').style.display=\'none\'" style="position:absolute;top:12px;right:16px;background:none;border:none;font-size:18px;cursor:pointer;color:#2d4373">✕</button><div style="text-align:center;padding:20px;color:#2d4373"><div style="display:inline-block;width:14px;height:14px;border:2px solid var(--blue);border-top-color:transparent;border-radius:50%;animation:spin .5s linear infinite;vertical-align:middle;margin-right:6px"></div>Generating P&L curves for '+sym+'...</div></div>';
var reg=window._globalRegion||'IN';
fetch('/api/payoff-curve?symbol='+encodeURIComponent(sym)+'&region='+reg).then(function(r){if(!r.ok)throw new Error('API error');return r.json()}).then(function(d){
if(!d.success){el.querySelector('div>div').innerHTML='<div style="color:var(--red)">'+d.error+'</div>';return}
var S=d.csym;var spot=d.spot;
var h='<div style="font-size:16px;font-weight:900;color:var(--text);margin-bottom:4px">📊 Strategy P&L Simulator — '+d.symbol+'</div>';
h+='<div style="font-size:10px;color:var(--text3);margin-bottom:16px">Spot: '+S+spot.toLocaleString()+'</div>';
d.curves.forEach(function(curve){
var pts=curve.dataPoints;
var maxP=Math.max.apply(null,pts.map(function(p){return p.pnl}));
var minP=Math.min.apply(null,pts.map(function(p){return p.pnl}));
var range=Math.max(Math.abs(maxP),Math.abs(minP),1);
var w=600;var ht=160;var pad=40;
h+='<div style="margin-bottom:16px;padding:12px;border:1px solid var(--border);border-radius:10px">';
h+='<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">';
h+='<div style="font-size:12px;font-weight:800;color:var(--text)">'+curve.name+'</div>';
h+='<div style="display:flex;gap:8px;font-size:8px"><span style="color:#059669;font-weight:700">Max: '+S+curve.maxProfit.toLocaleString()+'</span><span style="color:#dc2626;font-weight:700">Risk: '+S+Math.abs(curve.maxLoss).toLocaleString()+'</span><span style="color:var(--text3)">POP: '+curve.pop+'%</span></div></div>';
// SVG chart
var svgW=w;var svgH=ht;
h+='<svg width="100%" viewBox="0 0 '+svgW+' '+svgH+'" style="display:block">';
// Zero line
var zeroY=pad+(ht-2*pad)/2;
h+='<line x1="'+pad+'" y1="'+zeroY+'" x2="'+(svgW-pad)+'" y2="'+zeroY+'" stroke="var(--text3)" stroke-width="0.5" stroke-dasharray="4"/>';
// Build path
var path='';
pts.forEach(function(p,i){
var x=pad+((p.price-pts[0].price)/(pts[pts.length-1].price-pts[0].price))*(svgW-2*pad);
var y=zeroY-((p.pnl/range)*(ht-2*pad)/2);
path+=(i===0?'M':'L')+x.toFixed(1)+' '+y.toFixed(1);
});
// Fill area
var fillAbove='M'+pad+' '+zeroY;var fillBelow='M'+pad+' '+zeroY;
pts.forEach(function(p,i){
var x=pad+((p.price-pts[0].price)/(pts[pts.length-1].price-pts[0].price))*(svgW-2*pad);
var y=zeroY-((p.pnl/range)*(ht-2*pad)/2);
if(p.pnl>=0)fillAbove+=' L'+x.toFixed(1)+' '+y.toFixed(1);
else fillAbove+=' L'+x.toFixed(1)+' '+zeroY;
if(p.pnl<0)fillBelow+=' L'+x.toFixed(1)+' '+y.toFixed(1);
else fillBelow+=' L'+x.toFixed(1)+' '+zeroY;
});
h+='<path d="'+fillAbove+' L'+(svgW-pad)+' '+zeroY+' Z" fill="rgba(5,150,105,.12)"/>';
h+='<path d="'+fillBelow+' L'+(svgW-pad)+' '+zeroY+' Z" fill="rgba(220,38,38,.12)"/>';
h+='<path d="'+path+'" fill="none" stroke="var(--text)" stroke-width="2"/>';
// Spot marker
var spotX=pad+((spot-pts[0].price)/(pts[pts.length-1].price-pts[0].price))*(svgW-2*pad);
h+='<line x1="'+spotX+'" y1="'+pad+'" x2="'+spotX+'" y2="'+(svgH-pad)+'" stroke="#3b82f6" stroke-width="1" stroke-dasharray="3"/>';
h+='<text x="'+spotX+'" y="'+(pad-4)+'" text-anchor="middle" font-size="8" fill="#3b82f6">SPOT</text>';
// Labels
h+='<text x="'+pad+'" y="'+(svgH-5)+'" font-size="8" fill="var(--text3)">'+S+(pts[0].price||0).toLocaleString()+'</text>';
h+='<text x="'+(svgW-pad)+'" y="'+(svgH-5)+'" text-anchor="end" font-size="8" fill="var(--text3)">'+S+(pts[pts.length-1].price||0).toLocaleString()+'</text>';
h+='<text x="5" y="'+(pad+4)+'" font-size="8" fill="#059669">+'+S+Math.abs(range).toLocaleString()+'</text>';
h+='<text x="5" y="'+(svgH-pad-2)+'" font-size="8" fill="#dc2626">-'+S+Math.abs(range).toLocaleString()+'</text>';
h+='</svg>';
// Legs table
h+='<div style="display:flex;gap:4px;margin-top:6px;flex-wrap:wrap">';
curve.legs.forEach(function(l){
var lC=l.action==='BUY'?'#059669':'#dc2626';
h+='<span style="font-size:7px;padding:2px 6px;border-radius:8px;background:'+lC+'10;color:'+lC+';font-weight:700">'+l.action+' '+l.strike+' '+l.type+' @'+S+l.premium+'</span>';
});
if(curve.breakevens.length)h+='<span style="font-size:7px;padding:2px 6px;border-radius:8px;background:#f1f5f9;color:#2d4373">BE: '+curve.breakevens.map(function(b){return S+b.toLocaleString()}).join(' / ')+'</span>';
h+='</div></div>';
});
el.querySelector('div').innerHTML=h+'<div style="text-align:center;margin-top:10px"><button onclick="document.getElementById(\'payoffCurveArea\').style.display=\'none\'" style="padding:6px 24px;border-radius:8px;background:#f1f5f9;border:1px solid var(--border);color:var(--text);font-size:10px;font-weight:700;cursor:pointer">✕ Close</button></div><div style="text-align:center;margin-top:4px;font-size:8px;color:#2d4373">P&L at expiry · Not including brokerage/taxes</div>';
}).catch(function(e){el.querySelector('div>div').innerHTML='<div style="color:var(--red)">Error: '+e.message+'</div>'});
}

// ═══ JOURNAL REVIEW — Daily behavioral insights ═══
function loadJournalReview(){
var el=document.getElementById('journalReview');if(!el)return;
el.innerHTML='<div style="text-align:center;padding:12px;color:var(--text3);font-size:10px">Loading review...</div>';
fetch('/api/journal-review').then(function(r){if(!r.ok)throw new Error('API error');return r.json()}).then(function(d){
if(!d.success){el.innerHTML='';return}
var h='';
// Today's summary
var t=d.today;
if(t.trades>0){
var pC=t.pnl>=0?'#059669':'#dc2626';
h+='<div style="padding:12px;border-radius:10px;background:linear-gradient(135deg,'+pC+'06,transparent);border:1px solid '+pC+'15;margin-bottom:10px">';
h+='<div style="font-size:11px;font-weight:800;color:var(--text);margin-bottom:6px">📅 Today\'s Summary</div>';
h+='<div style="display:flex;gap:12px;font-size:10px;flex-wrap:wrap">';
h+='<span>Trades: <strong>'+t.trades+'</strong></span>';
h+='<span style="color:#059669">Wins: <strong>'+t.wins+'</strong></span>';
h+='<span style="color:#dc2626">Losses: <strong>'+t.losses+'</strong></span>';
if(t.open>0)h+='<span style="color:#3b82f6">Open: <strong>'+t.open+'</strong></span>';
h+='<span style="color:'+pC+';font-weight:800">P&L: ₹'+t.pnl.toLocaleString()+'</span>';
h+='</div></div>';
}
// Streak
if(d.streak.count>=2){
var sC=d.streak.type==='WIN'?'#059669':'#dc2626';
h+='<div style="padding:8px 12px;border-radius:8px;background:'+sC+'06;border:1px solid '+sC+'15;margin-bottom:10px;font-size:10px;color:'+sC+';font-weight:700">'+(d.streak.type==='WIN'?'🔥':'❄️')+' '+d.streak.count+'-trade '+d.streak.type.toLowerCase()+' streak</div>';
}
// Behavioral insights
if(d.behaviors&&d.behaviors.length>0){
h+='<div style="font-size:11px;font-weight:800;color:var(--text);margin-bottom:6px">🧠 Behavioral Insights</div>';
d.behaviors.forEach(function(b){
var bC=b.type==='CRITICAL'?'#dc2626':b.type==='WARNING'?'#d97706':'#0891b2';
h+='<div style="padding:10px 12px;border-radius:8px;background:'+bC+'06;border-left:3px solid '+bC+';margin-bottom:6px">';
h+='<div style="font-size:10px;font-weight:700;color:'+bC+';margin-bottom:3px">'+b.habit+'</div>';
h+='<div style="font-size:9px;color:var(--text2);line-height:1.5">'+b.msg+'</div>';
h+='<div style="font-size:8px;color:'+bC+';margin-top:4px;font-weight:600">💡 Fix: '+b.fix+'</div>';
h+='</div>';
});
}
if(!h)h='<div style="text-align:center;padding:12px;color:var(--text3);font-size:10px">Start logging trades to see behavioral insights</div>';
el.innerHTML=h;
}).catch(function(){el.innerHTML=''});
}

// ═══ VISUAL DECISION ENGINE ═══
window._deRegion='IN';
window._pmsRegion='IN';
function switchDERegion(reg){
window._deRegion=reg;
var inBtn=document.getElementById('deRegIN');var usBtn=document.getElementById('deRegUS');
if(inBtn){inBtn.style.background=reg==='IN'?'linear-gradient(135deg,#1A3A78,#1e40af)':'#fff';inBtn.style.color=reg==='IN'?'#fff':'#374151';}
if(usBtn){usBtn.style.background=reg==='US'?'linear-gradient(135deg,#1A3A78,#1e40af)':'#fff';usBtn.style.color=reg==='US'?'#fff':'#374151';}
var ins=document.getElementById('deStocksIN');var uss=document.getElementById('deStocksUS');
// Only show index quick-buttons in TRADER mode
if(window._deMode==='investor'){
if(ins)ins.style.display='none';if(uss)uss.style.display='none';
}else{
if(ins)ins.style.display=reg==='IN'?'flex':'none';
if(uss)uss.style.display=reg==='US'?'flex':'none';
}
if(window._fillDESelect)window._fillDESelect(reg);
var r=document.getElementById('deResult');if(r)r.innerHTML='<div style="text-align:center;padding:30px;color:var(--text3);font-size:10px">Switched to '+(reg==='US'?'USA':'India')+'. Select a stock or index.</div>';
// r63.99.16: Propagate region change to dependent scanners (ETF, 360°, Intraday Options)
try { if (typeof window._onRegionChange === 'function') window._onRegionChange(reg); } catch(_re){}
}
window._deMode='investor';

// r63.72.34: Persona system — two top-level personas (Research vs Trading)
// Research persona = Investor mode (unified fundamental + Deep DD entry)
// Trading persona  = expands to Trader / Options / Active Trading sub-modes
window._dePersona = 'research';

// Bridge: from Research persona, navigate to Deep DD sub-tab with the symbol preloaded.
window._openDeepDDFor = function(symbol) {
  try {
    if (!symbol) return;
    var sym = String(symbol).toUpperCase();
    // The Deep DD lives as a sub-tab under "Decide" group
    if (typeof showTab === 'function') {
      showTab('deepdd');
    }
    // Pre-fill the DD ticker input then trigger load
    setTimeout(function() {
      var inputIds = ['ddSymbol', 'ddTicker', 'deepDDSymbol'];
      var input = null;
      for (var i = 0; i < inputIds.length; i++) {
        input = document.getElementById(inputIds[i]);
        if (input) break;
      }
      if (input) {
        input.value = sym;
        if (typeof submitDeepDD === 'function') { submitDeepDD(); return; }
      }
      // Fallback: call loadDeepDD directly if available
      if (typeof loadDeepDD === 'function') {
        try { loadDeepDD(sym); } catch(e) { loadDeepDD(); }
      }
    }, 200);
  } catch (e) { console.warn('_openDeepDDFor failed:', e); }
};

// ═════════════════════════════════════════════════════════════════════════
// r63.72.35: Embedded Deep DD sections inside the Research (Investor) view
// Builds HTML container slots + fires the corresponding card loaders.
// Replaces the separate r63.72.34 "View Deep DD" button — research is now unified.
// ═════════════════════════════════════════════════════════════════════════

window._buildEmbeddedDDSections = function(symbol, sector, region) {
  var h = '';
  // Section divider opens the new institutional design system region
  h += '<div class="csdd-root" style="margin-top:20px">';

  // Header band — visual transition from fundamental view to institutional view
  h += '<div style="background:linear-gradient(135deg,#1A3A78,#2563eb);color:#fff;border-radius:12px;padding:16px 20px;margin-bottom:16px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px">';
  h += '<div>';
  h += '<div style="font-size:10px;letter-spacing:1px;font-weight:800;opacity:0.85;font-family:Sora,sans-serif">INSTITUTIONAL ANALYSIS</div>';
  h += '<div style="font-size:16px;font-weight:900;margin-top:2px;font-family:Sora,sans-serif">📌 Deep DD · Market Regime · 4D Positioning · Signals · External View</div>';
  h += '<div style="font-size:11px;margin-top:4px;opacity:0.85;line-height:1.4">Where the fundamental verdict above meets timing, flow, and consensus signals.</div>';
  h += '</div>';
  h += '</div>';

  // ── SECTION DD-I: CONTEXT (Market Regime + Sector Flow side-by-side) ──
  h += '<section class="csdd-section" data-csdd-section="DD-I">';
  h += '<div class="csdd-section__head">';
  h += '<span class="csdd-section__roman">DD · I</span>';
  h += '<span class="csdd-section__title">Context</span>';
  h += '<span class="csdd-section__sub">What\'s the macro &amp; sector environment?</span>';
  h += '</div>';
  h += '<div class="csdd-row-2col">';
  h += '<div id="ddMarketRegimeCard"></div>';
  h += '<div id="ddSectorFlowCard"></div>';
  h += '</div>';
  h += '</section>';

  // ── SECTION DD-II: 4D POSITIONING ──
  h += '<section class="csdd-section" data-csdd-section="DD-II">';
  h += '<div class="csdd-section__head">';
  h += '<span class="csdd-section__roman">DD · II</span>';
  h += '<span class="csdd-section__title">4D Positioning</span>';
  h += '<span class="csdd-section__sub">Flow · Valuation · Quality · Risk — the institutional decision matrix</span>';
  h += '</div>';
  h += '<div id="ddStock4DCard"></div>';
  h += '</section>';

  // ── SECTION DD-III: SIGNALS ──
  h += '<section class="csdd-section" data-csdd-section="DD-III">';
  h += '<div class="csdd-section__head">';
  h += '<span class="csdd-section__roman">DD · III</span>';
  h += '<span class="csdd-section__title">Signals</span>';
  h += '<span class="csdd-section__sub">Returns · Commentary · Demand · Ownership · Volume · Woodshed</span>';
  h += '</div>';
  h += '<div id="ddReturnsSnapshotCard"></div>';
  h += '<div id="stockCommentaryCard"></div>';
  h += '<div id="ddDemandCurveCard"></div>';
  h += '<div id="ddOwnershipCard"></div>';
  h += '<div id="ddVolumeProfileCard"></div>';
  h += '<div id="ddWoodshedCard"></div>';
  h += '</section>';

  // ── SECTION DD-IV: EXTERNAL VIEW ──
  h += '<section class="csdd-section" data-csdd-section="DD-IV">';
  h += '<div class="csdd-section__head">';
  h += '<span class="csdd-section__roman">DD · IV</span>';
  h += '<span class="csdd-section__title">External View</span>';
  h += '<span class="csdd-section__sub">Wall Street consensus &amp; recent rating actions</span>';
  h += '</div>';
  h += '<div id="ddAnalystCoverageCard"></div>';
  h += '</section>';

  h += '</div>'; // .csdd-root
  return h;
};

window._fireEmbeddedDDLoaders = function(symbol, sector, region) {
  if (!symbol) return;
  var sym = String(symbol).toUpperCase();
  region = region || window._deRegion || 'US';
  // Stash for downstream helpers
  window._ddLastSymbol = sym;
  window._ddLastSector = sector || '';

  // Fire each card's loader if available — each handles its own errors
  try {
    if (typeof window._loadPositioningIntel === 'function') {
      window._loadPositioningIntel(sym, sector || '', region);
    }
  } catch(e) { console.warn('PositioningIntel load failed:', e); }

  try {
    if (typeof window._loadStockCommentary === 'function') {
      window._loadStockCommentary(sym, region, 'stockCommentaryCard');
    }
  } catch(e) { console.warn('Commentary load failed:', e); }

  try {
    if (typeof window._loadDDForwardView === 'function') {
      window._loadDDForwardView(sym, region);
    }
  } catch(e) { console.warn('ForwardView load failed:', e); }

  try {
    if (typeof window._loadWoodshedSignal === 'function') {
      window._loadWoodshedSignal(sym, region);
    }
  } catch(e) { console.warn('Woodshed load failed:', e); }

  try {
    if (typeof window._loadAnalystCoverageTicker === 'function') {
      window._loadAnalystCoverageTicker(sym, region);
    }
  } catch(e) { console.warn('AnalystCoverage load failed:', e); }

  // r63.75.0: Returns Snapshot — multi-timeframe momentum thought-check
  try {
    if (typeof window._loadReturnsSnapshot === 'function') {
      window._loadReturnsSnapshot(sym, region);
    }
  } catch(e) { console.warn('ReturnsSnapshot load failed:', e); }
};

// ═════════════════════════════════════════════════════════════════════════
// r63.74.0: Embed FULL Deep DD (all 6 sections incl. Section VI Full Institutional Detail)
// into investor view via /api/investor-due-diligence. Replaces the slim
// _buildEmbeddedDDSections embed (which only gave DD-I through DD-IV).
//
// Relies on window._renderDeepDDLegacyInto which is exposed by loadDeepDD.
// loadDeepDD is called once at app init (lines 3556, 3629) so the helper is
// available by the time investor mode renders.
// ═════════════════════════════════════════════════════════════════════════
window._embedDeepDDIntoInvestor = function(symbol, region, targetEl) {
  if (!symbol || !targetEl) return;
  var sym = String(symbol).toUpperCase();
  region = region || window._deRegion || 'US';

  // r63.75.0: Self-bootstrap — if the legacy renderer wasn\'t exposed at app init (loadDeepDD
  // was never invoked), call it now. After r63.74.0's refactor, loadDeepDD's closure setup
  // and helper exposure run BEFORE the early-return guards, so this triggers exposure
  // without any DOM side effects.
  if (typeof window._renderDeepDDLegacyInto !== 'function') {
    try {
      if (typeof loadDeepDD === 'function') {
        loadDeepDD();  // hits the closure setup + helper exposure, then returns early (no DOM writes)
      }
    } catch (e) {
      console.warn('[DD-EMBED] loadDeepDD bootstrap failed:', e);
    }
  }

  // Loading state
  targetEl.innerHTML = '' +
    '<div style="margin:24px 0 14px;padding:14px 18px;background:linear-gradient(135deg,#1A3A78,#2563eb);color:#fff;border-radius:12px;font-family:Sora,sans-serif">' +
      '<div style="font-size:10px;letter-spacing:1px;font-weight:800;opacity:0.85">DEEP DUE DILIGENCE</div>' +
      '<div style="font-size:15px;font-weight:900;margin-top:2px">📌 Full institutional report — loading…</div>' +
      '<div style="font-size:10px;margin-top:4px;opacity:0.85">Fetching multi-factor analysis, Porter, SWOT, Risk Matrix, Catalysts, Ownership, Earnings…</div>' +
    '</div>' +
    '<div style="padding:30px;text-align:center;color:#94a3b8;font-size:11px;font-family:Inter,sans-serif">' +
      '<div style="display:inline-block;width:18px;height:18px;border:2.5px solid #1A3A78;border-top-color:transparent;border-radius:50%;animation:spin .5s linear infinite;vertical-align:middle"></div>' +
      '<span style="margin-left:10px">Running Deep DD on <strong>' + sym + '</strong>…</span>' +
    '</div>';

  var _eml = document.getElementById('email');
  var emailParam = window._verifiedEmail || (_eml ? (_eml.dataset.real || _eml.value || '') : '').trim().toLowerCase();

  fetch('/api/investor-due-diligence?symbol=' + encodeURIComponent(sym) + '&region=' + encodeURIComponent(region) + '&email=' + encodeURIComponent(emailParam))
    .then(function(r) { return r.json(); })
    .then(function(d) {
      if (!d || !d.success) {
        var msg = (d && d.error) || 'Unknown error';
        targetEl.innerHTML = '<div style="margin:24px 0;padding:14px;background:#fef2f2;border:1px solid #fecaca;border-radius:8px;font-size:11px;color:#7f1d1d;font-family:Inter,sans-serif">⚠ Full Deep DD unavailable for ' + sym + ': ' + msg + '</div>';
        return;
      }
      window._ddLastSymbol = sym;
      window._ddLastSector = (d.company && d.company.sector) || '';

      if (typeof window._renderDeepDDLegacyInto !== 'function') {
        targetEl.innerHTML = '<div style="margin:24px 0;padding:14px;background:#fef9c3;border:1px solid #fde68a;border-radius:8px;font-size:11px;color:#78350f;font-family:Inter,sans-serif">⚠ Deep DD render helper not initialized — please refresh the page.</div>';
        return;
      }

      // Render full Deep DD (Sections I–VI) into the target container
      window._renderDeepDDLegacyInto(d, targetEl);

      // Fire all DD card loaders — same set _ddGenerate would fire
      setTimeout(function() {
        try {
          if (typeof window._loadPositioningIntel === 'function') {
            window._loadPositioningIntel(sym, window._ddLastSector, region);
          }
          if (typeof window._loadStockCommentary === 'function') {
            window._loadStockCommentary(sym, region, 'stockCommentaryCard');
          }
          if (typeof window._loadDDForwardView === 'function') {
            window._loadDDForwardView(sym, region);
          }
          if (typeof window._loadWoodshedSignal === 'function') {
            window._loadWoodshedSignal(sym, region);
          }
          if (typeof window._loadAnalystCoverageTicker === 'function') {
            window._loadAnalystCoverageTicker(sym, region);
          }
          // r63.75.0: Returns Snapshot — multi-timeframe thought-check
          if (typeof window._loadReturnsSnapshot === 'function') {
            window._loadReturnsSnapshot(sym, region);
          }
        } catch (e) { console.warn('Embedded full-DD loaders failed:', e); }
      }, 120);
    })
    .catch(function(e) {
      targetEl.innerHTML = '<div style="margin:24px 0;padding:14px;background:#fef2f2;border:1px solid #fecaca;border-radius:8px;font-size:11px;color:#7f1d1d;font-family:Inter,sans-serif">⚠ Full Deep DD network error: ' + (e.message || e) + '</div>';
    });
};

// ═════════════════════════════════════════════════════════════════════════
// r63.76.0: Premium Intelligence Group — 5 institutional sections
//   1. Fiscal Period Ending — Analysts Expect (consensus by FY)
//   2. Estimate Revisions Heatmap (7d / 30d / 60d / 90d trend)
//   3. Earnings Surprise History (8Q beat/miss + price reaction)
//   4. Forward Multiples Stack (Fwd PE / PEG / EV-EBITDA / P-S / P-FCF vs 5Y median)
//   5. Dividend Quality Score (skipped for non-payers)
//
// Defensive field access — tries multiple common path variants per field.
// Missing fields render as red ⚠ NEEDS_BACKEND tags so api.py side knows
// what to expose. Wire one field at a time and the red tags disappear.
// ═════════════════════════════════════════════════════════════════════════

// Helper: deep-pick with fallback paths (returns first non-empty value)
window._piPick = function(obj, paths, fallback) {
  if (!obj) return fallback;
  for (var i = 0; i < paths.length; i++) {
    var parts = paths[i].split('.');
    var v = obj;
    for (var j = 0; j < parts.length; j++) {
      if (v == null) { v = undefined; break; }
      v = v[parts[j]];
    }
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return fallback;
};

// r63.79.0: Gap tracker — accumulates missing field paths so we can show ONE
// collapsed "Developer notes" footer at the bottom of Premium Intelligence
// instead of dozens of loud red boxes scattered through the user view.
window._piGapTracker = window._piGapTracker || {};
window._piResetGapTracker = function() { window._piGapTracker = {}; };

// Helper: subtle gray dash placeholder for missing fields (was: loud red box)
// Tooltip shows the field path so dev can hover to see what's missing.
window._piGap = function(fieldName, note) {
  window._piGapTracker[fieldName] = (window._piGapTracker[fieldName] || 0) + 1;
  return '<span style="color:#cbd5e1;font-family:JetBrains Mono,monospace;font-size:11px" title="' + fieldName + (note ? ' (' + note + ')' : '') + ' — not yet returned by /api/investor-decide">—</span>';
};

// Helper: signed % with color
window._piPct = function(value, fieldName, decimals) {
  if (value === undefined || value === null || value === '') return window._piGap(fieldName);
  var n = parseFloat(value);
  if (isNaN(n)) return window._piGap(fieldName, 'NaN');
  var c = n > 0 ? '#059669' : n < 0 ? '#dc2626' : '#64748b';
  var sign = n > 0 ? '+' : '';
  return '<span style="color:' + c + ';font-weight:800">' + sign + n.toFixed(decimals != null ? decimals : 1) + '%</span>';
};

// Helper: format currency with B/M/T suffix
window._piCcy = function(value, fieldName, S) {
  S = S || '$';
  if (value === undefined || value === null || value === '') return window._piGap(fieldName);
  var n = parseFloat(value);
  if (isNaN(n)) return window._piGap(fieldName, 'NaN');
  if (Math.abs(n) >= 1e12) return S + (n/1e12).toFixed(2) + 'T';
  if (Math.abs(n) >= 1e9) return S + (n/1e9).toFixed(2) + 'B';
  if (Math.abs(n) >= 1e6) return S + (n/1e6).toFixed(2) + 'M';
  return S + n.toLocaleString('en-US', {maximumFractionDigits: 2});
};

