// ═══════════════════ MOMENTUM CoC ENGINE ═══════════════════
// Phase 1: Readiness Score + CoC Journal (localStorage). Phase 2 scaffolded.
// Ensure a global HTML-escaper for the engines added below (Momentum CoC +
// Market 360). The codebase convention is a local `var E = window._esc`; this
// shim guarantees bare E resolves even if a function omits the local decl.
if (typeof window.E !== 'function') {
  window.E = window._esc || function(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); };
}
window._mcocTab = 'score';
window._mcocLast = null;
window._MCOC_LS = 'celesys_mcoc_journal_v1';
window._MCOC_MIN_SIGNALS = 30;        // gate for Control/DNA/EMP
window._MCOC_HORIZONS = [['w1','+1w',7],['w2','+2w',14],['m1','+1m',30],['m3','+3m',90],['m6','+6m',180]];

window._mcocJournal = function(){ try { return JSON.parse(localStorage.getItem(window._MCOC_LS)||'[]'); } catch(e){ return []; } };
window._mcocSaveJournal = function(j){ try { localStorage.setItem(window._MCOC_LS, JSON.stringify(j)); } catch(e){} };

// ── Durable store (Neon) layer — localStorage stays the always-on local cache ──
window._mcocStore = { mode:'local', configured:false, checked:false, user_key:'default' };
window._mcocUserKey = function(){ try { return window._celesysUserKey || window._mcocStore.user_key || 'default'; } catch(e){ return 'default'; } };
window._mcocCheckStore = function(cb){
  fetch('/api/momentum-coc/journal/status',{cache:'no-store'})
    .then(function(r){return r.json();})
    .then(function(s){ window._mcocStore.mode=s.available?'neon':'local'; window._mcocStore.configured=!!s.configured; window._mcocStore.checked=true; if(cb)cb(); })
    .catch(function(){ window._mcocStore.mode='local'; window._mcocStore.checked=true; if(cb)cb(); });
};
window._mcocMerge = function(remote){
  var byId={}; window._mcocJournal().forEach(function(e){ if(e&&e.id) byId[e.id]=e; });
  (remote||[]).forEach(function(e){ if(e&&e.id) byId[e.id]=e; });   // Neon wins on conflict
  var arr=Object.keys(byId).map(function(k){return byId[k];});
  arr.sort(function(a,b){return String(b.date||'').localeCompare(String(a.date||''));});
  window._mcocSaveJournal(arr); return arr;
};
window._mcocPullNeon = function(cb){
  if(window._mcocStore.mode!=='neon'){ if(cb)cb(); return; }
  fetch('/api/momentum-coc/journal?user_key='+encodeURIComponent(window._mcocUserKey()),{cache:'no-store'})
    .then(function(r){return r.json();})
    .then(function(d){ if(d.available&&Array.isArray(d.entries)) window._mcocMerge(d.entries); if(cb)cb(); })
    .catch(function(){ if(cb)cb(); });
};
window._mcocPushEntry = function(entry){
  if(window._mcocStore.mode!=='neon'||!entry) return;
  fetch('/api/momentum-coc/journal',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({entry:entry,user_key:window._mcocUserKey()})}).catch(function(){});
};
window._mcocDelNeon = function(id){
  if(window._mcocStore.mode!=='neon') return;
  fetch('/api/momentum-coc/journal?id='+encodeURIComponent(id)+'&user_key='+encodeURIComponent(window._mcocUserKey()),{method:'DELETE'}).catch(function(){});
};
window._mcocSyncNeon = function(){
  window._mcocCheckStore(function(){
    if(window._mcocStore.mode!=='neon'){ alert('Neon not connected.\n\nSet DATABASE_URL (your Neon connection string) in Render \u2192 Environment, redeploy, then click Sync again.'); window._mcocShowTab('journal'); return; }
    var btn=document.getElementById('mcocSyncBtn'); if(btn){btn.disabled=true;btn.innerHTML='\u23F3 Syncing\u2026';}
    fetch('/api/momentum-coc/journal/sync',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({entries:window._mcocJournal(),user_key:window._mcocUserKey()})})
      .then(function(r){return r.json();})
      .then(function(d){ if(d.available&&Array.isArray(d.entries)) window._mcocMerge(d.entries); window._mcocShowTab('journal'); })
      .catch(function(){ window._mcocShowTab('journal'); });
  });
};

window._mcocShowTab = function(tab){
  window._mcocTab = tab;
  var inp = document.getElementById('mcocScoreInput');
  if (inp) inp.style.display = (tab==='score') ? 'flex' : 'none';
  [['score','mcocTabScore'],['journal','mcocTabJournal'],['lab','mcocTabLab'],['top','mcocTabTop']].forEach(function(p){
    var b=document.getElementById(p[1]); if(!b) return;
    if(p[0]===tab){ b.style.background='linear-gradient(135deg,#ea580c,#c2410c)'; b.style.color='#fff'; b.style.border='none'; }
    else { b.style.background='#fff'; b.style.color='#c2410c'; b.style.border='1px solid #fed7aa'; }
  });
  var r=document.getElementById('mcocResult');
  if(!r) return;
  if(tab==='journal'){ r.innerHTML = window._renderMcocJournal(); if(!window._mcocStore.checked){ window._mcocCheckStore(function(){ window._mcocPullNeon(function(){ var rr=document.getElementById('mcocResult'); if(rr&&window._mcocTab==='journal') rr.innerHTML=window._renderMcocJournal(); }); }); } else if(window._mcocStore.mode==='neon'){ window._mcocPullNeon(function(){ var rr=document.getElementById('mcocResult'); if(rr&&window._mcocTab==='journal') rr.innerHTML=window._renderMcocJournal(); }); } }
  else if(tab==='lab') r.innerHTML = window._renderMcocLab();
  else if(tab==='top') r.innerHTML = window._mcocTopLast ? window._renderMcocTop(window._mcocTopLast)
      : '<div style="text-align:center;padding:30px"><div style="font-size:11px;color:#64748b;margin-bottom:12px">Scan the universe and rank every name by Momentum Readiness \u2014 the setups closest to a multibagger breakout.</div><button onclick="window._mcocLoadTop()" style="padding:8px 20px;background:linear-gradient(135deg,#ea580c,#c2410c);color:#fff;border:none;border-radius:6px;font-size:12px;font-weight:800;cursor:pointer;font-family:Sora,sans-serif">\uD83C\uDFC6 SCAN TOP READINESS</button></div>';
  else r.innerHTML = window._mcocLast ? window._renderMcocScore(window._mcocLast) : '<div style="text-align:center;padding:24px;color:#94a3b8;font-size:11px">Enter a symbol, click SCORE READINESS.</div>';
};

window._mcocScore = function(){
  if(window._mcocLoading) return;
  var sym=((document.getElementById('mcocSym')||{}).value||'').trim().toUpperCase();
  var reg=(window._engState.mcoc&&window._engState.mcoc.region)||'US';
  if(!sym){ document.getElementById('mcocResult').innerHTML='<div style="padding:12px;color:#dc2626;font-size:11px">Enter a symbol first.</div>'; return; }
  window._mcocLoading=true;
  var btn=document.getElementById('mcocBtn'), r=document.getElementById('mcocResult');
  if(btn){btn.disabled=true;btn.style.opacity='0.6';btn.style.pointerEvents='none';btn.innerHTML='\u23F3 SCORING\u2026';}
  var _done=function(){window._mcocLoading=false; if(btn){btn.disabled=false;btn.style.opacity='1';btn.style.pointerEvents='auto';btn.innerHTML='\uD83E\uDDEC SCORE READINESS';}};
  if(r) r.innerHTML='<div style="text-align:center;padding:24px;color:#94a3b8;font-size:11px"><span style="display:inline-block;width:14px;height:14px;border:2px solid #fed7aa;border-top-color:transparent;border-radius:50%;animation:spin .6s linear infinite;vertical-align:-2px;margin-right:7px"></span>Computing 10-factor readiness for '+window._esc(sym)+'\u2026</div>';
  var ac=(typeof AbortController!=='undefined')?new AbortController():null;
  var to=setTimeout(function(){if(ac)ac.abort();},45000);
  fetch('/api/momentum-coc/score?symbol='+encodeURIComponent(sym)+'&region='+encodeURIComponent(reg),{cache:'no-store',signal:ac?ac.signal:undefined})
    .then(function(x){return x.json();})
    .then(function(d){
      clearTimeout(to); _done();
      if(!d||!d.success){ if(r) r.innerHTML='<div style="padding:12px;color:#dc2626;font-size:11px">'+window._esc((d&&d.error)||'Failed')+'</div>'; return; }
      window._mcocLast=d; if(r) r.innerHTML=window._renderMcocScore(d);
    })
    .catch(function(e){
      clearTimeout(to); _done();
      var msg=(e&&e.name==='AbortError')?'Feed slow/blocked on this host \u2014 try again.':('Network error: '+window._esc(String(e)));
      if(r) r.innerHTML='<div style="padding:12px;color:#dc2626;font-size:11px">'+msg+'</div>';
    });
};

window._mcocStagePipeline = function(s, region){
  var E=window._esc;
  var pipe=s.pipeline||[];
  var h='<div style="background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:11px 14px;margin-bottom:10px">';
  h+='<div style="font-size:10px;font-weight:800;color:#475569;margin-bottom:9px">\uD83D\uDD2C STAGE PIPELINE \u2014 where this stock is in its lifecycle</div>';
  h+='<div style="display:flex;align-items:flex-start;gap:0;overflow-x:auto;padding-bottom:4px">';
  pipe.forEach(function(name,i){
    var cur=(i===s.index), done=(i<s.index), sweet=(s.sweet_idx && i>=s.sweet_idx[0] && i<=s.sweet_idx[1]);
    var bg=cur?'#7c3aed':done?'#ede9fe':'#f8fafc', fg=cur?'#fff':done?'#7c3aed':'#94a3b8', bd=cur?'#7c3aed':sweet?'#a78bfa':'#e2e8f0';
    h+='<div style="flex:1;min-width:60px;text-align:center"><div style="background:'+bg+';color:'+fg+';border:1.5px solid '+bd+';border-radius:7px;padding:5px 3px;font-size:8px;font-weight:800;line-height:1.15;font-family:Sora,sans-serif">'+(cur?'\u25C9 ':done?'\u2713 ':'')+E(name)+'</div>'+(sweet?'<div style="font-size:6.5px;color:#a78bfa;font-weight:700;margin-top:1px">sweet spot</div>':'<div style="height:11px"></div>')+'</div>';
    if(i<pipe.length-1) h+='<div style="display:flex;align-items:center;color:#cbd5e1;font-size:10px;padding:6px 1px 0">\u2192</div>';
  });
  h+='</div>';
  h+='<div style="font-size:10px;color:#475569;margin-top:6px"><b style="color:#7c3aed">Current:</b> '+E(s.current)+' \u00b7 <b>Next expected:</b> '+E(s.next)+' \u00b7 <b>Sweet spot:</b> '+E(s.sweet_spot)+'</div>';
  if(s.rs_before_price) h+='<div style="margin-top:7px;background:#dcfce7;border:1px solid #86efac;border-radius:7px;padding:6px 9px;font-size:9.5px;color:#15803d"><b>\u26A1 RS line at a NEW HIGH before price</b> \u2014 the classic early-leader tell (O\u2019Neil/Minervini): relative strength is leading while price is still under the pivot.</div>';
  else if(s.rs_new_high) h+='<div style="margin-top:7px;background:#ecfeff;border:1px solid #a5f3fc;border-radius:7px;padding:6px 9px;font-size:9.5px;color:#0e7490"><b>RS line at new highs.</b> Leadership confirmed'+(s.rs_rising?' and rising':'')+'.</div>';
  else if(s.rs_line!=null) h+='<div style="margin-top:7px;font-size:9px;color:#64748b">RS line (vs benchmark): '+s.rs_line+(s.rs_rising?' \u00b7 rising':' \u00b7 flat/falling')+'.</div>';
  else h+='<div style="margin-top:7px;font-size:9px;color:#94a3b8">RS line: benchmark series unavailable on this run.</div>';
  h+='<div style="margin-top:9px;display:flex;align-items:center;gap:8px"><span style="font-size:8px;font-weight:800;color:#64748b">STAGE QUALITY</span><div style="flex:1;height:7px;background:#e2e8f0;border-radius:4px;overflow:hidden"><div style="height:100%;width:'+s.quality+'%;background:#7c3aed"></div></div><span style="font-size:12px;font-weight:900;color:#7c3aed;font-family:JetBrains Mono,monospace">'+s.quality+'</span></div>';
  h+='<div style="display:flex;flex-wrap:wrap;gap:5px;margin-top:6px">';
  (s.components||[]).forEach(function(cp){ var na=(cp.value==null); h+='<div style="font-size:8px;color:'+(na?'#94a3b8':'#475569')+';background:'+(na?'#f8fafc':'#f1f5f9')+';border-radius:5px;padding:2px 6px">'+E(cp.name)+' <b>'+(na?'N/A':cp.value)+'</b><span style="color:#cbd5e1"> /'+cp.weight+'</span></div>'; });
  h+='</div>';
  h+='<div style="font-size:7.5px;color:#94a3b8;margin-top:6px">Stage is a best-effort read from price/volume structure. Institutional Sponsorship needs an ownership feed (N/A here); Earnings acceleration is a separate, unavailable factor.</div>';
  h+='</div>';
  return h;
};

window._mcocFramework = function(fw, sym, region){
  var E=window._esc, cur=(region==='IN')?'\u20B9':'$';
  var sc={WATCHLIST:['#64748b','#f1f5f9'],ACCUMULATION:['#2563eb','#eff6ff'],ACTIONABLE:['#16a34a','#dcfce7'],EXTENDED:['#dc2626','#fef2f2']}[fw.status]||['#64748b','#f1f5f9'];
  var h='';
  h+='<div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:10px">';
  h+='<span style="font-size:9px;font-weight:800;padding:4px 12px;border-radius:12px;background:'+sc[1]+';color:'+sc[0]+'">STATUS: '+E(fw.status)+'</span>';
  h+='<div style="flex:1;min-width:150px"><div style="font-size:8px;color:#94a3b8;font-weight:700">INSTITUTIONAL CONFIDENCE</div><div style="display:flex;align-items:center;gap:6px"><div style="flex:1;height:7px;background:#e2e8f0;border-radius:4px;overflow:hidden"><div style="height:100%;width:'+fw.confidence+'%;background:'+sc[0]+'"></div></div><span style="font-size:12px;font-weight:900;color:'+sc[0]+';font-family:JetBrains Mono,monospace">'+fw.confidence+'%</span></div></div>';
  h+='</div>';
  function zone(name,priceTxt,prob,risk,conds,star,accent,bg){
    var c='<div style="background:'+bg+';border:1px solid '+accent+'33;'+(star?'border-left:3px solid '+accent+';':'')+'border-radius:9px;padding:9px 11px;margin-bottom:7px">';
    c+='<div style="display:flex;justify-content:space-between;align-items:baseline;flex-wrap:wrap;gap:6px"><span style="font-size:11px;font-weight:900;color:'+accent+';font-family:Sora,sans-serif">'+(star?'\u2B50 ':'')+name+'</span><span style="font-size:13px;font-weight:900;color:#0f172a;font-family:JetBrains Mono,monospace">'+priceTxt+'</span></div>';
    c+='<div style="font-size:8.5px;color:#64748b;margin:3px 0 5px">Probability: <b>'+prob+'</b> \u00b7 Risk: <b>'+risk+'</b></div>';
    conds.forEach(function(cd){ var mk=cd.met===true?'\u2713':cd.met===false?'\u2717':'\u25CB'; var mc=cd.met===true?'#16a34a':cd.met===false?'#dc2626':'#94a3b8'; c+='<div style="font-size:9.5px;color:'+mc+'"><b>'+mk+'</b> <span style="color:#475569">'+E(cd.label)+'</span></div>'; });
    c+='</div>'; return c;
  }
  var Z=fw.zones;
  h+=zone('AGGRESSIVE',cur+Z.aggressive.lo+'\u2013'+cur+Z.aggressive.hi,Z.aggressive.prob,Z.aggressive.risk,Z.aggressive.conds,false,'#d97706','#fffbeb');
  h+=zone('OPTIMAL (preferred)',cur+Z.optimal.price,Z.optimal.prob,Z.optimal.risk,Z.optimal.conds,true,'#16a34a','#f0fdf4');
  h+=zone('CONFIRMATION',cur+Z.confirmation.price,Z.confirmation.prob,Z.confirmation.risk,Z.confirmation.conds,false,'#2563eb','#eff6ff');
  h+='<div style="display:flex;gap:8px;flex-wrap:wrap;margin:8px 0">';
  [['INVALIDATION',cur+fw.invalidation,'#dc2626'],['RISK / REWARD',(fw.risk_reward!=null?fw.risk_reward+' : 1':'n/a'),'#16a34a'],['TARGET (measured)',cur+fw.target,'#475569']].forEach(function(x){
    h+='<div style="flex:1;min-width:92px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:7px;padding:6px 8px"><div style="font-size:8px;color:#94a3b8;font-weight:700">'+x[0]+'</div><div style="font-size:13px;font-weight:900;color:'+x[2]+';font-family:JetBrains Mono,monospace">'+E(String(x[1]))+'</div></div>';
  });
  h+='</div>';
  h+='<div style="display:flex;gap:10px;flex-wrap:wrap">';
  h+='<div style="flex:1;min-width:150px"><div style="font-size:8px;font-weight:800;color:#16a34a;margin-bottom:3px">REASONS</div>'+((fw.reasons||[]).length?fw.reasons.map(function(r){return '<div style="font-size:9.5px;color:#15803d;line-height:1.5">\u2713 '+E(r)+'</div>';}).join(''):'<div style="font-size:9px;color:#cbd5e1">\u2014</div>')+'</div>';
  h+='<div style="flex:1;min-width:150px"><div style="font-size:8px;font-weight:800;color:#dc2626;margin-bottom:3px">CONCERNS</div>'+((fw.concerns||[]).length?fw.concerns.map(function(r){return '<div style="font-size:9.5px;color:#b91c1c;line-height:1.5">\u2717 '+E(r)+'</div>';}).join(''):'<div style="font-size:9px;color:#cbd5e1">\u2014</div>')+'</div>';
  h+='</div>';
  h+='<div style="margin-top:9px;background:'+sc[1]+';border:1px solid '+sc[0]+'55;border-radius:8px;padding:9px 12px"><span style="font-size:8px;font-weight:800;color:'+sc[0]+';letter-spacing:1px">VERDICT</span><div style="font-size:14px;font-weight:900;color:'+sc[0]+';font-family:Sora,sans-serif;margin-top:2px">'+E(fw.verdict)+'</div></div>';
  return h;
};

window._renderMcocScore = function(d){
  var sc=d.score;
  var cls=d.classification||'';
  var col = sc==null?'#94a3b8':sc>=90?'#16a34a':sc>=80?'#0ea5e9':sc>=70?'#d97706':'#dc2626';
  var bg  = sc==null?'#f8fafc':sc>=90?'#f0fdf4':sc>=80?'#eff6ff':sc>=70?'#fffbeb':'#fef2f2';
  var h='';
  h+='<div style="background:'+bg+';border:1px solid '+col+'40;border-radius:14px;padding:16px 18px;margin-bottom:12px">';
  h+='<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap">';
  h+='<div><div style="font-size:9px;font-weight:800;color:#94a3b8;letter-spacing:1px">'+window._esc(d.symbol)+' \u00B7 '+window._esc(d.region)+' \u00B7 READINESS</div>';
  h+='<div style="font-size:13px;font-weight:900;color:'+col+';font-family:Sora,sans-serif;margin-top:2px">'+window._esc(cls)+'</div></div>';
  h+='<div style="text-align:right"><div style="font-size:34px;font-weight:900;color:'+col+';font-family:JetBrains Mono,monospace;line-height:1">'+(sc==null?'\u2014':sc)+'</div><div style="font-size:8px;color:#94a3b8;font-weight:700">/ 100</div></div>';
  h+='</div>';
  h+='<div style="position:relative;height:7px;border-radius:5px;background:#e2e8f0;margin-top:10px"><div style="position:absolute;left:0;top:0;height:7px;border-radius:5px;width:'+(sc||0)+'%;background:'+col+'"></div>';
  ['70','80','90'].forEach(function(t){ h+='<div style="position:absolute;top:-2px;left:'+t+'%;width:1px;height:11px;background:#94a3b8"></div>'; });
  h+='</div>';
  h+='<div style="font-size:8px;color:#94a3b8;margin-top:3px;display:flex;justify-content:space-between"><span>Ignore</span><span>70 Watch</span><span>80 Inst.</span><span>90 Elite</span></div>';
  h+='</div>';

  // dimension bars
  h+='<div style="background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:12px 14px;margin-bottom:10px">';
  h+='<div style="font-size:10px;font-weight:800;color:#475569;margin-bottom:8px">10-FACTOR BREAKDOWN <span style="color:#94a3b8;font-weight:600">(weight shown; N/A excluded from score)</span></div>';
  (d.dimensions||[]).forEach(function(dim){
    var avail=dim.available; var ss=dim.subscore;
    var dc = !avail?'#cbd5e1':ss>=70?'#16a34a':ss>=45?'#d97706':'#dc2626';
    h+='<div style="margin-bottom:7px">';
    h+='<div style="display:flex;justify-content:space-between;font-size:10px;margin-bottom:2px"><span style="font-weight:700;color:#334155">'+window._esc(dim.label)+' <span style="color:#94a3b8;font-weight:600">w'+dim.weight+'</span></span><span style="font-weight:800;color:'+dc+'">'+(avail?ss:'N/A')+'</span></div>';
    h+='<div style="height:6px;border-radius:4px;background:#f1f5f9;overflow:hidden"><div style="height:6px;width:'+(avail?ss:0)+'%;background:'+dc+'"></div></div>';
    h+='<div style="font-size:8.5px;color:#94a3b8;margin-top:1px">'+window._esc(dim.note||'')+'</div>';
    h+='</div>';
  });
  h+='</div>';

  if (d.entry_plan) {
    var ep = d.entry_plan;
    var zc = (ep.current_zone==='Pivot / Retest')?'#16a34a':(ep.current_zone==='Cheat Entry')?'#2563eb':(ep.current_zone==='Chase Zone')?'#d97706':(ep.current_zone==='Avoid Zone')?'#dc2626':'#64748b';
    var zbg = (ep.current_zone==='Pivot / Retest')?'#f0fdf4':(ep.current_zone==='Cheat Entry')?'#eff6ff':(ep.current_zone==='Chase Zone')?'#fffbeb':(ep.current_zone==='Avoid Zone')?'#fef2f2':'#f8fafc';
    h += '<div style="background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:12px 14px;margin-bottom:10px">';
    h += '<div style="font-size:10px;font-weight:800;color:#475569;margin-bottom:8px">\uD83D\uDCD0 INSTITUTIONAL ENTRY FRAMEWORK</div>';
    // Plain-English headline
    var sym = window._esc(d.symbol||'This stock');
    var _pv = ep.pivot;
    var _beLo = ep.pivot;
    var _beHi = (ep.pivot!=null)?Math.round(ep.pivot*1.01*100)/100:null;
    var _maxPay = (ep.pivot!=null)?Math.round(ep.pivot*1.05*100)/100:null;
    var _needRise = (ep.pivot!=null&&ep.current)?Math.round((ep.pivot/ep.current-1)*1000)/10:null;
    if (ep.stage) { h += window._mcocStagePipeline(ep.stage, d.region); }
    if (ep.framework) { h += window._mcocFramework(ep.framework, (d.symbol||''), d.region); } else {
    var ph;
    if (ep.current_zone==='Below base') ph='\uD83D\uDD34 <b>No buy yet.</b> '+sym+' is '+Math.abs(ep.pct_from_pivot)+'% below the buy trigger of '+_pv+'. It must rise ~'+_needRise+'% and build a base first \u2014 then break out on strong volume.';
    else if (ep.current_zone==='Cheat Entry') ph='\uD83D\uDFE1 <b>Early \u2014 not yet confirmed.</b> Price is just under the buy trigger ('+_pv+'). Only aggressive traders buy here, and only if volume is drying up.';
    else if (ep.current_zone==='Pivot / Retest') ph='\uD83D\uDFE2 <b>Buy window NOW.</b> Price is at the buy trigger ('+_pv+').'+(ep.rvol_confirmed?' Volume confirms (RVOL '+ep.rvol+'\u00d7) \u2014 this is the entry.':' But volume is light (RVOL '+ep.rvol+'\u00d7) \u2014 wait for a close above '+_pv+' on heavy volume.');
    else if (ep.current_zone==='Chase Zone') ph='\uD83D\uDFE0 <b>Extended.</b> Price is +'+ep.pct_from_pivot+'% past the trigger \u2014 beyond the ideal entry. Buy small, or wait for a pullback toward '+_pv+'.';
    else ph='\uD83D\uDD34 <b>Too extended (+'+ep.pct_from_pivot+'%).</b> Don\u2019t chase \u2014 wait for a pullback/retest down to '+_pv+'.';
    h += '<div style="font-size:12px;color:#0f172a;background:'+zbg+';border:1px solid '+zc+'40;border-radius:8px;padding:9px 11px;line-height:1.5;margin-bottom:10px">'+ph+'</div>';
    // Three clear prices
    h += '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px">';
    [['BUY TRIGGER', _pv, 'first close above this', '#16a34a'],
     ['BEST ENTRY', _beLo+'\u2013'+_beHi, 'ideal zone, on volume', '#16a34a'],
     ['DON\u2019T PAY ABOVE', _maxPay, 'too extended past here', '#dc2626']].forEach(function(x){
      h+='<div style="flex:1;min-width:104px;background:#fff;border:1px solid '+x[3]+'33;border-left:3px solid '+x[3]+';border-radius:8px;padding:7px 9px"><div style="font-size:8px;color:#94a3b8;font-weight:800;letter-spacing:0.3px">'+x[0]+'</div><div style="font-size:15px;font-weight:900;color:'+x[3]+';font-family:JetBrains Mono,monospace">'+window._esc(String(x[1]))+'</div><div style="font-size:8px;color:#94a3b8">'+x[2]+'</div></div>';
    });
    h += '</div>';
    // Secondary facts
    h += '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:9px">';
    [['CURRENT',ep.current+' ('+(ep.pct_from_pivot>0?'+':'')+ep.pct_from_pivot+'%)'],['RVOL (volume)',ep.rvol+'\u00d7'+(ep.rvol_confirmed?' \u2713 confirms':' \u2014 light')],['STOP / RISK',ep.stop_ref]].forEach(function(x){
      h+='<div style="flex:1;min-width:84px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:7px;padding:5px 8px"><div style="font-size:8px;color:#94a3b8;font-weight:700">'+x[0]+'</div><div style="font-size:12px;font-weight:800;color:#475569;font-family:JetBrains Mono,monospace">'+window._esc(String(x[1]))+'</div></div>';
    });
    h += '</div>';
    // Tier table with plain meanings
    var _tm={'Cheat Entry':'early \u2014 before the breakout (riskier)','Pivot Breakout':'the breakout itself (pro entry)','Breakout Retest':'after a pullback to the breakout (best win-rate)','Chase Zone':'1\u20135% above \u2014 reduce size','Avoid Zone':'too extended \u2014 don\u2019t chase'};
    h += '<div style="font-size:9px;font-weight:800;color:#475569;margin-bottom:4px">ENTRY TYPES (price ranges for '+sym+')</div>';
    h += '<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:10px"><tr style="background:#f8fafc;color:#475569"><th style="padding:4px 6px;text-align:left">Entry Type</th><th style="padding:4px 6px;text-align:right">Price range</th><th style="padding:4px 6px;text-align:right">Win odds</th><th style="padding:4px 6px;text-align:right">Reward</th></tr>';
    ep.tiers.forEach(function(t){
      var hot=(ep.current_zone.indexOf(t.name)>=0)||(ep.current_zone==='Pivot / Retest'&&(t.name==='Pivot Breakout'||t.name==='Breakout Retest'));
      h+='<tr style="border-bottom:1px solid #f1f5f9;'+(hot?'background:'+zbg+';':'')+'">';
      h+='<td style="padding:4px 6px;color:#1e293b"><span style="font-weight:'+(hot?'900':'700')+'">'+(hot?'\u25B6 ':'')+window._esc(t.name)+'</span><div style="font-size:8px;color:#94a3b8;font-weight:600">'+window._esc(_tm[t.name]||'')+'</div></td>';
      h+='<td style="padding:4px 6px;text-align:right;font-family:JetBrains Mono,monospace;color:#475569">'+t.lo+(t.hi?('\u2013'+t.hi):'+')+'</td>';
      h+='<td style="padding:4px 6px;text-align:right;color:#16a34a;font-weight:700">'+window._esc(t.prob)+'</td>';
      h+='<td style="padding:4px 6px;text-align:right;color:#64748b">'+t.reward+'</td>';
      h+='</tr>';
    });
    h += '</table></div>';
    }
    h += '<div style="font-size:10px;color:#0f172a;background:#f0fdf4;border:1px solid #bbf7d0;border-radius:8px;padding:7px 10px;margin-top:8px"><b>\uD83C\uDFAF The one rule (if you buy just once):</b> '+window._esc(ep.best_price)+'</div>';
    h += '<div style="font-size:9px;font-weight:800;color:#475569;margin:9px 0 5px">360\u00B0 REQUIREMENTS</div><div style="display:flex;flex-wrap:wrap;gap:5px">';
    ep.requirements.forEach(function(r){
      var mk = r.ok===true?'\u2713':r.ok===false?'\u2717':'\u00b7'; var rcol=r.ok===true?'#16a34a':r.ok===false?'#dc2626':'#94a3b8';
      h+='<span style="font-size:9px;color:'+rcol+';border:1px solid '+rcol+'33;border-radius:5px;padding:2px 7px"><b>'+mk+'</b> '+window._esc(r.label)+' <span style="color:#94a3b8">('+window._esc(r.note)+')</span></span>';
    });
    h += '</div>';
    h += '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px">';
    ep.staged_plan.forEach(function(s){ h+='<div style="flex:1;min-width:100px;background:#faf5ff;border:1px solid #e9d5ff;border-radius:7px;padding:6px 8px"><div style="font-size:14px;font-weight:900;color:#7c3aed;font-family:JetBrains Mono,monospace">'+s.pct+'%</div><div style="font-size:9px;font-weight:700;color:#1e293b">'+window._esc(s.leg)+'</div><div style="font-size:8px;color:#94a3b8;line-height:1.3">'+window._esc(s.trigger)+'</div></div>'; });
    h += '</div>';
    h += '<div style="font-size:9px;color:'+(ep.requirements_met>=4?'#16a34a':'#b45309')+';font-weight:700;margin-top:7px">'+window._esc(ep.size_guidance)+' \u00b7 '+ep.requirements_met+'/'+ep.requirements_checkable+' requirements met</div>';
    h += '<div style="font-size:8px;color:#94a3b8;margin-top:4px">Entry levels are derived from the pivot (max high of the prior base) + live price/volume. Risk framing, not advice; size and stops are your decision.</div>';
    h += '</div>';
  }

  if((d.excluded||[]).length) h+='<div style="font-size:9px;color:#b45309;background:#fffbeb;border:1px solid #fde68a;border-radius:8px;padding:7px 10px;margin-bottom:8px">\u26A0 Excluded (N/A): '+window._esc(d.excluded.join(', '))+' \u2014 score renormalized over available factors.</div>';
  h+='<div style="font-size:8.5px;color:#94a3b8;margin-bottom:10px">Weights: '+window._esc(d.weights_basis||'')+'. '+window._esc(d.data_note||'')+'</div>';

  // Log to journal
  h+='<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center">';
  h+='<button onclick="window._mcocLog()" style="padding:7px 16px;background:linear-gradient(135deg,#ea580c,#c2410c);color:#fff;border:none;border-radius:6px;font-size:11px;font-weight:800;cursor:pointer;font-family:Sora,sans-serif">\uD83D\uDCD3 Log to CoC Journal</button>';
  h+='<span style="font-size:9px;color:#94a3b8">Logs this call as a tracked experiment (entry '+ (d.entry_ref_price!=null?('$'+d.entry_ref_price):'\u2014') +') to build your evidence base.</span>';
  h+='</div>';
  return h;
};

window._mcocLog = function(){
  var d=window._mcocLast; if(!d) return;
  var j=window._mcocJournal();
  if(j.some(function(e){return e.symbol===d.symbol && e.date.slice(0,10)===new Date().toISOString().slice(0,10);})){
    alert('Already logged '+d.symbol+' today.'); return;
  }
  var _ne={ id:Date.now()+'_'+d.symbol, symbol:d.symbol, region:d.region, date:new Date().toISOString(),
    score:d.score, classification:d.classification, regime:(d.vix_regime||''),
    entryPrice:d.entry_ref_price, benchSymbol:d.bench_symbol, benchPrice:d.bench_ref_price,
    pivot:(d.entry_plan&&d.entry_plan.pivot)||null, entryZone:(d.entry_plan&&d.entry_plan.current_zone)||null,
    sector:null, outcomes:{} };
  j.unshift(_ne);
  window._mcocSaveJournal(j);
  window._mcocPushEntry(_ne);
  window._mcocShowTab('journal');
};

window._renderMcocJournal = function(){
  var E=window._esc;
  var j=window._mcocJournal();
  var HZ=window._MCOC_HORIZONS||[];
  // storage pill
  var sm=window._mcocStore||{mode:'local'};
  var pill, pbg, pcol;
  if(sm.mode==='neon'){ pill='\u2601 Synced to Neon'; pbg='#ecfdf5'; pcol='#047857'; }
  else if(sm.configured){ pill='\u26A0 Neon set \u2014 reconnecting, using local'; pbg='#fffbeb'; pcol='#b45309'; }
  else { pill='\uD83D\uDCBE Local only (this browser)'; pbg='#f1f5f9'; pcol='#64748b'; }

  var h='<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:10px">';
  h+='<span style="font-size:9px;font-weight:800;padding:4px 10px;border-radius:12px;background:'+pbg+';color:'+pcol+'">'+pill+'</span>';
  h+='<button id="mcocSyncBtn" onclick="window._mcocSyncNeon()" style="padding:6px 12px;background:#0ea5e9;color:#fff;border:none;border-radius:6px;font-size:10px;font-weight:800;cursor:pointer;font-family:Sora,sans-serif">\u2601 Sync to Neon</button>';
  h+='<button onclick="window._mcocRefreshOutcomes()" id="mcocRefreshBtn" style="padding:6px 12px;background:#fff7ed;color:#c2410c;border:1px solid #fed7aa;border-radius:6px;font-size:10px;font-weight:800;cursor:pointer;font-family:Sora,sans-serif">\u21BB Update Outcomes</button>';
  h+='<button onclick="window._mcocExport()" style="padding:6px 10px;background:#fff;color:#475569;border:1px solid #cbd5e1;border-radius:6px;font-size:10px;font-weight:700;cursor:pointer">\u2B07 Export</button>';
  h+='<label style="padding:6px 10px;background:#fff;color:#475569;border:1px solid #cbd5e1;border-radius:6px;font-size:10px;font-weight:700;cursor:pointer">\u2B06 Import<input type="file" accept="application/json" onchange="window._mcocImport(event)" style="display:none"></label>';
  h+='</div>';

  if(!j.length) return h+'<div style="text-align:center;padding:24px;color:#94a3b8;font-size:11px">No logged signals yet. Score a name, then \u201CLog to CoC Journal\u201D. Each log becomes a tracked experiment.</div>';

  // summary
  var withOut=j.filter(function(e){return Object.keys(e.outcomes||{}).length;});
  var avg=Math.round(j.reduce(function(a,e){return a+(e.score||0);},0)/j.length);
  function lastOutcome(e){ var ks=Object.keys(e.outcomes||{}); return ks.length?e.outcomes[ks[ks.length-1]]:null; }
  var lasts=withOut.map(lastOutcome).filter(Boolean);
  var hits=lasts.filter(function(o){return o.rel>0;}).length;
  var avgAlpha=lasts.length?+(lasts.reduce(function(a,o){return a+(o.rel||0);},0)/lasts.length).toFixed(1):null;
  var best=lasts.length?Math.max.apply(null,lasts.map(function(o){return o.rel||0;})):null;
  function stat(lbl,val,sub,col){ return '<div style="flex:1;min-width:84px;background:#fff;border:1px solid #e2e8f0;border-radius:8px;padding:8px 10px"><div style="font-size:8px;color:#94a3b8;font-weight:700">'+lbl+'</div><div style="font-size:17px;font-weight:900;color:'+(col||'#1e293b')+';font-family:JetBrains Mono,monospace">'+val+'</div>'+(sub?'<div style="font-size:7px;color:#cbd5e1">'+sub+'</div>':'')+'</div>'; }
  h+='<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px">';
  h+=stat('LOGGED', j.length);
  h+=stat('AVG READINESS', avg);
  h+=stat('REL. HIT-RATE', lasts.length?Math.round(hits/lasts.length*100)+'%':'\u2014','n='+lasts.length);
  h+=stat('AVG ALPHA', avgAlpha==null?'\u2014':(avgAlpha>0?'+':'')+avgAlpha+'%', 'vs bench', avgAlpha==null?'#1e293b':avgAlpha>0?'#16a34a':'#dc2626');
  h+=stat('BEST', best==null?'\u2014':(best>0?'+':'')+best.toFixed(1)+'%', null, best==null?'#1e293b':best>0?'#16a34a':'#dc2626');
  h+='</div>';

  // entry cards
  j.forEach(function(e){
    var cur=(e.region==='IN')?'\u20B9':'$';
    var scol=e.score>=80?'#16a34a':e.score>=70?'#d97706':'#dc2626';
    var sbg=e.score>=80?'#dcfce7':e.score>=70?'#fef3c7':'#fee2e2';
    var nOut=Object.keys(e.outcomes||{}).length;
    h+='<div style="background:#fff;border:1px solid #e2e8f0;border-left:3px solid '+scol+';border-radius:10px;padding:10px 12px;margin-bottom:8px">';
    // header line
    h+='<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">';
    h+='<span style="font-size:13px;font-weight:900;color:#1e293b;font-family:JetBrains Mono,monospace">'+E(e.symbol)+'</span>';
    h+='<span style="font-size:8px;font-weight:800;padding:2px 7px;border-radius:10px;background:'+sbg+';color:'+scol+'">'+(e.score==null?'\u2014':e.score)+' \u00B7 '+E(e.classification||'')+'</span>';
    if(e.entryZone) h+='<span style="font-size:8px;color:#7c3aed;background:#f5f3ff;border-radius:8px;padding:2px 7px">'+E(e.entryZone)+'</span>';
    h+='<span style="font-size:9px;color:#94a3b8;margin-left:auto">'+E(String(e.date||'').slice(0,10))+'</span>';
    h+='<span onclick="window._mcocDel(\''+E(e.id)+'\')" style="cursor:pointer;color:#cbd5e1;font-weight:900;font-size:13px" title="Delete">\u00D7</span>';
    h+='</div>';
    // meta line
    h+='<div style="display:flex;gap:12px;flex-wrap:wrap;margin-top:5px;font-size:9px;color:#64748b">';
    if(e.entryPrice!=null) h+='<span>Entry <b style="color:#334155;font-family:JetBrains Mono,monospace">'+cur+Number(e.entryPrice).toLocaleString(undefined,{maximumFractionDigits:2})+'</b></span>';
    if(e.pivot!=null) h+='<span>Pivot <b style="color:#334155;font-family:JetBrains Mono,monospace">'+cur+Number(e.pivot).toLocaleString(undefined,{maximumFractionDigits:2})+'</b></span>';
    if(e.benchSymbol) h+='<span>vs <b style="color:#334155">'+E(e.benchSymbol)+'</b></span>';
    if(e.regime) h+='<span>Regime <b style="color:#334155">'+E(e.regime)+'</b></span>';
    h+='<span style="margin-left:auto;color:'+(nOut?'#16a34a':'#cbd5e1')+';font-weight:700">'+nOut+'/'+HZ.length+' horizons elapsed</span>';
    h+='</div>';
    // horizon strip
    h+='<div style="display:flex;gap:5px;flex-wrap:wrap;margin-top:8px">';
    HZ.forEach(function(hz){
      var o=(e.outcomes||{})[hz[0]];
      if(o){
        var rc=o.rel>0?'#16a34a':'#dc2626'; var rbg=o.rel>0?'#f0fdf4':'#fef2f2';
        h+='<div style="flex:1;min-width:58px;background:'+rbg+';border:1px solid '+rc+'22;border-radius:7px;padding:5px 6px;text-align:center">';
        h+='<div style="font-size:7px;color:#94a3b8;font-weight:700">'+E(hz[1])+'</div>';
        h+='<div style="font-size:12px;font-weight:900;color:'+rc+';font-family:JetBrains Mono,monospace">'+(o.rel>0?'+':'')+o.rel.toFixed(1)+'%</div>';
        if(o.stock!=null) h+='<div style="font-size:7px;color:#94a3b8">abs '+(o.stock>0?'+':'')+o.stock.toFixed(1)+'%</div>';
        h+='</div>';
      } else {
        h+='<div style="flex:1;min-width:58px;background:#f8fafc;border:1px dashed #e2e8f0;border-radius:7px;padding:5px 6px;text-align:center"><div style="font-size:7px;color:#cbd5e1;font-weight:700">'+E(hz[1])+'</div><div style="font-size:12px;color:#cbd5e1;font-family:JetBrains Mono,monospace">\u2014</div><div style="font-size:7px;color:#e2e8f0">pending</div></div>';
      }
    });
    h+='</div>';
    h+='</div>';
  });

  h+='<div style="font-size:8px;color:#94a3b8;margin-top:8px;line-height:1.5">Each card is a tracked experiment. The big number is <b>relative</b> return (stock \u2212 benchmark); <b>abs</b> is the raw move. Outcomes are captured the first time you hit <b>Update Outcomes</b> after a horizon elapses, so timing is approximate to your refresh cadence. Alpha vs benchmark \u2014 not absolute \u2014 is the honest scorecard. With Neon connected, this journal persists across devices.</div>';
  return h;
};

window._mcocDel = function(id){ var j=window._mcocJournal().filter(function(e){return e.id!==id;}); window._mcocSaveJournal(j); window._mcocDelNeon(id); window._mcocShowTab('journal'); };

window._mcocRefreshOutcomes = function(){
  var j=window._mcocJournal();
  var pending=j.filter(function(e){ return e.entryPrice && e.benchPrice; });
  if(!pending.length){ return; }
  var btn=document.getElementById('mcocRefreshBtn'); if(btn){btn.disabled=true;btn.innerHTML='\u23F3 Updating\u2026';}
  var done=0;
  pending.forEach(function(e){
    fetch('/api/momentum-coc/quote?symbol='+encodeURIComponent(e.symbol)+'&region='+encodeURIComponent(e.region),{cache:'no-store'})
      .then(function(x){return x.json();})
      .then(function(q){
        if(q&&q.success&&q.price&&q.bench_price){
          var days=(Date.now()-new Date(e.date).getTime())/86400000;
          var sret=(q.price/e.entryPrice-1)*100;
          var bret=(q.bench_price/e.benchPrice-1)*100;
          var rel=sret-bret;
          e.outcomes=e.outcomes||{};
          window._MCOC_HORIZONS.forEach(function(hz){
            if(days>=hz[2] && !e.outcomes[hz[0]]) e.outcomes[hz[0]]={stock:+sret.toFixed(2),bench:+bret.toFixed(2),rel:+rel.toFixed(2),atDay:Math.round(days)};
          });
        }
      })
      .catch(function(){})
      .finally(function(){ done++; if(done===pending.length){ window._mcocSaveJournal(j); if(window._mcocStore.mode==='neon'){ j.forEach(function(e){window._mcocPushEntry(e);}); } window._mcocShowTab('journal'); } });
  });
};

window._mcocExport = function(){
  var blob=new Blob([JSON.stringify(window._mcocJournal(),null,2)],{type:'application/json'});
  var a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download='celesys_coc_journal_'+new Date().toISOString().slice(0,10)+'.json'; a.click();
};
window._mcocImport = function(ev){
  var f=ev.target.files&&ev.target.files[0]; if(!f) return;
  var rd=new FileReader();
  rd.onload=function(){ try{ var arr=JSON.parse(rd.result); if(Array.isArray(arr)){ window._mcocSaveJournal(arr); window._mcocShowTab('journal'); } }catch(e){ alert('Invalid JSON'); } };
  rd.readAsText(f);
};

window._renderMcocLab = function(){
  var withOut=window._mcocJournal().filter(function(e){return Object.keys(e.outcomes||{}).length;}).length;
  var E=window._esc;
  var h='<div style="font-size:10px;color:#64748b;line-height:1.5;margin-bottom:10px;background:#fff7ed;border:1px solid #fed7aa;border-radius:8px;padding:9px 11px">\uD83D\uDD2C <b>Phase 2 Lab</b> \u2014 the learning loop, now live. Each engine is computed <i>honestly</i>: no survivorship bias, no look-ahead leakage, sample sizes and confidence bands shown. Small universe + free feeds mean results are <b>directional, not gospel</b>.</div>';

  // Control Group
  h+='<div style="background:#fff;border:1px solid #e2e8f0;border-left:3px solid #16a34a;border-radius:10px;padding:12px 14px;margin-bottom:8px">';
  h+='<div style="font-size:11px;font-weight:900;color:#1e293b;font-family:Sora,sans-serif">\uD83E\uDDEA Control Group Engine</div>';
  h+='<div style="font-size:10px;color:#64748b;line-height:1.5;margin:5px 0 8px">For each logged pick, compares its return to same-sector peers over the <b>identical window</b> \u2014 isolating your alpha from a rising tide. Needs journal entries with elapsed outcomes (run <b>Update Outcomes</b> in the Journal first).</div>';
  h+='<button onclick="window._mcocRunControl()" style="padding:6px 14px;background:#16a34a;color:#fff;border:none;border-radius:6px;font-size:10px;font-weight:800;cursor:pointer;font-family:Sora,sans-serif">\uD83E\uDDEA RUN CONTROL GROUP</button>';
  h+='<span style="font-size:9px;color:#94a3b8;margin-left:8px">'+withOut+' logged signal(s) with outcomes</span>';
  h+='<div id="mcocControlOut" style="margin-top:10px"></div></div>';

  // DNA
  h+='<div style="background:#fff;border:1px solid #e2e8f0;border-left:3px solid #7c3aed;border-radius:10px;padding:12px 14px;margin-bottom:8px">';
  h+='<div style="font-size:11px;font-weight:900;color:#1e293b;font-family:Sora,sans-serif">\uD83E\uDDEC Multibagger DNA Engine</div>';
  h+='<div style="font-size:10px;color:#64748b;line-height:1.5;margin:5px 0 8px">Look-ahead-clean study over the whole universe: factors measured <b>before</b> each anchor date, forward return measured <b>after</b>. Each factor\u2019s win-rate is shown <b>with its sample size and Wilson CI</b>, vs the base rate. Price/volume factors only (fundamentals leak from free feeds).</div>';
  h+='<button onclick="window._mcocLoadDNA()" id="mcocDnaBtn" style="padding:6px 14px;background:#7c3aed;color:#fff;border:none;border-radius:6px;font-size:10px;font-weight:800;cursor:pointer;font-family:Sora,sans-serif">\uD83E\uDDEC RUN DNA + EMP STUDY</button>';
  h+='<span style="font-size:9px;color:#94a3b8;margin-left:8px">~multi-year scan, heavy first run (cached 24h)</span>';
  h+='<div id="mcocDnaOut" style="margin-top:10px">'+(window._mcocDnaLast?window._renderDnaFactors(window._mcocDnaLast):'')+'</div></div>';

  // EMP
  h+='<div style="background:#fff;border:1px solid #e2e8f0;border-left:3px solid #ea580c;border-radius:10px;padding:12px 14px;margin-bottom:8px">';
  h+='<div style="font-size:11px;font-weight:900;color:#1e293b;font-family:Sora,sans-serif">\uD83C\uDFAF Expected Multibagger Probability (EMP)</div>';
  h+='<div style="font-size:10px;color:#64748b;line-height:1.5;margin:5px 0 8px">From the same study: by readiness-score bucket, the realized P(+20%), P(+50%), P(+100%) over the forward window \u2014 <b>each with a confidence band + sample count</b>, never a bare number. Runs together with the DNA study above.</div>';
  h+='<div id="mcocEmpOut">'+(window._mcocDnaLast?window._renderEmp(window._mcocDnaLast):'<div style="font-size:9px;color:#94a3b8">Run the DNA study to populate EMP.</div>')+'</div></div>';
  return h;
};

window._mcocLoadDNA = function(){
  if(window._mcocDnaLoading) return;
  window._mcocDnaLoading=true;
  var reg=(window._engState.mcoc&&window._engState.mcoc.region)||'US';
  var btn=document.getElementById('mcocDnaBtn'); var out=document.getElementById('mcocDnaOut'); var emp=document.getElementById('mcocEmpOut');
  if(btn){btn.disabled=true;btn.style.opacity='0.6';btn.innerHTML='\u23F3 RUNNING\u2026';}
  if(out) out.innerHTML='<div style="font-size:10px;color:#94a3b8;padding:8px"><span style="display:inline-block;width:12px;height:12px;border:2px solid #ddd6fe;border-top-color:transparent;border-radius:50%;animation:spin .6s linear infinite;vertical-align:-2px;margin-right:6px"></span>Scanning multi-year history & scoring anchors\u2026 (up to ~2 min first run)</div>';
  var ac=(typeof AbortController!=='undefined')?new AbortController():null; var to=setTimeout(function(){if(ac)ac.abort();},150000);
  fetch('/api/momentum-coc/dna?region='+encodeURIComponent(reg),{cache:'no-store',signal:ac?ac.signal:undefined})
    .then(function(x){return x.json();})
    .then(function(d){
      clearTimeout(to); window._mcocDnaLoading=false;
      if(btn){btn.disabled=false;btn.style.opacity='1';btn.innerHTML='\uD83E\uDDEC RUN DNA + EMP STUDY';}
      if(!d||!d.success){ if(out) out.innerHTML='<div style="font-size:10px;color:#dc2626">'+window._esc((d&&d.error)||'failed')+'</div>'; return; }
      window._mcocDnaLast=d;
      if(out) out.innerHTML=window._renderDnaFactors(d);
      if(emp) emp.innerHTML=window._renderEmp(d);
    })
    .catch(function(e){
      clearTimeout(to); window._mcocDnaLoading=false;
      if(btn){btn.disabled=false;btn.style.opacity='1';btn.innerHTML='\uD83E\uDDEC RUN DNA + EMP STUDY';}
      var msg=(e&&e.name==='AbortError')?'Scan slow/blocked on this host \u2014 historical feed likely unreachable.':('Network error: '+window._esc(String(e)));
      if(out) out.innerHTML='<div style="font-size:10px;color:#dc2626">'+msg+'</div>';
    });
};

window._renderDnaFactors = function(d){
  var E=window._esc;
  if(!d.sufficient) return '<div style="font-size:10px;color:#b45309;background:#fffbeb;border:1px solid #fde68a;border-radius:8px;padding:9px 11px">\u26A0 '+E(d.note||'Insufficient data.')+' <span style="color:#94a3b8">(obs='+(d.observations||0)+', names='+(d.names_scored||0)+'/'+(d.universe_size||0)+')</span></div>';
  var b=d.base_rates||{};
  var h='<div style="font-size:9px;color:#475569;margin-bottom:6px"><b>'+d.observations+'</b> look-ahead-clean observations from <b>'+d.names_scored+'</b> names over a '+d.horizon_months+'-mo forward window. Base rates: '
    +['20','50','100'].map(function(t){var x=b[t]||{};return 'P(+'+t+'%)='+Math.round((x.rate||0)*100)+'%';}).join(' \u00b7 ')+'</div>';
  h+='<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:10px">';
  h+='<tr style="background:#f5f3ff;color:#5b21b6"><th style="padding:5px 6px;text-align:left">Factor</th><th style="padding:5px 6px;text-align:right">n</th><th style="padding:5px 6px;text-align:right">Win% (+50%/6mo)</th><th style="padding:5px 6px;text-align:right">95% CI</th><th style="padding:5px 6px;text-align:right">Lift vs base</th></tr>';
  (d.factors||[]).forEach(function(f){
    if(f.insufficient){ h+='<tr style="border-bottom:1px solid #f1f5f9;color:#cbd5e1"><td style="padding:5px 6px">'+E(f.label)+'</td><td style="padding:5px 6px;text-align:right">'+f.n+'</td><td colspan="3" style="padding:5px 6px;text-align:right">insufficient (n&lt;5)</td></tr>'; return; }
    var lift=f.lift_vs_base; var lc=lift>0.03?'#16a34a':lift<-0.03?'#dc2626':'#64748b';
    h+='<tr style="border-bottom:1px solid #f1f5f9">';
    h+='<td style="padding:5px 6px;font-weight:700;color:#334155">'+E(f.label)+'</td>';
    h+='<td style="padding:5px 6px;text-align:right;color:#64748b">'+f.n+'</td>';
    h+='<td style="padding:5px 6px;text-align:right;font-weight:800;color:#1e293b">'+Math.round(f.win_rate_50*100)+'%</td>';
    h+='<td style="padding:5px 6px;text-align:right;color:#94a3b8">'+Math.round(f.lo*100)+'\u2013'+Math.round(f.hi*100)+'%</td>';
    h+='<td style="padding:5px 6px;text-align:right;font-weight:800;color:'+lc+'">'+(lift>0?'+':'')+Math.round(lift*100)+'pp</td>';
    h+='</tr>';
  });
  h+='</table></div>';
  h+='<div style="font-size:8px;color:#94a3b8;margin-top:6px;line-height:1.4">'+E(d.note||'')+'</div>';
  return h;
};

window._renderEmp = function(d){
  var E=window._esc;
  if(!d.sufficient) return '<div style="font-size:9px;color:#b45309">\u26A0 Not enough observations for calibrated EMP yet.</div>';
  var h='<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:10px">';
  h+='<tr style="background:#fff7ed;color:#7c2d12"><th style="padding:5px 6px;text-align:left">Readiness bucket</th><th style="padding:5px 6px;text-align:right">n</th><th style="padding:5px 6px;text-align:right">P(+20%)</th><th style="padding:5px 6px;text-align:right">P(+50%)</th><th style="padding:5px 6px;text-align:right">P(+100%)</th></tr>';
  (d.emp||[]).forEach(function(r){
    h+='<tr style="border-bottom:1px solid #f1f5f9">';
    h+='<td style="padding:5px 6px;font-weight:800;color:#1e293b">'+E(r.bucket)+'</td>';
    h+='<td style="padding:5px 6px;text-align:right;color:#64748b">'+r.n+'</td>';
    if(r.sufficient){
      ['p20','p50','p100'].forEach(function(k){
        var x=r[k]||{}; h+='<td style="padding:5px 6px;text-align:right"><span style="font-weight:800;color:#1e293b">'+Math.round((x.rate||0)*100)+'%</span><br><span style="font-size:8px;color:#94a3b8">'+Math.round((x.lo||0)*100)+'\u2013'+Math.round((x.hi||0)*100)+'%</span></td>';
      });
    } else { h+='<td colspan="3" style="padding:5px 6px;text-align:right;color:#cbd5e1">n&lt;5</td>'; }
    h+='</tr>';
  });
  h+='</table></div>';
  h+='<div style="font-size:8px;color:#94a3b8;margin-top:6px;line-height:1.4">Each cell: realized rate with 95% Wilson band. Wide bands = small sample = read directionally. Not a price prediction, not advice.</div>';
  return h;
};

window._mcocRunControl = function(){
  if(window._mcocCtrlLoading) return;
  var entries=window._mcocJournal().filter(function(e){return e.outcomes && Object.keys(e.outcomes).length && e.region;});
  var out=document.getElementById('mcocControlOut');
  if(!entries.length){ if(out) out.innerHTML='<div style="font-size:10px;color:#b45309;background:#fffbeb;border:1px solid #fde68a;border-radius:8px;padding:8px 10px">\u26A0 No logged signals with elapsed outcomes yet. Log a few in the Readiness tab, then run <b>Update Outcomes</b> in the Journal once time has passed.</div>'; return; }
  window._mcocCtrlLoading=true;
  if(out) out.innerHTML='<div style="font-size:10px;color:#94a3b8;padding:6px"><span style="display:inline-block;width:12px;height:12px;border:2px solid #bbf7d0;border-top-color:transparent;border-radius:50%;animation:spin .6s linear infinite;vertical-align:-2px;margin-right:6px"></span>Comparing each pick to its sector peers\u2026</div>';
  var rows=[]; var pending=entries.length;
  entries.forEach(function(e){
    var ks=Object.keys(e.outcomes); var last=e.outcomes[ks[ks.length-1]]; var days=(last&&last.atDay)||30;
    fetch('/api/momentum-coc/control?symbol='+encodeURIComponent(e.symbol)+'&region='+encodeURIComponent(e.region)+'&days='+days,{cache:'no-store'})
      .then(function(x){return x.json();})
      .then(function(c){
        rows.push({symbol:e.symbol, stock:(last?last.stock:null), control:(c.success?c.control_avg_pct:null),
                   sector:(c.success?c.sector:null), n:(c.success?c.n:0),
                   alpha:(c.success&&last?+(last.stock-c.control_avg_pct).toFixed(2):null)});
      })
      .catch(function(){ rows.push({symbol:e.symbol, stock:(last?last.stock:null), control:null, alpha:null}); })
      .finally(function(){ if(--pending===0){ window._mcocCtrlLoading=false; if(out) out.innerHTML=window._renderControl(rows); } });
  });
};

window._renderControl = function(rows){
  var E=window._esc;
  var valid=rows.filter(function(r){return r.alpha!=null;});
  var h='';
  if(valid.length){
    var avgAlpha=+(valid.reduce(function(a,r){return a+r.alpha;},0)/valid.length).toFixed(2);
    var beat=valid.filter(function(r){return r.alpha>0;}).length;
    h+='<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px">';
    h+='<div style="flex:1;min-width:90px;background:#f0fdf4;border:1px solid #bbf7d0;border-radius:8px;padding:7px 9px"><div style="font-size:8px;color:#15803d;font-weight:700">AVG ALPHA vs SECTOR</div><div style="font-size:16px;font-weight:900;color:'+(avgAlpha>0?'#16a34a':'#dc2626')+';font-family:JetBrains Mono,monospace">'+(avgAlpha>0?'+':'')+avgAlpha+'pp</div></div>';
    h+='<div style="flex:1;min-width:90px;background:#fff;border:1px solid #e2e8f0;border-radius:8px;padding:7px 9px"><div style="font-size:8px;color:#94a3b8;font-weight:700">BEAT CONTROL</div><div style="font-size:16px;font-weight:900;color:#1e293b;font-family:JetBrains Mono,monospace">'+beat+'/'+valid.length+'</div></div>';
    h+='</div>';
  }
  h+='<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:10px">';
  h+='<tr style="background:#f0fdf4;color:#15803d"><th style="padding:5px 6px;text-align:left">Pick</th><th style="padding:5px 6px;text-align:left">Sector</th><th style="padding:5px 6px;text-align:right">Pick ret</th><th style="padding:5px 6px;text-align:right">Peer avg</th><th style="padding:5px 6px;text-align:right">Alpha</th></tr>';
  rows.forEach(function(r){
    h+='<tr style="border-bottom:1px solid #f1f5f9">';
    h+='<td style="padding:5px 6px;font-weight:800;color:#1e293b;font-family:JetBrains Mono,monospace">'+E(r.symbol)+'</td>';
    h+='<td style="padding:5px 6px;color:#94a3b8;font-size:9px">'+E(r.sector||'\u2014')+'</td>';
    h+='<td style="padding:5px 6px;text-align:right;color:#64748b">'+(r.stock!=null?(r.stock>0?'+':'')+r.stock+'%':'\u2014')+'</td>';
    h+='<td style="padding:5px 6px;text-align:right;color:#64748b">'+(r.control!=null?(r.control>0?'+':'')+r.control+'%':'\u2014')+'</td>';
    var ac=r.alpha==null?'#cbd5e1':r.alpha>0?'#16a34a':'#dc2626';
    h+='<td style="padding:5px 6px;text-align:right;font-weight:800;color:'+ac+'">'+(r.alpha!=null?(r.alpha>0?'+':'')+r.alpha+'pp':'n/a')+'</td>';
    h+='</tr>';
  });
  h+='</table></div>';
  h+='<div style="font-size:8px;color:#94a3b8;margin-top:6px;line-height:1.4">Alpha = pick return \u2212 same-sector peer average over the same window. Positive = genuine edge vs a rising tide. Small n \u21d2 directional. Not advice.</div>';
  return h;
};

