window._lastDirection=null;window._soundEnabled=true;
function _playAlertSound(type){
if(!window._soundEnabled)return;
try{
var ctx=new(window.AudioContext||window.webkitAudioContext)();
var osc=ctx.createOscillator();var gain=ctx.createGain();
osc.connect(gain);gain.connect(ctx.destination);
gain.gain.setValueAtTime(0.15,ctx.currentTime);
gain.gain.exponentialRampToValueAtTime(0.001,ctx.currentTime+0.6);
if(type==='bullish'){osc.frequency.setValueAtTime(523,ctx.currentTime);osc.frequency.setValueAtTime(659,ctx.currentTime+0.15);osc.frequency.setValueAtTime(784,ctx.currentTime+0.3);}
else if(type==='bearish'){osc.frequency.setValueAtTime(784,ctx.currentTime);osc.frequency.setValueAtTime(659,ctx.currentTime+0.15);osc.frequency.setValueAtTime(523,ctx.currentTime+0.3);}
else{osc.frequency.setValueAtTime(440,ctx.currentTime);}
osc.start(ctx.currentTime);osc.stop(ctx.currentTime+0.6);
}catch(e){}
}
