h+='<div style="display:flex;justify-content:space-between;align-items:center;padding:10px 14px;border-radius:10px;background:#ef444406;border:1px solid #ef444410;margin-bottom:4px">';
h+='<div style="flex:1"><div style="font-size:12px;font-weight:900;color:var(--text);font-family:Sora,sans-serif">'+l.symbol+' <span style="font-size:9px;color:var(--text3);font-weight:500">'+l.name+'</span></div>';
