      h += '<strong>'+c.symbol+' rank vs peers (incl self):</strong> ';
      var rl = [];
      if(comp.company_rank.revenue_growth_pct) rl.push('Growth: <strong>'+comp.company_rank.revenue_growth_pct+'</strong>');
