h+='<table style="width:100%;border-collapse:collapse;font-size:9px">';
var _v3R=[{s:'RSI',v:Math.round(_rsi2),c:_rsi2>60?'#10b981':_rsi2<40?'#ef4444':'#f59e0b'},{s:'Trend',v:_trend2+'/4',c:_trend2>=3?'#10b981':_trend2<=1?'#ef4444':'#f59e0b'},{s:'Fwd PE',v:_fwdPE.toFixed(1)+'x',c:_fwdPE>0&&_fwdPE<20?'#10b981':_fwdPE>35?'#ef4444':'#f59e0b'},{s:'Signals',v:_totalBull+'B/'+_totalBear+'R',c:_totalBull>_totalBear?'#10b981':'#ef4444'},{s:'Week',v:_wD,c:_wC2},{s:'Month',v:_mD,c:_mC2}];
_v3R.forEach(function(r){h+='<tr style="border-bottom:1px solid var(--border)"><td style="padding:4px 8px;font-weight:700;color:var(--text)">'+r.s+'</td><td style="padding:4px;text-align:center;font-weight:900;color:'+r.c+';font-family:var(--mono)">'+r.v+'</td></tr>';});
h+='</table></div>';

// ═══ FINAL VERDICT ═══
var _totalAll=_totalBull+_totalBear;var _fPct=_totalAll>0?Math.round(_totalBull/_totalAll*100):50;
var _fvC2=_fPct>=55?'#10b981':_fPct>=45?'#f59e0b':'#ef4444';
