// ═══ UNIVERSAL SMART PARSER — works with ANY format ═══
function _smartExtract(text){
// UNIVERSAL PARSER — handles ALL broker formats:
// Sharekhan, Zerodha, Groww, Angel One, ICICI Direct, HDFC Sec, Kotak, Upstox
// Supports: NSE tickers, BSE codes, ISIN, company names, trading symbols
var _blacklist={'NAME':1,'STOCK':1,'SYMBOL':1,'TICKER':1,'QUANTITY':1,'QTY':1,'PRICE':1,'VALUE':1,'MARKET':1,'TOTAL':1,'HOLDING':1,'COST':1,'GAIN':1,'LOSS':1,'REALIZED':1,'UNREALIZED':1,'PERCENT':1,'AVERAGE':1,'AVG':1,'CURRENT':1,'CMP':1,'BUY':1,'SELL':1,'DATE':1,'CUSTOMER':1,'LOGIN':1,'EQUITY':1,'TRADE':1,'FOLDER':1,'SKSCRIPCODE':1,'LTD':1,'LIMITED':1,'INDUSTRIES':1,'TECHNOLOGIES':1,'SERVICES':1,'COMPANY':1,'CORPORATION':1,'ENTERPRISES':1,'SR':1,'NO':1,'ID':1,'TRADING':1,'INSTRUMENT':1,'EXCHANGE':1,'SEGMENT':1,'SERIES':1,'ISIN':1,'DEMAT':1,'DP':1,'CLIENT':1,'FOLIO':1,'SCHEME':1,'NAV':1,'UNITS':1,'ACCOUNT':1,'BROKER':1,'SETTLEMENT':1,'ORDER':1,'EXECUTED':1,'PENDING':1,'CANCELLED':1,'REJECTED':1,'NSE':1,'BSE':1,'MCX':1,'NFO':1,'CDS':1};
// ISIN to NSE ticker mapping (top 200 Indian stocks)
var _isinMap={'INE002A01018':'RELIANCE','INE467B01029':'TCS','INE009A01021':'INFY','INE040A01034':'HDFCBANK','INE154A01025':'ITC','INE030A01027':'HINDUNILVR','INE062A01020':'SBIN','INE090A01021':'ICICIBANK','INE585B01010':'MARUTI','INE397D01024':'BHARTIARTL','INE018A01030':'HCLTECH','INE669E01016':'ADANIENT','INE774D01024':'BAJFINANCE','INE101A01026':'WIPRO','INE752E01010':'POWERGRID','INE176A01028':'AXISBANK','INE669C01036':'ASIANPAINT','INE028A01039':'BAJAJ-AUTO','INE121A01024':'M&M','INE123W01016':'ADANIPORTS','INE042A01014':'NTPC','INE075A01022':'CIPLA','INE092T01019':'NESTLEIND','INE848E01016':'TECHM','INE117A01022':'APOLLOHOSP','INE749A01030':'DRREDDY','INE019A01038':'JSWSTEEL','INE047A01021':'BPCL','INE160A01022':'DIVISLAB','INE628A01036':'UPL','INE095A01012':'HEROMOTOCO','INE029A01011':'BEL','INE216A01030':'ULTRACEMCO','INE155A01022':'TATAPOWER','INE081A01012':'BAJAJFINSV','INE726G01019':'TITAN','INE021A01026':'COALINDIA','INE040H01021':'PIDILITIND','INE364U01010':'POLYCAB'};
// BSE code to NSE ticker (top stocks)
var _bseMap={'500325':'RELIANCE','532540':'TCS','500209':'INFY','500180':'HDFCBANK','500875':'ITC','500696':'HINDUNILVR','500112':'SBIN','532174':'ICICIBANK','532500':'MARUTI','532454':'BHARTIARTL'};
var found=[];
var seen={};
// Split into individual tokens
var cells=text.replace(/"/g,'').split(/[,\t;|\n\r]+/).map(function(c){return c.trim()}).filter(function(c){return c.length>=2&&c.length<=30});

cells.forEach(function(cell){
var up=cell.toUpperCase().replace(/\.NS|\.BO|\.NSE|\.BSE/gi,'').trim();
// Skip blacklisted words
if(_blacklist[up])return;
// Skip pure numbers (but keep BSE codes which are 6 digits)
if(/^[\d.,]+$/.test(up)&&!/^\d{6}$/.test(up))return;
// Skip if contains colon (metadata like "Name: XYZ")
if(up.indexOf(':')>=0)return;
// 0. ISIN detection (INExxxxxxxxxx)
if(/^INE[A-Z0-9]{9,12}$/.test(up)){
  if(_isinMap[up]){if(!seen[_isinMap[up]]){seen[_isinMap[up]]=1;found.push(_isinMap[up])}}
  return;
}
// 0b. BSE 6-digit code detection
if(/^\d{6}$/.test(up)){
  if(_bseMap[up]){if(!seen[_bseMap[up]]){seen[_bseMap[up]]=1;found.push(_bseMap[up])}}
  return;
}
// 0c. Zerodha/Kite trading symbol (RELIANCE-EQ, INFY-BE, TCS-N1)
var _cleanSym=up.replace(/-EQ$|-BE$|-BZ$|-N[0-9]$|-BL$/,'');
if(_cleanSym!==up&&/^[A-Z][A-Z0-9&]{1,19}$/.test(_cleanSym)){
  up=_cleanSym;// Strip suffix, continue with clean symbol
}
// 1. Direct NSE/US symbol match (no spaces, 2-20 chars, alphanumeric)
if(/^[A-Z][A-Z0-9&-]{1,19}$/.test(up)&&up.indexOf(' ')<0){
    var isKnown=false;
    for(var k in _nameMap){if(_nameMap[k]===up){isKnown=true;break;}}
    if(isKnown||up.length<=15){
      if(!seen[up]){seen[up]=1;found.push(up)}
    }
    return;
}
// 2. Company name matching
var matched=false;
for(var mk in _nameMap){
    if(up.indexOf(mk)>=0||mk.indexOf(up)>=0){
        var sym=_nameMap[mk];
        if(!seen[sym]){seen[sym]=1;found.push(sym)}
        matched=true;break;
    }
}
if(matched)return;
// 3. Partial match — first word
var firstWord=up.split(/[\s(,]+/)[0].replace(/[^A-Z0-9&-]/g,'');
if(firstWord.length>=2&&firstWord.length<=15){
    var fwKnown=false;
    for(var k2 in _nameMap){if(_nameMap[k2]===firstWord){fwKnown=true;break;}}
    if(fwKnown&&!seen[firstWord]){seen[firstWord]=1;found.push(firstWord)}
}
});
return found;
}

if(ext==='csv'||ext==='txt'){
symbols=_smartExtract(e.target.result);
symbols=symbols.filter(function(s,i,a){return a.indexOf(s)===i}); // Deduplicate
}else if(ext==='xlsx'){
try{
var data=new Uint8Array(e.target.result);
var wb=XLSX.read(data,{type:'array'});
// Scan ALL sheets
wb.SheetNames.forEach(function(sn){
var ws=wb.Sheets[sn];
var csv=XLSX.utils.sheet_to_csv(ws);
var _newSyms=_smartExtract(csv);_newSyms.forEach(function(s){if(symbols.indexOf(s)<0)symbols.push(s)});
});
// CRITICAL: If XLSX.read succeeded but found few/no symbols, try HTML fallback too
if(symbols.length<5&&ext==='xls'){
  console.log('XLSX parsed but only '+symbols.length+' symbols — trying HTML fallback');
  try{
    var htmlText2=new TextDecoder().decode(new Uint8Array(e.target.result));
    if(htmlText2.indexOf('<table')>=0||htmlText2.indexOf('<TABLE')>=0){
      var tmp2=document.createElement('div');tmp2.innerHTML=htmlText2;
      var allRows2=tmp2.querySelectorAll('tr');
      var colScores2={};var dataRows2=[];
      allRows2.forEach(function(tr,ri){
        var cells=tr.querySelectorAll('td,th');
        if(cells.length<3||ri<2)return;
        var rowData=[];
        cells.forEach(function(td,ci){
          var t=td.textContent.trim();rowData.push(t);
          if(ri>=3&&ri<=10){
            var up=t.toUpperCase().replace(/\.NS|\.BO/g,'');
            if(up.length>=2&&up.length<=15&&/^[A-Z][A-Z0-9&-]+$/.test(up)&&up.indexOf(' ')<0)
              colScores2[ci]=(colScores2[ci]||0)+1;
          }
        });
        if(ri>=3)dataRows2.push(rowData);
      });
      var codeCol2=1;var maxScore2=0;
      for(var ci2 in colScores2){if(colScores2[ci2]>maxScore2){maxScore2=colScores2[ci2];codeCol2=parseInt(ci2);}}
      var htmlCodes=[];
      dataRows2.forEach(function(row){
        if(row.length<=codeCol2)return;
        var code=row[codeCol2].trim().toUpperCase().replace(/\.NS|\.BO/g,'');
        if(code.length>=2&&code.length<=20&&/^[A-Z][A-Z0-9&-]+$/.test(code)&&code!=='TOTAL'&&code.indexOf(' ')<0)
          if(htmlCodes.indexOf(code)<0)htmlCodes.push(code);
      });
      if(htmlCodes.length>symbols.length){
        symbols=htmlCodes;
        console.log('HTML fallback found '+symbols.length+' symbols from column '+codeCol2);
      }
      tmp2=null;
    }
  }catch(he2){console.warn('HTML fallback after XLSX:',he2)}
}
}catch(xe){
// .xls might be HTML table (Sharekhan, Zerodha, etc.)
console.log('XLSX parse failed, trying HTML table fallback:', xe.message);
try{
  var htmlText=typeof e.target.result==='string'?e.target.result:new TextDecoder().decode(new Uint8Array(e.target.result));
  if(htmlText.indexOf('<table')>=0||htmlText.indexOf('<TABLE')>=0){
    // Extract from HTML table — DATA-PATTERN column detection
    // Broker exports often have swapped headers (SKScripCode=name, Stock Name=code)
    // So detect by DATA: find column where most values are SHORT UPPERCASE (2-15 chars, no spaces)
    var tmp=document.createElement('div');tmp.innerHTML=htmlText;
    var allRows=tmp.querySelectorAll('tr');
    var extractedCodes=[];
    
    // Step 1: Score each column by how many short uppercase codes it has
    var colScores={};
    var dataRows=[];
    allRows.forEach(function(tr,ri){
      var cells=tr.querySelectorAll('td,th');
      if(cells.length<3||ri<2)return;// Skip metadata rows
      var rowData=[];
      cells.forEach(function(td,ci){
        var t=td.textContent.trim();
        rowData.push(t);
        if(ri>=3&&ri<=10){// Sample first 8 data rows
          var up=t.toUpperCase().replace(/\.NS|\.BO/g,'');
          if(up.length>=2&&up.length<=15&&/^[A-Z][A-Z0-9&-]+$/.test(up)&&up.indexOf(' ')<0){
            colScores[ci]=(colScores[ci]||0)+1;
          }
        }
      });
      if(ri>=3)dataRows.push(rowData);
    });
    
    // Step 2: Pick the column with highest score (most short uppercase codes)
    var codeCol=1;// Default
    var maxScore=0;
    for(var ci in colScores){
      if(colScores[ci]>maxScore){maxScore=colScores[ci];codeCol=parseInt(ci);}
    }
    console.log('Column scores:',JSON.stringify(colScores),'→ using column '+codeCol);
    
    // Step 3: Extract all codes from winning column
    dataRows.forEach(function(row){
      if(row.length<=codeCol)return;
      var code=row[codeCol].trim().toUpperCase().replace(/\.NS|\.BO/g,'');
      if(code.length>=2&&code.length<=20&&/^[A-Z][A-Z0-9&-]+$/.test(code)&&code!=='TOTAL'&&code.indexOf(' ')<0){
        if(extractedCodes.indexOf(code)<0)extractedCodes.push(code);
      }
    });
    
    if(extractedCodes.length>3){
      symbols=extractedCodes;
      // NO supplement — column extraction is clean and sufficient
      // _smartExtract on all cells causes false positives from company names
    }else{
      // Fallback: _smartExtract on all cells
      var cellTexts=[];
      dataRows.forEach(function(row){
        row.forEach(function(t){if(t.length>=2&&t.length<=20)cellTexts.push(t)});
      });
      symbols=_smartExtract(cellTexts.join(','));
      symbols=symbols.filter(function(s,i,a){return a.indexOf(s)===i});
    }
    tmp=null;
    console.log('HTML table: found '+symbols.length+' symbols from column '+codeCol);
  }else{
    // Try as plain text
    var textContent=htmlText;
    symbols=_smartExtract(textContent);
    symbols=symbols.filter(function(s,i,a){return a.indexOf(s)===i});
  }
}catch(he){_unlockUI();el.innerHTML='<div style="color:#ef4444;padding:16px">Error reading file: '+he.message+'. Try saving as CSV.</div>';return;}
}
}else if(ext==='xls'){
// .xls read as text — check if HTML table
var fileText=e.target.result;
if(fileText.indexOf('<table')>=0||fileText.indexOf('<TABLE')>=0||fileText.indexOf('<tr')>=0){
  console.log('.xls is HTML table — parsing directly');
  var tmp=document.createElement('div');tmp.innerHTML=fileText;
  var allRows=tmp.querySelectorAll('tr');
  var colScores={};var dataRows=[];
  // Phase 1: Score ALL rows (not just 3-10) to find the NSE code column
  allRows.forEach(function(tr,ri){
    var cells=tr.querySelectorAll('td,th');
    if(cells.length<2)return;
    var rowData=[];
    cells.forEach(function(td,ci){
      var t=td.textContent.trim();rowData.push(t);
      // Score every row (skip first 1 header row only)
      if(ri>=1){
        var up=t.toUpperCase().replace(/\.NS|\.BO|\.BSE/g,'').replace(/[\s]+/g,'');
        // Match: 2-15 chars, starts with letter, all uppercase alphanumeric
        if(up.length>=2&&up.length<=15&&/^[A-Z][A-Z0-9&-]+$/.test(up)&&up.indexOf(' ')<0)
          colScores[ci]=(colScores[ci]||0)+1;
      }
    });
    if(ri>=1)dataRows.push(rowData);
  });
  // Pick column with most NSE-like codes
  var codeCol=0;var maxSc=0;
  for(var ci in colScores){if(colScores[ci]>maxSc){maxSc=colScores[ci];codeCol=parseInt(ci);}}
  console.log('Column scores:',JSON.stringify(colScores),'using col '+codeCol+' ('+maxSc+' hits from '+allRows.length+' rows)');
  // Phase 2: Extract ALL codes from winning column
  dataRows.forEach(function(row){
    if(row.length<=codeCol)return;
    var code=row[codeCol].trim().toUpperCase().replace(/\.NS|\.BO|\.BSE/g,'').replace(/[\s]+/g,'');
    if(code.length>=2&&code.length<=20&&/^[A-Z][A-Z0-9&-]+$/.test(code)&&code!=='TOTAL'&&code!=='SYMBOL'&&code!=='SCRIP'&&code.indexOf(' ')<0)
      if(symbols.indexOf(code)<0)symbols.push(code);
  });
  // Phase 3: Also try _nameMap on ALL text cells (catch company names)
  if(symbols.length<10){
    console.log('Column extraction got only '+symbols.length+' — also scanning by name');
    dataRows.forEach(function(row){
      row.forEach(function(t){
        var up=t.trim().toUpperCase();
        if(_nameMap[up]&&symbols.indexOf(_nameMap[up])<0)symbols.push(_nameMap[up]);
        // Try partial match
        for(var nm in _nameMap){
          if(up.indexOf(nm)>=0&&symbols.indexOf(_nameMap[nm])<0)symbols.push(_nameMap[nm]);
        }
      });
    });
  }
  tmp=null;
  console.log('HTML .xls: extracted '+symbols.length+' symbols');
}else{
  // Not HTML — try as plain text
  symbols=_smartExtract(fileText);
  symbols=symbols.filter(function(s,i,a){return a.indexOf(s)===i});
}
}else{_unlockUI();el.innerHTML='<div style="color:#ef4444;padding:16px">Unsupported format. Please upload .csv, .txt, or .xlsx</div>';return;}

// Deduplicate + filter junk (common column headers, numbers, etc)
var _junk=['SYMBOL','TICKER','STOCK','COMPANY','NAME','SECURITY','SCRIP','STOCKNAME','ISIN','DATE','PRICE','QTY','QUANTITY','BUY','SELL','TOTAL','AMOUNT','VALUE','PORTFOLIO','SECTOR','INDUSTRY','MARKET','CAP','EXCHANGE','TYPE','STATUS','ACTION','WEIGHT','ALLOCATION','NOTES','SR','NO','SL','SERIAL','INDEX','CHANGE','VOLUME','HIGH','LOW','OPEN','CLOSE','LTP','PREV','AVG','NET','PNL','PROFIT','LOSS','RETURN','RETURNS','CAGR','PE','PB','ROE','EPS','DIV','DIVIDEND','YIELD','CATEGORY','RISK','RATING'];
symbols=[...new Set(symbols)].filter(function(s){return s&&s.length>=2&&s.length<=20&&_junk.indexOf(s)<0&&!/^\d+$/.test(s)&&!/^[A-Z]$/.test(s);});
if(symbols.length===0){_unlockUI();el.innerHTML='<div style="padding:30px;text-align:center"><div style="font-size:40px;margin-bottom:8px">❌</div><div style="font-size:14px;font-weight:800;color:#ef4444">No stock symbols found</div><div style="font-size:10px;color:#2d4373;margin-top:6px;max-width:420px;margin-left:auto;margin-right:auto;line-height:1.6">Could not extract NSE symbols from your file. <br><br><strong>Supported formats:</strong><br>1. CSV with column: <strong>Symbol</strong> (RELIANCE, TCS, INFY)<br>2. CSV with column: <strong>Company Name</strong> (we auto-map 50+ companies)<br>3. Excel (.xlsx) with same columns<br><br><strong>Example CSV:</strong><br><code style="background:#f1f5f9;padding:6px 10px;border-radius:6px;font-size:9px;display:inline-block;text-align:left">Symbol<br>RELIANCE<br>TCS<br>INFY<br>HDFCBANK</code></div><button onclick="document.getElementById(\'portfolioFile\').click()" style="margin-top:12px;padding:8px 18px;border-radius:8px;background:linear-gradient(135deg,#1A3A78,#1e40af);color:#fff;border:none;font-size:11px;font-weight:700;cursor:pointer">🔄 Try Another File</button></div>';input.value='';return;}
// No cap — scan ALL stocks in portfolio
