h+='</div></div>';

// Row 2: Strategy + Full trade levels
h+='<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px">';
// Strategy card
var strC=idx.strategy.indexOf('BUY')>=0?'#10b981':idx.strategy.indexOf('SELL')>=0?'#f59e0b':idx.strategy==='AVOID'||idx.strategy.indexOf('NO EDGE')>=0?'#ef4444':'#3b82f6';
h+='<div style="flex:1;min-width:160px;padding:8px 12px;border-radius:10px;background:'+strC+'06;border:1px solid '+strC+'15">';
