h+='<div style="flex:0.5;padding:6px 4px;background:#1A3A7812"><div style="font-size:7px;color:#1A3A78;font-weight:800">R:R</div><div style="font-weight:900;color:#1A3A78;font-family:var(--mono);font-size:11px">1:'+idx.rr+'</div></div>';
h+='</div>';
