// FORCE HIDE all tabs, sub-tabs, report on fresh page load
var _mtb=document.getElementById('mainTabBar');if(_mtb){_mtb.classList.add('tab-bar-hidden');_mtb.style.display='none';}
var _sst=document.getElementById('summarySubTabs');if(_sst)_sst.style.display='none';
var _gsn=document.getElementById('groupSubNav');if(_gsn)_gsn.style.display='none';
var _rpt=document.getElementById('report');if(_rpt){_rpt.style.display='none';_rpt.classList.remove('show');}
// Normal init — show placeholder immediately
