function _proAccordion(id,title,sub,open,content){
return '<details'+(open?' open':'')+' style="margin-bottom:10px;border:1px solid var(--border);border-radius:14px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,.03)"><summary style="padding:14px 18px;background:var(--surface);cursor:pointer;list-style:none;display:flex;justify-content:space-between;align-items:center;user-select:none"><div><div style="font-family:Sora,sans-serif;font-size:13px;font-weight:800;color:var(--text)">'+title+'</div><div style="font-size:9px;color:#2d4373;margin-top:2px">'+sub+'</div></div><span style="font-size:14px;color:#2d4373">▾</span></summary><div style="padding:16px 18px;border-top:1px solid var(--border)">'+content+'</div></details>'
}

function _proGauge(label,value,max,color){
var pct=Math.min(100,Math.max(0,value/max*100));
return '<div style="text-align:center"><div style="font-size:8px;color:var(--text3);font-weight:700;letter-spacing:.5px;margin-bottom:4px">'+label+'</div><div style="position:relative;width:56px;height:56px;margin:0 auto"><svg width="56" height="56" viewBox="0 0 56 56"><circle cx="28" cy="28" r="22" fill="none" stroke="var(--border)" stroke-width="4"/><circle cx="28" cy="28" r="22" fill="none" stroke="'+color+'" stroke-width="4" stroke-linecap="round" stroke-dasharray="'+138.2+'" stroke-dashoffset="'+(138.2*(1-pct/100))+'" transform="rotate(-90 28 28)"/><text x="28" y="26" text-anchor="middle" font-size="14" font-weight="900" fill="'+color+'" font-family="var(--mono)">'+value+'</text><text x="28" y="38" text-anchor="middle" font-size="7" fill="var(--text3)">/ '+max+'</text></svg></div></div>'
}

function _proFmt(v,csym){
if(!v||v===0)return 'N/A';
var a=Math.abs(v);var s=v<0?'-':'';
if(a>=1e12)return s+csym+(a/1e12).toFixed(1)+'T';
if(a>=1e9)return s+csym+(a/1e9).toFixed(1)+'B';
if(a>=1e7)return s+csym+(a/1e7).toFixed(1)+'Cr';
return s+csym+a.toLocaleString();
}

