function _fmtPMS(val, sym) {
  if (!val || val === 0) return sym + '0';
  var abs = Math.abs(val);
  if (sym === '₹') {
    // India: Lakh (1L = 100,000) and Crore (1Cr = 10,000,000)
    if (abs >= 10000000) return sym + (val / 10000000).toFixed(1) + 'Cr';
    if (abs >= 100000) return sym + (val / 100000).toFixed(1) + 'L';
    if (abs >= 1000) return sym + (val / 1000).toFixed(1) + 'K';
    return sym + val.toFixed(0);
  } else {
    // US: $K, $M, $B
    if (abs >= 1000000000) return sym + (val / 1000000000).toFixed(1) + 'B';
    if (abs >= 1000000) return sym + (val / 1000000).toFixed(1) + 'M';
    if (abs >= 1000) return sym + (val / 1000).toFixed(1) + 'K';
    return sym + val.toFixed(0);
  }
}
