function _openLiveSim(sym){
if(!sym)sym=window._lastDESym||window._lastAnalyzedSymbol||'RELIANCE';
var reg=window._deRegion||window._globalRegion||'IN';
var el=document.getElementById('liveSimArea');
if(!el){el=document.getElementById('jargonBusterArea');if(!el)return}
el.innerHTML='<div style="padding:20px;text-align:center"><div style="display:inline-block;width:16px;height:16px;border:2px solid #1A3A78;border-top-color:transparent;border-radius:50%;animation:spin .5s linear infinite;vertical-align:middle;margin-right:8px"></div><span style="font-size:11px;color:#2d4373">Loading '+sym+' live data...</span></div>';
fetch('/api/algo-signal?symbol='+encodeURIComponent(sym)+'&region='+reg).then(function(r){return r.json()}).then(function(d){
if(!d.success){el.innerHTML='<div style="padding:20px;text-align:center;color:var(--red)">Could not load '+sym+': '+(d.error||'Unknown error')+'</div>';return}
var S=reg==='US'?'$':'₹';var price=d.price||0;
var h='<div style="padding:14px;border-radius:14px;background:linear-gradient(135deg,rgba(124,58,237,.06),rgba(59,130,246,.04));border:1px solid rgba(124,58,237,.12);margin-bottom:12px">';
h+='<div style="display:flex;justify-content:space-between;align-items:center"><div>';
h+='<div style="font-size:16px;font-weight:900;color:var(--text)">🔬 '+d.symbol+' — Live Analysis</div>';
h+='<div style="font-size:9px;color:var(--text2)">9 modules · Real-time · '+new Date().toLocaleTimeString()+'</div></div>';
h+='<div style="text-align:right"><div style="font-size:20px;font-weight:900;color:var(--text);font-family:var(--mono)">'+S+price.toFixed(2)+'</div>';
h+='<div style="font-size:10px;font-weight:700;color:'+(d.direction==='LONG'?'var(--green)':'var(--red)')+'">'+d.direction+' · '+(d.grade||'—')+'</div></div></div></div>';
h+=_renderV2Charts(d);
h+='<div style="text-align:center;margin-top:8px"><button onclick="_openLiveSim()" style="padding:6px 16px;border-radius:8px;background:linear-gradient(135deg,#1A3A78,#1e40af);color:#fff;border:none;font-size:10px;font-weight:700;cursor:pointer;margin-right:6px">🔄 Refresh</button>';
h+='<input id="_simSymInput" placeholder="Enter symbol" value="'+sym+'" style="padding:6px 10px;border-radius:8px;border:1px solid var(--border);background:#f1f5f9;color:var(--text);font-family:var(--mono);font-size:10px;width:100px">';
h+='<button onclick="_openLiveSim(document.getElementById(\'_simSymInput\').value.toUpperCase())" style="padding:6px 12px;border-radius:8px;background:linear-gradient(135deg,#1A3A78,#1e40af);color:#fff;border:none;font-size:10px;font-weight:700;cursor:pointer;margin-left:4px">Analyze</button></div>';
el.innerHTML=h;
}).catch(function(e){el.innerHTML='<div style="padding:20px;text-align:center;color:var(--red)">Error: '+e.message+'</div>'});
}



