function _investorExportPDF(){
if(!window._isPdfUser)return;

var d=window._lastInvestorData;if(!d){alert('Analyze a stock first');return}
var S=d.csym||'\u20b9';
console.log('[PDF] Generating full report PDF for',d.symbol);

// Get the full rendered report from the DOM
var srcEl=document.getElementById('deResult');
if(!srcEl||srcEl.innerHTML.length<500){alert('No report to export. Analyze a stock first.');return}

// Clone the entire report
var clone=srcEl.cloneNode(true);

// Open all <details> tags so everything is visible
clone.querySelectorAll('details').forEach(function(det){det.setAttribute('open','')});

// Remove interactive elements (buttons, inputs) but keep content
clone.querySelectorAll('button,input,select,textarea').forEach(function(el){
  // Keep the text content if it\'s informational
  if(el.tagName==='BUTTON'&&el.textContent.length>20){
    var span=document.createElement('span');
    span.textContent=el.textContent;
    span.style.cssText='font-size:10px;color:#6b7280;font-style:italic';
    el.replaceWith(span);
  } else {
    el.remove();
  }
});

// Remove retry buttons, scanners etc
clone.querySelectorAll('[onclick*="loadInvestorDE"],[onclick*="runCrossMarket"],[onclick*="switchTab"],[onclick*="_topStocksReport"]').forEach(function(el){el.remove()});

// Get all stylesheets from the page
var styles='';
document.querySelectorAll('link[rel="stylesheet"],style').forEach(function(s){
  if(s.tagName==='STYLE'){styles+=s.outerHTML}
  else if(s.href){styles+='<link rel="stylesheet" href="'+s.href+'">'}
});

// Also inline the CSS variables
var rootStyles=getComputedStyle(document.documentElement);
var cssVars='';
['--bg','--bg2','--bg3','--surface','--glass','--border','--border2','--blue','--blue2',
 '--cyan','--teal','--green','--green2','--amber','--red','--purple',
 '--text','--text2','--text3','--mono'].forEach(function(v){
  try{cssVars+=v+':'+rootStyles.getPropertyValue(v)+';'}catch(e){}
});

var h='<!DOCTYPE html><html><head><meta charset="UTF-8"><title>'+d.symbol+' \u2014 Celesys AI Report</title>';
h+=styles;
h+='<style>';
h+=':root{'+cssVars+'}';
h+='body{font-family:"DM Sans","Segoe UI",system-ui,sans-serif;padding:20px 30px;color:#1f2937;background:#fff;max-width:900px;margin:0 auto}';
h+='@media print{body{padding:10px 15px;max-width:100%}button,input,select,.no-print{display:none!important}details{display:block!important}details>summary{display:none!important}details>*:not(summary){display:block!important}}';
h+='@page{margin:10mm 8mm;size:A4}';
h+='</style></head><body>';

// Header
h+='<div style="text-align:center;padding-bottom:14px;border-bottom:3px solid #1A3A78;margin-bottom:14px">';
h+='<div style="font-size:24px;font-weight:900;color:#1A3A78;font-family:Sora,sans-serif">'+d.symbol+' \u2014 '+(d.companyName||d.symbol)+'</div>';
h+='<div style="font-size:11px;color:#6b7280">Celesys AI Report \u00b7 LIVE \u00b7 '+new Date().toLocaleString()+'</div></div>';

// Full report content
h+=clone.outerHTML;

// Footer
h+='<div style="margin-top:20px;padding:12px;border-top:2px solid #1A3A78;text-align:center;font-size:9px;color:#4a6fa5">';
h+='Generated by Celesys AI \u00b7 celesys.ai \u00b7 For educational purposes only. Not financial advice.</div>';
h+='</body></html>';

// Method 1: Try window.open
var w=window.open('','_blank','width=960,height=800');
if(w&&!w.closed){
  console.log('[PDF] Window opened, writing report...');
  w.document.write(h+'<script>setTimeout(function(){window.print()},1200)<\/script>');
  w.document.close();
  return;
}

// Method 2: Blob download fallback
console.log('[PDF] Popup blocked, downloading HTML...');
var blob=new Blob([h],{type:'text/html;charset=utf-8'});
var url=URL.createObjectURL(blob);
var a=document.createElement('a');
a.href=url;a.download=d.symbol+'_Celesys_Full_Report.html';
document.body.appendChild(a);a.click();
setTimeout(function(){document.body.removeChild(a);URL.revokeObjectURL(url)},1000);
alert('Report downloaded as HTML.\nOpen it in your browser and press Ctrl+P to save as PDF.\n\nTip: In print settings, set Margins to "Minimum" and enable "Background graphics".');
}

