// r63.1: Deep DD Toolbar — PDF export, Print, Copy URL
// ═══════════════════════════════════════════════════════════════════
// Adds 3 icon buttons floating top-right of the DD report.
// Tooltips on hover. Keyboard accessible (aria-labels).

window._csInjectDDToolbar = function() {
  // Don't add toolbar twice
  if (document.getElementById('csDDToolbar')) return;

  // Only add if there's actual report content (not error or loading state)
  var el = document.getElementById('deResult');
  if (!el) return;
  // Heuristic: report exists if it has substantial content (>1000 chars HTML)
  if (el.innerHTML.length < 1000) return;
  // Don't add if currently in error state
  if (el.querySelector('.cs-error-block')) return;

  var bar = document.createElement('div');
  bar.id = 'csDDToolbar';
  bar.setAttribute('role', 'toolbar');
  bar.setAttribute('aria-label', 'Report actions');
  bar.style.cssText = 'position:sticky;top:12px;float:right;z-index:50;display:flex;gap:6px;background:#fff;border:1px solid #e2e8f0;border-radius:8px;padding:5px;box-shadow:0 2px 8px rgba(0,0,0,0.06);font-family:Inter,sans-serif;margin-bottom:10px;margin-right:8px';

  bar.innerHTML = '' +
    // PDF button
    '<button onclick="window._csExportPDF()" data-tooltip="Export full report as PDF" aria-label="Export as PDF" class="cs-tb-btn">' +
      '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="9" y1="13" x2="15" y2="13"/><line x1="9" y1="17" x2="15" y2="17"/></svg>' +
      '<span style="font-size:10px;font-weight:700;letter-spacing:0.4px">PDF</span>' +
    '</button>' +
    // Print button
    '<button onclick="window._csPrintReport()" data-tooltip="Print report (browser dialog)" aria-label="Print report" class="cs-tb-btn">' +
      '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 6 2 18 2 18 9"/><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><rect x="6" y="14" width="12" height="8"/></svg>' +
    '</button>' +
    // Copy URL button
    '<button onclick="window._csCopyReportURL(this)" data-tooltip="Copy shareable link" aria-label="Copy URL" class="cs-tb-btn">' +
      '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"/><path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"/></svg>' +
    '</button>';

  // Insert toolbar at the TOP of deResult (sticky positioning makes it stay visible while scrolling)
  el.insertBefore(bar, el.firstChild);

  // Inject styles ONCE per session
  if (!document.getElementById('csTbStyles')) {
    var style = document.createElement('style');
    style.id = 'csTbStyles';
    style.textContent = '' +
      '.cs-tb-btn { display:inline-flex; align-items:center; gap:5px; padding:6px 10px; background:#fff; color:#475569; border:1px solid #e2e8f0; border-radius:6px; cursor:pointer; transition:all 120ms; position:relative; }' +
      '.cs-tb-btn:hover { background:#1A3A78; color:#fff; border-color:#1A3A78; }' +
      '.cs-tb-btn:active { transform:scale(0.96); }' +
      '.cs-tb-btn:focus-visible { outline:2px solid #1A3A78; outline-offset:2px; }' +
      // Tooltip via data-tooltip attribute
      '.cs-tb-btn[data-tooltip]::after { content:attr(data-tooltip); position:absolute; top:100%; right:0; margin-top:8px; padding:5px 9px; background:#0f172a; color:#fff; font-size:10px; font-weight:600; border-radius:4px; white-space:nowrap; opacity:0; pointer-events:none; transition:opacity 150ms; letter-spacing:0.2px; }' +
      '.cs-tb-btn[data-tooltip]:hover::after { opacity:1; }' +
      '.cs-tb-btn[data-tooltip]::before { content:""; position:absolute; top:100%; right:14px; margin-top:3px; border:5px solid transparent; border-bottom-color:#0f172a; opacity:0; pointer-events:none; transition:opacity 150ms; }' +
      '.cs-tb-btn[data-tooltip]:hover::before { opacity:1; }' +
      // Print-only styles for Print button workflow
      '@media print { #csDDToolbar { display:none !important; } body { background:#fff !important; } }' +
      // Loading state
      '.cs-tb-btn.is-loading { pointer-events:none; opacity:0.6; }' +
      '.cs-tb-btn.is-loading svg { animation:csTbSpin 0.7s linear infinite; }' +
      '@keyframes csTbSpin { to { transform:rotate(360deg); } }';
    document.head.appendChild(style);
  }
};


// ═══════════════════════════════════════════════════════════════════
// PDF EXPORT — uses jsPDF + html2canvas (loaded from CDN in index.html)
// ═══════════════════════════════════════════════════════════════════
// ═══════════════════════════════════════════════════════════════════
// r63.77.0: PDF APPENDIX BUILDER — captures Wealth Pro, Market Pulse,
// Cross-Market Scanner, Similar Stocks, 360° Cycle Analysis as a PDF
// appendix so they appear in the exported document.
// These buttons normally open modals/replace the page, so their output
// is invisible to html2canvas which captures #deResult only. The
// appendix pre-fetches each endpoint, builds compact summary cards,
// appends to #deResult right before PDF capture, then cleans up.
// ═══════════════════════════════════════════════════════════════════

window._csBuildPDFAppendix = async function(sym, reg) {
  sym = (sym || window._ddLastSymbol || '').toUpperCase();
  reg = reg || window._deRegion || 'US';
  var S = reg === 'US' ? '$' : '₹';

  // Helper: safe numeric formatter
  var fNum = function(v, dec) { if (v == null || v === '') return '—'; var n = parseFloat(v); return isNaN(n) ? '—' : n.toFixed(dec != null ? dec : 1); };
  var fPct = function(v, dec) { if (v == null || v === '') return '—'; var n = parseFloat(v); if (isNaN(n)) return '—'; var c = n > 0 ? '#059669' : n < 0 ? '#dc2626' : '#64748b'; return '<span style="color:' + c + ';font-weight:700">' + (n > 0 ? '+' : '') + n.toFixed(dec != null ? dec : 1) + '%</span>'; };

  // r63.81.0 fix: serialize objects/arrays defensively (was rendering "[object Object]" in PDF)
  var fStr = function(v) {
    if (v == null) return null;
    if (typeof v === 'string') return v.trim() === '' ? null : v;
    if (typeof v === 'number' || typeof v === 'boolean') return String(v);
    if (typeof v === 'object') {
      var picked = v.verdict || v.label || v.value || v.signal || v.status ||
                   v.text || v.summary || v.description || v.name;
      if (picked != null) return String(picked);
      if (typeof v.score === 'number') return String(v.score);
      try { return JSON.stringify(v).slice(0, 80); } catch(_) { return null; }
    }
    return String(v);
  };

  // r63.81.0 fix: force-open all <details> so html2canvas captures section bodies
  // (otherwise Wealth Pro appendix prints with only headers visible, bodies hidden)
  var fOpen = function(html) {
    if (!html) return html;
    return html.replace(/<details(?!\s+open)(\s[^>]*)?>/g, '<details open$1>');
  };

  // Run all 5 fetches in parallel
  var endpoints = [
    fetch('/api/pro-scan?symbol=' + encodeURIComponent(sym) + '&region=' + reg).then(function(r){return r.json();}).catch(function(e){return {success:false,error:e.message};}),
    fetch('/api/market-context?symbol=' + encodeURIComponent(sym) + '&region=' + reg).then(function(r){return r.json();}).catch(function(e){return {success:false,error:e.message};}),
    fetch('/api/cross-market-match?symbol=' + encodeURIComponent(sym) + '&region=' + reg + '&mode=cross').then(function(r){return r.json();}).catch(function(e){return {success:false,error:e.message};}),
    fetch('/api/cross-market-match?symbol=' + encodeURIComponent(sym) + '&region=' + reg + '&mode=same').then(function(r){return r.json();}).catch(function(e){return {success:false,error:e.message};}),
    fetch('/api/cycle-analysis?symbol=' + encodeURIComponent(sym) + '&region=' + reg + '&price=' + (window._lastInvestorData && window._lastInvestorData.price || 0) + '&market_cap=' + (window._lastInvestorData && window._lastInvestorData.market_cap || 0)).then(function(r){return r.json();}).catch(function(e){return {success:false,error:e.message};}),
  ];
  var results = await Promise.all(endpoints);
  var ps = results[0], mp = results[1], xmCross = results[2], xmSame = results[3], cy = results[4];

  // ─── Appendix wrapper ───
  var h = '<div id="csPdfAppendix" style="margin-top:32px;page-break-before:always">';

  // Section divider
  h += '<div style="padding:18px 22px;background:linear-gradient(135deg,#0A1628,#1A3A78);color:#fff;border-radius:14px 14px 0 0;display:flex;align-items:center;justify-content:space-between">';
  h += '<div><div style="font-size:11px;letter-spacing:1.5px;font-weight:800;opacity:0.85;font-family:Sora,sans-serif">PDF APPENDIX</div>';
  h += '<div style="font-size:18px;font-weight:900;margin-top:2px;font-family:Sora,sans-serif">📎 Deep Scan Outputs</div>';
  h += '<div style="font-size:10px;margin-top:4px;opacity:0.75">Auto-captured · Wealth Pro · Market Pulse · Cross-Market · Similar Stocks · 360° Cycle</div></div>';
  h += '<div style="font-size:9px;opacity:0.7;font-family:JetBrains Mono,monospace">' + sym + ' · ' + reg + '</div>';
  h += '</div>';

  // ═══ 1. WEALTH PRO — force all <details open> for print capture ═══
  h += '<div style="margin:18px 0;border:1px solid #e2e8f0;border-radius:14px;background:#fff;overflow:hidden">';
  h += '<div style="padding:12px 18px;background:#1A3A7810;border-bottom:2px solid #1A3A7840"><div style="font-size:13px;font-weight:900;color:#1A3A78;font-family:Sora,sans-serif">🔬 Wealth Pro Scan — ROIC · Reverse DCF · Monte Carlo · Legend Match</div></div>';
  if (ps && ps.success && typeof window._renderProScan === 'function') {
    try { h += '<div style="padding:14px 18px">' + fOpen(window._renderProScan(ps)) + '</div>'; }
    catch(e) { h += '<div style="padding:14px 18px;font-size:11px;color:#7f1d1d">⚠ Render error: ' + e.message + '</div>'; }
  } else {
    h += '<div style="padding:14px 18px;font-size:11px;color:#7f1d1d">⚠ ' + ((ps && ps.error) || 'Wealth Pro endpoint unavailable') + '</div>';
  }
  h += '</div>';

  // ═══ 2. MARKET PULSE — defensive object serializer for verdict/momentum/sectorFlow ═══
  h += '<div style="margin:18px 0;border:1px solid #e2e8f0;border-radius:14px;background:#fff;overflow:hidden">';
  h += '<div style="padding:12px 18px;background:#0d948814;border-bottom:2px solid #0d948840"><div style="font-size:13px;font-weight:900;color:#0d9488;font-family:Sora,sans-serif">🌊 Market Pulse — Sector Rotation · Momentum · Trend · Analyst Revisions</div></div>';
  if (mp && mp.success) {
    var ctxV = fStr(mp.contextVerdict || mp.verdict) || 'NEUTRAL';
    var ctxC = ctxV === 'TAILWIND' ? '#059669' : ctxV === 'HEADWIND' ? '#dc2626' : '#d97706';
    h += '<div style="padding:14px 18px">';
    h += '<div style="display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin-bottom:12px">';
    h += '<div style="padding:6px 14px;border-radius:6px;background:' + ctxC + '15;border:1px solid ' + ctxC + '40;font-size:11px;font-weight:900;color:' + ctxC + '">' + ctxV + '</div>';
    if (mp.contextScore != null) h += '<div style="font-size:11px;color:#64748b">Context Score: <strong style="color:#0f172a;font-family:JetBrains Mono,monospace">' + fNum(mp.contextScore, 0) + '/100</strong></div>';
    h += '</div>';
    h += '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:8px;margin-bottom:10px">';
    var mpFields = [
      ['Trend', mp.trend || mp.trendVerdict],
      ['Momentum', mp.momentum || mp.momentumVerdict],
      ['Sector Flow', mp.sectorFlow || mp.sectorVerdict],
      ['Volatility Regime', mp.volatilityRegime || mp.volRegime],
      ['Analyst Revisions', mp.analystRevisions || mp.revisions],
      ['Price-Earnings Gap', mp.peGap],
    ];
    mpFields.forEach(function(f) {
      var val = fStr(f[1]);
      if (val != null) {
        h += '<div style="padding:8px 10px;border-radius:6px;background:#f8fafc;border:1px solid #e2e8f0"><div style="font-size:8px;color:#64748b;font-weight:800;letter-spacing:0.4px;text-transform:uppercase">' + f[0] + '</div><div style="font-size:11px;font-weight:700;color:#0f172a;margin-top:2px">' + val + '</div></div>';
      }
    });
    h += '</div>';
    var mpSummary = fStr(mp.summary || mp.commentary || mp.explain);
    if (mpSummary) h += '<div style="margin-top:10px;padding:10px 12px;background:#f0fdfa;border-left:3px solid #0d9488;border-radius:0 6px 6px 0;font-size:11px;color:#0f172a;line-height:1.5">' + mpSummary + '</div>';
    h += '</div>';
  } else {
    h += '<div style="padding:14px 18px;font-size:11px;color:#7f1d1d">⚠ ' + ((mp && mp.error) || 'Market Pulse endpoint unavailable') + '</div>';
  }
  h += '</div>';

  // ═══ 3 & 4. CROSS-MARKET + SIMILAR STOCKS — handle bucketed response (investNow/exactMatch/wait/avoid) ═══
  var _renderXM = function(data, title, icon, color, region_label) {
    var card = '<div style="margin:18px 0;border:1px solid #e2e8f0;border-radius:14px;background:#fff;overflow:hidden">';
    card += '<div style="padding:12px 18px;background:' + color + '14;border-bottom:2px solid ' + color + '40"><div style="font-size:13px;font-weight:900;color:' + color + ';font-family:Sora,sans-serif">' + icon + ' ' + title + ' — ' + region_label + '</div></div>';

    if (!data || !data.success) {
      card += '<div style="padding:14px 18px;font-size:11px;color:#7f1d1d">⚠ ' + ((data && data.error) || 'Endpoint unavailable') + '</div>';
      card += '</div>';
      return card;
    }

    // r63.81.0 fix: backend returns BUCKETED categories (investNow / exactMatch / wait / avoid)
    // Flatten them in priority order so the table shows best matches first.
    var rows = [];
    if (Array.isArray(data.results)) rows = data.results;
    else if (Array.isArray(data.matches)) rows = data.matches;
    else if (Array.isArray(data.peers)) rows = data.peers;
    else {
      ['exactMatch','investNow','wait','avoid','candidates'].forEach(function(k){
        if (Array.isArray(data[k])) rows = rows.concat(data[k].map(function(r){ r._bucket = k; return r; }));
      });
    }

    if (rows.length === 0) {
      card += '<div style="padding:14px 18px;font-size:11px;color:#64748b;font-style:italic">No similar stocks returned by the scanner.</div>';
      card += '</div>';
      return card;
    }

    // Show source profile summary if present
    var sp = data.sourceProfile || {};
    if (sp.confidence != null || sp.fScore != null) {
      card += '<div style="padding:10px 18px;background:#fafbfc;border-bottom:1px solid #f1f5f9;display:flex;gap:14px;flex-wrap:wrap;font-size:10px;color:#475569">';
      if (sp.confidence != null) card += '<span>Match confidence: <strong style="color:#0f172a;font-family:JetBrains Mono,monospace">' + fNum(sp.confidence, 0) + '</strong></span>';
      if (sp.fScore != null) card += '<span>Source F-Score: <strong style="color:#0f172a;font-family:JetBrains Mono,monospace">' + sp.fScore + '/9</strong></span>';
      if (sp.moatScore != null) card += '<span>Source moat: <strong style="color:#0f172a;font-family:JetBrains Mono,monospace">' + sp.moatScore + '</strong></span>';
      if (data.totalScanned) card += '<span style="margin-left:auto">Scanned <strong>' + data.totalScanned + '</strong> stocks</span>';
      card += '</div>';
    }

    card += '<div style="padding:14px 18px"><table style="width:100%;border-collapse:collapse;font-size:10px;font-family:Inter,sans-serif">';
    card += '<thead><tr style="background:#fafbfc"><th style="padding:7px 8px;text-align:left;font-size:9px;color:#64748b;font-weight:800">SYMBOL</th><th style="padding:7px 8px;text-align:left;font-size:9px;color:#64748b;font-weight:800">NAME</th><th style="padding:7px 8px;text-align:right;font-size:9px;color:#64748b;font-weight:800">PRICE</th><th style="padding:7px 8px;text-align:right;font-size:9px;color:#64748b;font-weight:800">SCORE</th><th style="padding:7px 8px;text-align:right;font-size:9px;color:#64748b;font-weight:800">UPSIDE</th><th style="padding:7px 8px;text-align:center;font-size:9px;color:#64748b;font-weight:800">BUCKET</th></tr></thead><tbody>';
    rows.slice(0, 10).forEach(function(r, i) {
      var rowBg = i % 2 === 0 ? '#fff' : '#fafbfc';
      var sym2 = r.symbol || r.ticker || '—';
      var name = String(r.companyName || r.name || '').substring(0, 32);
      var price = r.price || r.spot;
      var score = r.score || r.investability_score || r.match_score || r.confidence;
      var upside = r.upside || r.upside_pct;
      var bucket = (r._bucket || r.verdict || r.decision || r.signal || '—').toString().toUpperCase();
      var vC = bucket.indexOf('INVEST') >= 0 || bucket.indexOf('BUY') >= 0 || bucket.indexOf('EXACT') >= 0 ? '#059669' :
               bucket.indexOf('AVOID') >= 0 || bucket.indexOf('SELL') >= 0 ? '#dc2626' :
               bucket.indexOf('WAIT') >= 0 || bucket.indexOf('HOLD') >= 0 ? '#d97706' : '#64748b';
      var bucketLabel = bucket === 'INVESTNOW' ? 'INVEST NOW' : bucket === 'EXACTMATCH' ? 'EXACT MATCH' : bucket;
      card += '<tr style="background:' + rowBg + '">';
      card += '<td style="padding:6px 8px;font-family:JetBrains Mono,monospace;font-weight:700;color:#1A3A78">' + sym2 + '</td>';
      card += '<td style="padding:6px 8px;color:#475569">' + name + '</td>';
      card += '<td style="padding:6px 8px;text-align:right;font-family:JetBrains Mono,monospace">' + (price != null ? (data.csym || S) + fNum(price, 2) : '—') + '</td>';
      card += '<td style="padding:6px 8px;text-align:right;font-family:JetBrains Mono,monospace;font-weight:700">' + (score != null ? fNum(score, 0) : '—') + '</td>';
      card += '<td style="padding:6px 8px;text-align:right;font-family:JetBrains Mono,monospace">' + fPct(upside, 1) + '</td>';
      card += '<td style="padding:6px 8px;text-align:center;font-weight:800;color:' + vC + ';font-size:9px">' + bucketLabel + '</td>';
      card += '</tr>';
    });
    card += '</tbody></table>';
    if (rows.length > 10) card += '<div style="margin-top:6px;font-size:9px;color:#94a3b8;text-align:center">Showing top 10 of ' + rows.length + ' matches.</div>';
    card += '</div></div>';
    return card;
  };
  h += _renderXM(xmCross, 'Cross-Market Scanner', '🌐', '#2563eb', reg === 'US' ? 'Indian market' : 'US market');
  h += _renderXM(xmSame, 'Similar Stocks — Same Region', '🔍', '#1A3A78', reg === 'US' ? 'US market peers' : 'Indian market peers');

  // ═══ 5. 360° CYCLE ANALYSIS — backend returns {sections:[{section:'synthesis',verdict,layman,metrics}, ...]} ═══
  h += '<div style="margin:18px 0;border:1px solid #e2e8f0;border-radius:14px;background:#fff;overflow:hidden">';
  h += '<div style="padding:12px 18px;background:#7c3aed14;border-bottom:2px solid #7c3aed40"><div style="font-size:13px;font-weight:900;color:#7c3aed;font-family:Sora,sans-serif">🔄 360° Cycle Analysis — Phase · Position · Recommendation</div></div>';
  if (cy && cy.success && Array.isArray(cy.sections) && cy.sections.length > 0) {
    var syn = cy.sections.find(function(s){return s.section === 'synthesis';}) || {};
    var synColor = syn.verdict_color === 'green' ? '#10b981' : syn.verdict_color === 'yellow' ? '#f59e0b' : syn.verdict_color === 'red' ? '#dc2626' : '#7c3aed';

    h += '<div style="padding:14px 18px">';

    // Synthesis verdict pill + score line
    if (syn.verdict) {
      h += '<div style="margin-bottom:12px;display:flex;align-items:center;gap:14px;flex-wrap:wrap">';
      h += '<div style="padding:8px 16px;background:' + synColor + ';color:#fff;border-radius:8px;font-size:14px;font-weight:900;font-family:Sora,sans-serif">' + fStr(syn.verdict) + '</div>';
      if (syn.metrics && typeof syn.metrics.net_score === 'number') {
        h += '<div style="font-size:11px;color:#64748b">+' + syn.metrics.positive_signals + ' / −' + syn.metrics.negative_signals + ' · net <strong style="color:#0f172a;font-family:JetBrains Mono,monospace">' + (syn.metrics.net_score >= 0 ? '+' : '') + syn.metrics.net_score + '</strong></div>';
      }
      h += '</div>';
    }

    // Plain-English summary
    if (syn.layman) {
      h += '<div style="padding:12px 14px;background:#faf5ff;border-left:3px solid #7c3aed;border-radius:0 6px 6px 0;font-size:11px;color:#0f172a;line-height:1.6;margin-bottom:12px">' + fStr(syn.layman) + '</div>';
    }

    // Sub-sections summary (top 6, excluding synthesis itself)
    var others = cy.sections.filter(function(s){return s.section !== 'synthesis' && (s.verdict || s.phase || s.summary);}).slice(0, 6);
    if (others.length > 0) {
      h += '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:8px">';
      others.forEach(function(sec) {
        var secColor = sec.verdict_color === 'green' ? '#10b981' : sec.verdict_color === 'red' ? '#dc2626' : sec.verdict_color === 'yellow' ? '#f59e0b' : '#7c3aed';
        var label = (sec.title || sec.section || '').toString().replace(/_/g,' ').replace(/\b\w/g, function(c){return c.toUpperCase();});
        h += '<div style="padding:9px 11px;border-radius:7px;background:#fafbfc;border:1px solid #e2e8f0;border-left:3px solid ' + secColor + '">';
        h += '<div style="font-size:9px;color:#64748b;font-weight:800;letter-spacing:0.3px;text-transform:uppercase">' + label + '</div>';
        var secVal = fStr(sec.verdict || sec.phase || sec.summary);
        if (secVal) h += '<div style="font-size:11px;font-weight:700;color:#0f172a;margin-top:3px;line-height:1.4">' + secVal.substring(0, 80) + '</div>';
        h += '</div>';
      });
      h += '</div>';
    }
    h += '</div>';
  } else {
    h += '<div style="padding:14px 18px;font-size:11px;color:#7f1d1d">⚠ ' + ((cy && cy.error) || '360° Cycle endpoint unavailable') + '</div>';
  }
  h += '</div>';

  h += '<div style="margin-top:16px;padding:10px 14px;background:#f8fafc;border-radius:8px;font-size:9px;color:#64748b;text-align:center;font-family:JetBrains Mono,monospace">END OF APPENDIX · Generated ' + new Date().toISOString() + '</div>';
  h += '</div>'; // close #csPdfAppendix

  return h;
};

window._csOpenPrintWindow = function(reportEl, ticker) {
  try {
    ticker = ticker || (window._ddLastSymbol || 'REPORT').toUpperCase();
    if (!reportEl) reportEl = document.getElementById('deResult');
    if (!reportEl) { alert('No report to print.'); return false; }
    var styles = '';
    document.querySelectorAll('link[rel="stylesheet"], style').forEach(function(node) { styles += node.outerHTML; });
    var body = reportEl.innerHTML.replace(/<details(?!\s+open)(\s[^>]*)?>/g, '<details open$1>');
    var w = window.open('', '_blank');
    if (!w) { alert('Pop-up blocked. Allow pop-ups for celesys.ai, then try Export/Print again.'); return false; }
    var cover = '<div style="border-bottom:3px solid #1A3A78;padding-bottom:10px;margin-bottom:18px">' +
      '<div style="font-size:24px;font-weight:900;color:#1A3A78;font-family:Sora,sans-serif">CELESYS \u00b7 ' + ticker + '</div>' +
      '<div style="font-size:11px;color:#64748b">Institutional Deep Due Diligence \u00b7 Generated ' + new Date().toLocaleString() + '</div></div>';
    var disc = '<div style="margin-top:24px;padding:14px 18px;background:#fffbeb;border:1px solid #fde68a;border-radius:10px;color:#78350f;font-size:11px;line-height:1.6">' +
      '<b>Important disclaimer</b><br>This report is research output, not investment advice. All figures sourced from public financial data (Yahoo Finance, Finnhub, NSE) and may have lag or gaps. Past performance does not predict future returns. Always conduct your own due diligence before any trade. Celesys provides analytical frameworks; investment decisions remain solely your responsibility.</div>';
    var pcss = '<style>@page{margin:14mm}body{background:#fff!important;margin:0;padding:20px;font-family:Inter,system-ui,sans-serif;color:#0f172a}#csPrintRoot{max-width:900px;margin:0 auto}details{display:block!important}details>summary{cursor:default}#csDDToolbar,.no-print{display:none!important}</style>';
    w.document.write('<!doctype html><html><head><meta charset="utf-8"><title>Celesys ' + ticker + ' DD</title>' +
      styles + pcss + '</head><body><div id="csPrintRoot">' + cover + body + disc +
      '</div><scr' + 'ipt>setTimeout(function(){try{window.focus();window.print();}catch(e){}},900);<\/scr' + 'ipt></body></html>');
    w.document.close();
    return true;
  } catch (err) {
    alert('Print fallback failed: ' + (err.message || err));
    return false;
  }
};

window._csExportPDF = async function() {
  var btn = event && event.currentTarget;

  // Check libraries are loaded
  if (typeof window.jspdf === 'undefined' || typeof window.html2canvas === 'undefined') {
    alert('PDF library not loaded yet. Please wait a moment and try again.');
    return;
  }

  // Validate report exists
  var reportEl = document.getElementById('deResult');
  if (!reportEl || reportEl.innerHTML.length < 1000) {
    alert('No report to export. Generate a Deep DD report first.');
    return;
  }

  // Try to detect ticker symbol from report for filename
  var ticker = (window._ddLastSymbol || 'REPORT').toUpperCase();
  var dateStr = new Date().toISOString().slice(0, 10);
  var filename = 'Celesys_DD_' + ticker + '_' + dateStr + '.pdf';

  // Show loading state
  if (btn) {
    btn.classList.add('is-loading');
    var origHtml = btn.innerHTML;
    btn.innerHTML = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg><span style="font-size:10px;font-weight:700">…</span>';
  }

  try {
    // Hide toolbar from capture
    var tb = document.getElementById('csDDToolbar');
    var tbDisplay = tb ? tb.style.display : '';
    if (tb) tb.style.display = 'none';

    // r63.77.0: Build PDF appendix (Wealth Pro, Market Pulse, Cross-Market x2, 360° Cycle)
    // Update button text to show progress
    if (btn) {
      btn.innerHTML = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg><span style="font-size:10px;font-weight:700">running scans…</span>';
    }
    var appendixHtml = '';
    try {
      if (typeof window._csBuildPDFAppendix === 'function') {
        appendixHtml = await window._csBuildPDFAppendix(ticker, window._deRegion || 'US');
      }
    } catch (apxErr) {
      console.warn('[PDF] Appendix build failed (continuing without it):', apxErr);
      appendixHtml = '<div style="margin-top:24px;padding:12px;background:#fef2f2;border:1px solid #fecaca;border-radius:8px;font-size:11px;color:#7f1d1d">⚠ PDF appendix unavailable: ' + (apxErr.message || apxErr) + '</div>';
    }

    // Inject appendix into #deResult so html2canvas captures it
    var appendixContainer = null;
    if (appendixHtml) {
      appendixContainer = document.createElement('div');
      appendixContainer.id = 'csPdfAppendixWrapper';
      appendixContainer.innerHTML = appendixHtml;
      reportEl.appendChild(appendixContainer);
    }

    if (btn) {
      btn.innerHTML = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg><span style="font-size:10px;font-weight:700">rendering…</span>';
    }

    // Capture report as canvas. CRITICAL: cap the scale so the resulting canvas
    // never exceeds the browser's max canvas size. A tall report (16 sections +
    // appendix) at scale 1.5 silently produces a BLANK/white canvas in
    // html2canvas 1.4.1 — that was the "blank PDF page 2" bug. 10800px on the
    // longest side stays safe across Chrome / Firefox / Safari.
    var _fullH = reportEl.scrollHeight || reportEl.offsetHeight || 1;
    var _fullW = reportEl.scrollWidth || reportEl.offsetWidth || 1;
    var _MAXSIDE = 10800;
    var _scale = Math.min(1.5, _MAXSIDE / _fullH, _MAXSIDE / _fullW);
    if (!isFinite(_scale) || _scale <= 0) _scale = 1;
    var canvas = await window.html2canvas(reportEl, {
      scale: _scale,
      useCORS: true,
      allowTaint: false,
      backgroundColor: '#ffffff',
      logging: false,
      windowWidth: _fullW,
      windowHeight: _fullH,
    });

    // Guard: a zero-dimension canvas means the capture failed (too large/complex).
    // Throw so the catch can fall back to the native print window.
    if (!canvas || !canvas.width || !canvas.height) {
      throw new Error('content capture came back empty (report too large for image export)');
    }

    // Remove appendix from DOM (user's view returns to normal)
    if (appendixContainer && appendixContainer.parentNode) {
      appendixContainer.parentNode.removeChild(appendixContainer);
    }

    // Restore toolbar
    if (tb) tb.style.display = tbDisplay;

    var imgData = canvas.toDataURL('image/jpeg', 0.92);

    // Build PDF — A4 portrait, mm units
    var pdf = new window.jspdf.jsPDF({
      orientation: 'portrait',
      unit: 'mm',
      format: 'a4',
    });

    var pageW = pdf.internal.pageSize.getWidth();   // 210mm
    var pageH = pdf.internal.pageSize.getHeight();  // 297mm
    var margin = 12;
    var contentW = pageW - (margin * 2);            // 186mm

    // ─── Cover page ───────────────────────────────────────────────
    // Navy header band
    pdf.setFillColor(26, 58, 120);  // #1A3A78
    pdf.rect(0, 0, pageW, 32, 'F');

    pdf.setTextColor(255, 255, 255);
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(22);
    pdf.text('CELESYS', margin, 14);
    pdf.setFontSize(10);
    pdf.setFont('helvetica', 'normal');
    pdf.text('INSTITUTIONAL DEEP DUE DILIGENCE', margin, 21);
    pdf.setFontSize(8);
    pdf.text('Generated ' + new Date().toLocaleString(), margin, 27);

    // Ticker block
    pdf.setTextColor(15, 23, 42);  // #0f172a
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(48);
    pdf.text(ticker, margin, 60);

    // Subtitle
    pdf.setFontSize(11);
    pdf.setFont('helvetica', 'normal');
    pdf.setTextColor(100, 116, 139);  // #64748b
    pdf.text('Multi-factor synthesis · 16-section institutional report', margin, 68);

    // Description block
    pdf.setDrawColor(226, 232, 240);
    pdf.line(margin, 75, pageW - margin, 75);

    pdf.setFontSize(9);
    pdf.setTextColor(71, 85, 105);
    var bodyLines = [
      'This report contains the full Deep Due Diligence analysis for ' + ticker + ',',
      'generated by the Celesys institutional research engine. Sections include:',
      '',
      '  • Bottom Line verdict (multi-factor synthesis)',
      '  • Investment thesis with DCF valuation',
      '  • Financial health snapshot',
      '  • Sector context vs benchmark ETF',
      '  • Porter\'s Five Forces analysis',
      '  • SWOT framework',
      '  • Catalysts: earnings + analyst targets',
      '  • Risk matrix with red flags',
      '  • Insider activity (Form 4 filings)',
      '  • Institutional ownership (13F holders)',
      '  • Earnings history with surprise tracking',
      '  • Layman blocks for every metric',
    ];
    var lineY = 85;
    bodyLines.forEach(function(line) {
      pdf.text(line, margin, lineY);
      lineY += 4.5;
    });

    // Disclaimer block
    pdf.setFillColor(255, 251, 235);  // amber-50
    pdf.setDrawColor(253, 230, 138);  // amber-200
    pdf.roundedRect(margin, pageH - 50, contentW, 32, 2, 2, 'FD');
    pdf.setFontSize(8);
    pdf.setTextColor(120, 53, 15);  // amber-900
    pdf.setFont('helvetica', 'bold');
    pdf.text('Important disclaimer', margin + 4, pageH - 43);
    pdf.setFont('helvetica', 'normal');
    pdf.setFontSize(7.5);
    var disclaimerLines = [
      'This report is research output, not investment advice. All figures sourced from public financial',
      'data (Yahoo Finance, Finnhub, NSE) and may have lag or gaps. Past performance does not predict',
      'future returns. Always conduct your own due diligence before any trade. Celesys provides analytical',
      'frameworks; investment decisions remain solely your responsibility.',
    ];
    var disclaimerY = pageH - 36;
    disclaimerLines.forEach(function(line) {
      pdf.text(line, margin + 4, disclaimerY);
      disclaimerY += 3.5;
    });

    // Footer
    pdf.setFontSize(7);
    pdf.setTextColor(148, 163, 184);
    pdf.text('celesys.ai · ' + (window.CELESYS_VERSION || 'v4.63') + ' · Page 1 of report', margin, pageH - 6);

    // ─── Report pages ─────────────────────────────────────────────
    pdf.addPage();

    // Calculate scaled image dimensions
    var imgW = contentW;
    var imgH = (canvas.height * imgW) / canvas.width;
    var availableH = pageH - (margin * 2) - 8;  // leave room for footer

    // If image fits on one page, just add it
    if (imgH <= availableH) {
      pdf.addImage(imgData, 'JPEG', margin, margin, imgW, imgH);
      pdf.setFontSize(7);
      pdf.setTextColor(148, 163, 184);
      pdf.text('celesys.ai · ' + ticker + ' DD · Page 2', margin, pageH - 6);
    } else {
      // Multi-page: slice the image
      var sliceCanvas = document.createElement('canvas');
      sliceCanvas.width = canvas.width;
      var sliceHeightPx = Math.floor((availableH * canvas.width) / contentW);
      sliceCanvas.height = sliceHeightPx;
      var sctx = sliceCanvas.getContext('2d');

      var totalSlices = Math.ceil(canvas.height / sliceHeightPx);
      for (var i = 0; i < totalSlices; i++) {
        if (i > 0) pdf.addPage();
        var srcY = i * sliceHeightPx;
        var srcH = Math.min(sliceHeightPx, canvas.height - srcY);

        sctx.fillStyle = '#ffffff';
        sctx.fillRect(0, 0, sliceCanvas.width, sliceCanvas.height);
        sctx.drawImage(canvas, 0, srcY, canvas.width, srcH, 0, 0, canvas.width, srcH);

        var slicedDataUrl = sliceCanvas.toDataURL('image/jpeg', 0.92);
        var renderedH = (srcH * contentW) / canvas.width;
        pdf.addImage(slicedDataUrl, 'JPEG', margin, margin, contentW, renderedH);

        // Footer on each page
        pdf.setFontSize(7);
        pdf.setTextColor(148, 163, 184);
        pdf.text(
          'celesys.ai · ' + ticker + ' DD · Page ' + (i + 2) + ' of ' + (totalSlices + 1),
          margin,
          pageH - 6
        );
      }
    }

    // Save
    pdf.save(filename);

    if (btn) {
      btn.classList.remove('is-loading');
      btn.innerHTML = origHtml;
    }
  } catch (e) {
    if (btn) {
      btn.classList.remove('is-loading');
      btn.innerHTML = origHtml || btn.innerHTML;
    }
    var tb2 = document.getElementById('csDDToolbar');
    if (tb2) tb2.style.display = '';
    console.error('PDF export failed:', e);
    // Graceful fallback: self-contained print window (renders the real DOM — no
    // canvas-size limit, faithful CSS, selectable text). Guarantees output via
    // the browser's "Save as PDF".
    if (confirm('Image-based PDF export hit a limit (' + (e.message || e) + ').\n\nOpen a clean print view instead? Choose "Save as PDF" in the dialog for the full report.')) {
      window._csOpenPrintWindow(reportEl, ticker);
    }
  }
};


// ═══════════════════════════════════════════════════════════════════
// PRINT — uses native browser print dialog
// ═══════════════════════════════════════════════════════════════════
window._csPrintReport = function() {
  var reportEl = document.getElementById('deResult');
  if (!reportEl || reportEl.innerHTML.length < 1000) {
    alert('No report to print. Generate a Deep DD report first.');
    return;
  }
  // CSS @media print rule in toolbar styles already hides the toolbar
  window.print();
};


// ═══════════════════════════════════════════════════════════════════
// COPY URL — copies current page URL with ticker hash for sharing
// ═══════════════════════════════════════════════════════════════════
window._csCopyReportURL = function(btn) {
  var ticker = (window._ddLastSymbol || '').toUpperCase();
  var url = window.location.origin + window.location.pathname + '#dd/' + ticker;

  // Try modern clipboard API first
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(url).then(function() {
      _csTbFlashSuccess(btn, 'Copied!');
    }).catch(function() {
      _csTbFallbackCopy(url, btn);
    });
  } else {
    _csTbFallbackCopy(url, btn);
  }
};

function _csTbFallbackCopy(text, btn) {
  // Fallback for older browsers
  var ta = document.createElement('textarea');
  ta.value = text;
  ta.style.position = 'fixed';
  ta.style.opacity = '0';
  document.body.appendChild(ta);
  ta.select();
  try {
    document.execCommand('copy');
    _csTbFlashSuccess(btn, 'Copied!');
  } catch (e) {
    alert('Could not copy. URL is: ' + text);
  }
  document.body.removeChild(ta);
}

function _csTbFlashSuccess(btn, message) {
  if (!btn) return;
  var orig = btn.getAttribute('data-tooltip');
  btn.setAttribute('data-tooltip', message || 'Copied!');
  btn.style.background = '#059669';
  btn.style.color = '#fff';
  btn.style.borderColor = '#059669';
  setTimeout(function() {
    btn.setAttribute('data-tooltip', orig);
    btn.style.background = '';
    btn.style.color = '';
    btn.style.borderColor = '';
  }, 1400);
}


// ═══════════════════════════════════════════════════════════════════
// AUTO-INJECT: inject toolbar after DD report renders
// ═══════════════════════════════════════════════════════════════════
// We hook into both _renderReportLegacy and _renderReportShellAladdin paths
// by polling deResult for content changes. Lightweight, runs once per render.
(function() {
  var lastInnerHTML = '';
  var checkCount = 0;
  var pollHandle = null;

  function checkAndInject() {
    var el = document.getElementById('deResult');
    if (!el) return;
    if (el.innerHTML === lastInnerHTML) return;
    lastInnerHTML = el.innerHTML;
    // Wait one tick for DOM to settle
    setTimeout(function() {
      if (typeof window._csInjectDDToolbar === 'function') {
        window._csInjectDDToolbar();
      }
    }, 50);
  }

  // r63.9: Start polling — runs forever as backup if renderReport wrapper fails
  function startPolling() {
    if (pollHandle) return;
    pollHandle = setInterval(checkAndInject, 800);
    // No timeout — polls run for the lifetime of the page
  }

  // Hook into existing tab dispatcher — when user is on DD tab, start polling
  document.addEventListener('DOMContentLoaded', function() {
    startPolling();
  });
  if (document.readyState !== 'loading') {
    startPolling();
  }
})();



// ═══════════════════════════════════════════════════════════════════
// r63.6: Find Similar Stocks — modal + scanner UI
// ═══════════════════════════════════════════════════════════════════
// Adds a "🔍 Find Similar" button to the Deep DD report. When clicked,
// opens a modal that scans the universe and shows results bucketed by
// price tier with similarity scores and matching factors.

window._csFindSimilarOpen = function(refTicker, region) {
  if (!refTicker) {
    refTicker = (window._ddLastSymbol || '').toUpperCase();
  }
  if (!region) region = (window._ddLastRegion || 'US').toUpperCase();
  if (!refTicker) {
    alert('No reference ticker. Generate a Deep DD report first.');
    return;
  }

  // Remove any existing modal
  var existing = document.getElementById('csFindSimilarModal');
  if (existing) existing.remove();

  // Build modal shell
  var modal = document.createElement('div');
  modal.id = 'csFindSimilarModal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,0.7);z-index:9999;display:flex;align-items:flex-start;justify-content:center;padding:40px 20px;overflow-y:auto;font-family:Inter,sans-serif;animation:csFsFadeIn 200ms ease';
  modal.innerHTML = '' +
    '<div style="background:#fff;border-radius:14px;max-width:980px;width:100%;box-shadow:0 20px 60px rgba(0,0,0,0.4);overflow:hidden">' +
      // Header
      '<div style="padding:20px 28px;background:linear-gradient(135deg,#0A1628,#1A3A78);color:#fff;display:flex;justify-content:space-between;align-items:center">' +
        '<div>' +
          '<div style="font-size:18px;font-weight:800;font-family:Sora,sans-serif">🔍 Find Similar Stocks</div>' +
          '<div style="font-size:11px;color:rgba(255,255,255,0.7);margin-top:3px">Reference: <strong>' + refTicker + '</strong> · Region: ' + region + ' · Scanning curated universe</div>' +
        '</div>' +
        '<button onclick="document.getElementById(\'csFindSimilarModal\').remove()" style="background:rgba(255,255,255,0.15);color:#fff;border:none;width:32px;height:32px;border-radius:8px;font-size:18px;cursor:pointer">✕</button>' +
      '</div>' +
      // Body
      '<div id="csFsBody" style="padding:24px 28px;min-height:200px">' +
        '<div id="csFsLoading" style="text-align:center;padding:40px 20px">' +
          '<div style="display:inline-block;width:36px;height:36px;border:3px solid #e2e8f0;border-top-color:#1A3A78;border-radius:50%;animation:csFsSpin 0.8s linear infinite"></div>' +
          '<div style="margin-top:14px;font-size:13px;color:#475569;font-weight:600">Computing reference profile…</div>' +
          '<div id="csFsStatus" style="margin-top:6px;font-size:11px;color:#94a3b8">Then scanning ' + (region === 'US' ? '~80' : '~110') + ' candidates. Cold scan: ~2-4 min. Warm cache: instant.</div>' +
          '<div id="csFsTimer" style="margin-top:8px;font-size:10px;color:#64748b;font-variant-numeric:tabular-nums">Elapsed: 0s</div>' +
        '</div>' +
      '</div>' +
      // Footer
      '<div style="padding:14px 28px;background:#f8fafc;border-top:1px solid #e2e8f0;font-size:10px;color:#64748b;display:flex;justify-content:space-between;align-items:center">' +
        '<span>Similarity = 40% verdict + 35% fundamentals + 25% risk/momentum</span>' +
        '<span id="csFsScanInfo"></span>' +
      '</div>' +
    '</div>';
  
  document.body.appendChild(modal);
  
  // Inject styles once
  if (!document.getElementById('csFsStyles')) {
    var style = document.createElement('style');
    style.id = 'csFsStyles';
    style.textContent =
      '@keyframes csFsSpin { to { transform: rotate(360deg); } }' +
      '@keyframes csFsFadeIn { from { opacity: 0; } to { opacity: 1; } }';
    document.head.appendChild(style);
  }
  
  // Start elapsed timer
  var t0 = Date.now();
  var timerHandle = setInterval(function() {
    var el = document.getElementById('csFsTimer');
    if (el) {
      var sec = Math.floor((Date.now() - t0) / 1000);
      el.textContent = 'Elapsed: ' + sec + 's' + (sec > 30 ? ' (cold cache scan, please wait)' : '');
    }
  }, 1000);
  
  // Get email from app state
  var email = (window._verifiedEmail || window._authedEmail || window.localStorage.getItem('email') || '').trim();
  
  // Fetch
  fetch('/api/find-similar-stocks?reference=' + encodeURIComponent(refTicker) + '&region=' + region + '&email=' + encodeURIComponent(email))
    .then(function(r) { return r.json(); })
    .then(function(data) {
      clearInterval(timerHandle);
      if (!data.success) {
        document.getElementById('csFsBody').innerHTML =
          '<div style="text-align:center;padding:40px;color:#dc2626">' +
            '<div style="font-size:18px;font-weight:700;margin-bottom:8px">⚠️ Could not complete scan</div>' +
            '<div style="font-size:12px;color:#475569">' + (data.error || 'Unknown error') + '</div>' +
          '</div>';
        return;
      }
      _csFsRender(data);
    })
    .catch(function(err) {
      clearInterval(timerHandle);
      document.getElementById('csFsBody').innerHTML =
        '<div style="text-align:center;padding:40px;color:#dc2626">' +
          '<div style="font-size:18px;font-weight:700;margin-bottom:8px">⚠️ Network error</div>' +
          '<div style="font-size:12px;color:#475569">' + err.message + '</div>' +
        '</div>';
    });
};

function _csFsRender(data) {
  var ref = data.reference || {};
  var buckets = data.buckets || {};
  var bucketOrder = ['penny', 'low', 'mid', 'high', 'ultra'];
  
  var html = '';
  
  // Reference summary
  html += '<div style="background:linear-gradient(135deg,#F0F4FF,#E0E7FF);border:1px solid #c7d2fe;border-radius:10px;padding:14px 18px;margin-bottom:18px">';
  html += '<div style="font-size:9px;color:#4338ca;font-weight:800;letter-spacing:1.2px;margin-bottom:4px">REFERENCE PROFILE</div>';
  html += '<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px">';
  html += '<div><span style="font-size:18px;font-weight:900;color:#1A3A78;font-family:Sora,sans-serif">' + ref.ticker + '</span>';
  if (ref.name && ref.name !== ref.ticker) html += ' <span style="font-size:11px;color:#64748b">' + _csEscape(ref.name) + '</span>';
  html += '</div>';
  html += '<div style="font-size:11px;color:#475569">';
  html += '<strong>' + ref.currency_symbol + (ref.price || 0).toFixed(2) + '</strong> · ';
  html += 'Score <strong>' + Math.round(ref.verdict_score) + '/100</strong> (' + (ref.verdict_label || '—') + ')';
  if (ref.sector) html += ' · ' + _csEscape(ref.sector);
  html += '</div>';
  html += '</div>';
  html += '</div>';
  
  // Bucket sections
  for (var i = 0; i < bucketOrder.length; i++) {
    var bkey = bucketOrder[i];
    var bucket = buckets[bkey];
    if (!bucket) continue;
    var results = bucket.results || [];
    
    html += '<div style="margin-bottom:18px">';
    html += '<div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:8px;padding:0 4px">';
    html += '<div style="font-size:13px;font-weight:800;color:#0f172a;font-family:Sora,sans-serif">' + bucket.label + '</div>';
    html += '<div style="font-size:10px;color:#94a3b8;font-weight:600">' + (results.length === 0 ? 'No matches' : results.length + ' match' + (results.length === 1 ? '' : 'es')) + '</div>';
    html += '</div>';
    
    if (results.length === 0) {
      html += '<div style="background:#f8fafc;border:1px dashed #e2e8f0;border-radius:8px;padding:14px;text-align:center;font-size:11px;color:#94a3b8">No similar stocks in this price tier within scanned universe</div>';
    } else {
      html += '<div style="display:grid;grid-template-columns:1fr;gap:8px">';
      for (var j = 0; j < results.length; j++) {
        var r = results[j];
        var simColor = r.similarity >= 75 ? '#059669' : (r.similarity >= 60 ? '#0891b2' : '#64748b');
        html += '<div style="border:1px solid #e2e8f0;border-radius:8px;padding:12px 14px;background:#fff;display:flex;justify-content:space-between;align-items:center;gap:14px">';
        html += '<div style="flex:1;min-width:0">';
        html += '<div style="display:flex;align-items:center;gap:8px;margin-bottom:3px">';
        html += '<span style="font-size:13px;font-weight:800;color:#1A3A78;font-family:Sora,sans-serif">' + r.ticker + '</span>';
        html += '<span style="font-size:9px;color:#475569;background:#f1f5f9;padding:2px 6px;border-radius:4px;font-weight:600">' + r.currency_symbol + (r.price || 0).toFixed(2) + '</span>';
        html += '<span style="font-size:9px;color:#fff;background:#1A3A78;padding:2px 6px;border-radius:4px;font-weight:700">' + Math.round(r.verdict_score) + '/100</span>';
        if (r.sector) html += '<span style="font-size:9px;color:#94a3b8">' + _csEscape(r.sector) + '</span>';
        html += '</div>';
        if (r.matches && r.matches.length > 0) {
          html += '<div style="font-size:10px;color:#64748b">' + r.matches.map(_csEscape).join(' · ') + '</div>';
        }
        html += '</div>';
        html += '<div style="text-align:right">';
        html += '<div style="font-size:18px;font-weight:900;color:' + simColor + ';font-variant-numeric:tabular-nums">' + Math.round(r.similarity) + '</div>';
        html += '<div style="font-size:8px;color:#94a3b8;letter-spacing:1px">SIM</div>';
        html += '</div>';
        html += '</div>';
      }
      html += '</div>';
    }
    
    html += '</div>';
  }
  
  document.getElementById('csFsBody').innerHTML = html;
  
  var scanInfo = document.getElementById('csFsScanInfo');
  if (scanInfo) {
    scanInfo.textContent = 'Scanned ' + data.scanned + ' · ' + data.valid + ' valid · ' + data.elapsed_sec + 's' + (data._cached ? ' (cached)' : '');
  }
}

function _csEscape(s) {
  if (s == null) return '';
  return String(s).replace(/[&<>"']/g, function(c) {
    return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
  });
}


// Auto-inject "Find Similar" button into Deep DD toolbar
window._csInjectFindSimilarButton = function() {
  var bar = document.getElementById('csDDToolbar');
  if (!bar) return;
  if (bar.querySelector('[data-action="find-similar"]')) return;  // already injected
  
  var btn = document.createElement('button');
  btn.setAttribute('data-action', 'find-similar');
  btn.setAttribute('data-tooltip', 'Find similar stocks across price tiers');
  btn.setAttribute('aria-label', 'Find Similar Stocks');
  btn.className = 'cs-tb-btn';
  btn.innerHTML =
    '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>' +
    '<span style="font-size:10px;font-weight:700;letter-spacing:0.4px">SIMILAR</span>';
  btn.onclick = function() { window._csFindSimilarOpen(); };
  
  // Insert as first button so it\'s prominent
  bar.insertBefore(btn, bar.firstChild);
};

// Hook into existing DD toolbar polling — runs after toolbar appears
(function() {
  // r63.9: removed 10-min timeout. Polling runs forever as backup if renderReport
  // wrapper fails to fire. Cost: trivial (one getElementById per second).
  setInterval(function() {
    if (document.getElementById('csDDToolbar')) {
      window._csInjectFindSimilarButton();
    }
  }, 1000);
})();



